:root {
  color-scheme: light;
  --color-canvas: #f5f7fc;
  --color-surface: #ffffff;
  --color-surface-raised: #ffffff;
  --color-text-primary: #101828;
  --color-text-secondary: #475467;
  --color-text-tertiary: #667085;
  --color-border: #e3e8f2;
  --color-brand: #2149d8;
  --color-brand-strong: #1739b1;
  --color-brand-subtle: #eaf0ff;
  --color-on-brand: #ffffff;
  --color-focus: #4169e1;
  --color-focus-ring: rgb(65 105 225 / 35%);
  --color-success: #197a58;
  --color-success-subtle: #eaf7f1;
  --color-warning: #8a5a0c;
  --color-warning-subtle: #fff4df;
  --color-danger: #b42318;
  --color-danger-subtle: #fef3f2;
  --color-ink-rgb: 16 24 40;
  --color-brand-rgb: 33 73 216;
  --color-avatar-text: #405495;
  --color-avatar-surface: #e7edff;
  --color-avatar-user: #6174a8;
  --color-nav-hover: #f7f8fc;
  --color-plan-surface: #fbfaff;
  --color-plan-border: #e9e5fa;
  --color-progress-track: #e5e5f2;
  --color-progress: #8a74d6;
  --color-plan-link: #735bbf;
  --color-topbar: rgb(255 255 255 / 68%);
  --color-breadcrumb: #c3c8d2;
  --color-note-rule: #b9c6f9;
  --color-thumbnail-accent: #aebdf4;
  --color-stage-blue: #eef4ff;
  --color-stage-blue-border: #dfe9ff;
  --color-stage-lilac: #f4f0ff;
  --color-stage-lilac-border: #e9e2ff;
  --color-stage-mint: #ebf8f3;
  --color-stage-mint-border: #d9f0e7;
  --color-row-hover: #fafbfe;
  --color-status-neutral: #f1f3f7;
  --color-connection-border: #d3d9e5;
  --color-connection-dot: #c5cbd7;
  --color-connection-success-border: #c8ebdd;
  --color-connection-success-surface: #edfaf5;
  --color-status-background: #f5f6f9;
  --color-offline-surface: #fff5e3;
  --color-control-border: #d7def8;
  --color-row-arrow: #b7bfce;
  --color-skeleton: #e7eaf1;
  --color-white: #ffffff;
  --font-family-sans:
    Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  --font-size-xs: 10px;
  --font-size-sm: 11px;
  --font-size-md: 12px;
  --font-size-lg: 16px;
  --font-size-xl: 19px;
  --font-size-2xl: 22px;
  --font-size-3xl: 24px;
  --font-size-display: clamp(38px, 4vw, 60px);
  --font-weight-regular: 400;
  --font-weight-medium: 600;
  --font-weight-semibold: 700;
  --font-weight-bold: 800;
  --line-height-tight: 1.03;
  --line-height-body: 1.55;
  --line-height-relaxed: 1.65;
  --space-1: 4px;
  --space-2: 8px;
  --space-3: 12px;
  --space-4: 16px;
  --space-5: 20px;
  --space-6: 24px;
  --space-7: 32px;
  --space-8: 40px;
  --space-9: 48px;
  --space-10: 56px;
  --space-11: 72px;
  --radius-sm: 5px;
  --radius-md: 8px;
  --radius-lg: 10px;
  --radius-xl: 16px;
  --radius-pill: 999px;
  --shadow-sm: 0 5px 20px rgb(var(--color-ink-rgb) / 3%);
  --shadow-md: 0 12px 32px rgb(var(--color-ink-rgb) / 6%);
  --shadow-focus: 0 0 0 3px var(--color-focus-ring);
  --shadow-button: 0 9px 18px rgb(var(--color-brand-rgb) / 18%);
  --shadow-hero-action: 0 10px 24px rgb(0 0 0 / 16%);
  --color-hero-surface: #011369;
  --color-hero-copy: #cbd5ff;
  --color-hero-muted: #b9c9ff;
  --color-hero-ink: #011369;
  --motion-duration-fast: 150ms;
  --motion-duration-normal: 200ms;
  --motion-duration-skeleton: 1.3s;
  --motion-ease-standard: cubic-bezier(0.2, 0.8, 0.2, 1);
  --z-base: 0;
  --z-sidebar: 10;
  --z-sticky: 20;
  --z-overlay: 100;
  --ink: var(--color-text-primary);
  --muted: var(--color-text-secondary);
  --subtle: var(--color-text-tertiary);
  --line: var(--color-border);
  --surface: var(--color-surface);
  --canvas: var(--color-canvas);
  --brand: var(--color-brand);
  --brand-dark: var(--color-brand-strong);
  --brand-soft: var(--color-brand-subtle);
  --blue-soft: var(--color-stage-blue);
  --lilac-soft: var(--color-stage-lilac);
  --mint-soft: var(--color-stage-mint);
  --success: var(--color-success);
  --warning: var(--color-warning);
  --radius: var(--radius-xl);
  --shadow: var(--shadow-md);
}

/* Live feature-detail parity for the editor and personalization routes. These
   pages intentionally share the same five-part composition as the public
   reference: card-based primary features, optional dark capabilities, use
   cases, feature discovery, FAQ, trust, then the global footer. */
.reference-feature-page {
  --marketing-blue: #444ce7;
  --marketing-blue-dark: #3538cd;
  --marketing-ink: #1d2735;
  --marketing-muted: #4b5563;
  --marketing-line: #d5d7da;
  --reference-feature-ink: #101a31;
  --reference-feature-muted: #4b5563;
  min-height: 100vh;
  overflow: hidden;
  color: var(--reference-feature-ink);
  background: #fff;
}

.reference-feature-page .reference-feature-hero {
  position: relative;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  gap: 64px;
  width: min(1216px, calc(100% - 64px));
  max-width: none;
  height: 676px;
  min-height: 676px;
  margin: -74px auto 0;
  padding: 160px 0 96px;
  box-sizing: border-box;
  align-items: center;
  background: #fff;
}

.reference-feature-page .reference-feature-hero::before {
  position: absolute;
  top: -96px;
  left: -96px;
  z-index: 0;
  width: 384px;
  height: 384px;
  border-radius: 999px;
  background: linear-gradient(135deg, #c084fc, #818cf8);
  content: "";
  filter: blur(64px);
  opacity: 0.3;
  pointer-events: none;
}

.reference-feature-page .reference-feature-hero::after {
  position: absolute;
  right: -96px;
  bottom: -96px;
  z-index: 0;
  width: 384px;
  height: 384px;
  border-radius: 999px;
  background: linear-gradient(135deg, #f472b6, #c084fc);
  content: "";
  filter: blur(64px);
  opacity: 0.3;
  pointer-events: none;
}

.reference-feature-page .feature-detail-hero-copy {
  position: relative;
  z-index: 1;
  grid-column: span 3;
  max-width: 485px;
  transform: none;
}

.reference-feature-page .feature-detail-hero h1 {
  width: 565px;
  max-width: none;
  color: transparent;
  font-family: "degularFont", Inter, ui-sans-serif, system-ui, sans-serif;
  font-size: 48px;
  font-weight: 700;
  line-height: 48px;
  letter-spacing: normal;
  background: linear-gradient(90deg, #1d2735, #3a2c6f);
  background-clip: text;
  transform: scaleX(0.86);
  transform-origin: left center;
}

.reference-feature-page
  .feature-detail-hero-copy
  > p:not(.feature-detail-eyebrow):not(.feature-detail-breadcrumb) {
  margin-top: 24px;
  color: #4b5563;
  font-size: 20px;
  line-height: 28px;
}

.reference-feature-page .feature-detail-hero .marketing-hero-actions {
  gap: 12px;
  margin-top: 32px;
}

.reference-feature-page .feature-detail-hero .marketing-button {
  min-height: 40px;
  padding: 8px 12px;
  border-radius: 12px;
  box-shadow:
    0 1px 2px rgb(10 13 18 / 5%),
    inset 0 -2px 0 rgb(10 13 18 / 5%);
  font-weight: 450;
  line-height: 20px;
  white-space: nowrap;
}

.reference-feature-page .feature-detail-preview {
  position: relative;
  z-index: 1;
  grid-column: span 4;
  width: 100%;
  height: 420px;
  min-height: 420px;
  border: 0;
  border-radius: 0;
  background: transparent;
  box-shadow: none;
  animation: none;
  overflow: visible;
}

.reference-feature-page .feature-detail-preview::before {
  display: none;
}

.reference-feature-page .feature-detail-preview-has-image .feature-detail-preview-media {
  min-height: 0;
  padding: 0;
  overflow: visible;
  background: transparent;
}

.reference-feature-page .feature-detail-preview-has-image .feature-detail-preview-image {
  display: block;
  width: 100%;
  height: 420px;
  max-height: 420px;
  object-fit: contain;
  object-position: right center;
  border-radius: 18px;
  box-shadow: 0 22px 52px rgb(26 35 73 / 17%);
}

.reference-feature-primary {
  padding: 96px 32px;
  background: #f9fafb;
  box-sizing: border-box;
}

.reference-feature-demo-editor .reference-feature-primary {
  height: 1828.59375px;
}

.reference-feature-personalization .reference-feature-primary {
  height: 2917.9921875px;
}

.reference-feature-primary-inner {
  display: grid;
  width: min(1152px, 100%);
  height: 100%;
  margin: 0 auto;
  grid-auto-rows: minmax(0, 1fr);
}

.reference-feature-row {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 48px;
  height: calc(100% - 64px);
  margin: 32px 0;
  padding: 40px;
  box-sizing: border-box;
  align-items: center;
  border: 1px solid #e5e7eb;
  border-radius: 24px;
  background: #fff;
}

.reference-feature-row.is-reversed .reference-feature-row-media {
  order: 2;
  grid-column: 4 / span 2;
}

.reference-feature-row.is-reversed .reference-feature-row-copy {
  order: 1;
  grid-column: 1 / span 3;
}

.reference-feature-row-media {
  grid-column: 1 / span 2;
  min-width: 0;
}

.reference-feature-row-media img {
  display: block;
  width: 100%;
  aspect-ratio: 1;
  object-fit: contain;
  border-radius: 14px;
}

.reference-feature-row-copy {
  grid-column: 3 / span 3;
  min-width: 0;
}

.reference-feature-row-copy .feature-detail-eyebrow {
  margin: 0 0 14px;
  color: #4d54e8;
  font-size: 12px;
  letter-spacing: 0.1em;
}

.reference-feature-row-copy h2 {
  margin: 0;
  color: #111827;
  font-size: 30px;
  line-height: 36px;
  letter-spacing: -0.04em;
}

.reference-feature-row-copy > p:not(.feature-detail-eyebrow) {
  margin: 16px 0 0;
  color: var(--reference-feature-muted);
  font-size: 16px;
  line-height: 24px;
}

.reference-feature-row-copy .marketing-text-action {
  display: inline-flex;
  gap: 8px;
  margin-top: 24px;
  color: #4d54e8;
  font-size: 14px;
  font-weight: 750;
  text-decoration: none;
}

.reference-feature-row-copy .marketing-text-action:hover,
.reference-feature-row-copy .marketing-text-action:focus-visible {
  text-decoration: underline;
  text-underline-offset: 3px;
}

.reference-feature-capabilities {
  height: 956px;
  padding: 96px 32px;
  color: #fff;
  background: #011369;
  box-sizing: border-box;
  overflow: hidden;
}

.reference-feature-capabilities-inner {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  grid-template-rows: repeat(3, minmax(0, 1fr));
  gap: 24px 48px;
  width: min(1216px, 100%);
  height: 100%;
  margin: 0 auto;
}

.reference-feature-capability-card {
  position: relative;
  display: grid;
  align-content: center;
  min-width: 0;
  padding: 32px;
  overflow: hidden;
  border: 1px solid rgb(255 255 255 / 15%);
  border-radius: 18px;
  background: linear-gradient(135deg, rgb(255 255 255 / 12%), rgb(255 255 255 / 3%));
}

.reference-feature-capability-card::after {
  position: absolute;
  right: -20%;
  bottom: -60%;
  width: 70%;
  height: 150%;
  border-radius: 999px;
  background: rgb(109 120 255 / 22%);
  content: "";
  filter: blur(22px);
}

.reference-feature-capability-card > span {
  position: relative;
  z-index: 1;
  color: #aebcff;
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.1em;
}

.reference-feature-capability-card h2 {
  position: relative;
  z-index: 1;
  max-width: 15ch;
  margin: 18px 0 10px;
  color: #fff;
  font-size: 30px;
  line-height: 1.05;
  letter-spacing: -0.05em;
}

.reference-feature-capability-card p {
  position: relative;
  z-index: 1;
  max-width: 44ch;
  margin: 0;
  color: #cad5ff;
  font-size: 14px;
  line-height: 1.5;
}

.reference-feature-use-cases {
  height: 818.4375px;
  padding: 120px 32px;
  box-sizing: border-box;
  overflow: hidden;
}

.reference-feature-explore {
  height: 584px;
  padding: 96px 32px 110px;
  box-sizing: border-box;
  overflow: hidden;
}

.reference-feature-faq {
  height: 880px;
  padding: 112px 32px 132px;
  box-sizing: border-box;
  overflow: hidden;
}

.reference-feature-personalization .reference-feature-faq {
  height: 852px;
}

.reference-feature-page > .showcase-trust {
  height: 600px;
  min-height: 600px;
  box-sizing: border-box;
  overflow: hidden;
}

.reference-feature-page + .marketing-footer-showcase {
  margin-top: 0;
  box-sizing: border-box;
  padding-top: 32px;
}

@media (max-width: 760px) {
  .reference-feature-page {
    overflow: visible;
  }

  .reference-feature-page .reference-feature-hero {
    grid-template-columns: 1fr;
    width: min(100% - 40px, 720px);
    height: auto;
    min-height: 0;
    margin: 0 auto;
    padding: 76px 0 84px;
    gap: 44px;
  }

  .reference-feature-page .feature-detail-hero-copy,
  .reference-feature-page .feature-detail-preview {
    grid-column: auto;
  }

  .reference-feature-page .feature-detail-hero h1 {
    width: auto;
    max-width: 485px;
    font-size: 46px;
    line-height: 48px;
    transform: none;
  }

  .reference-feature-page .feature-detail-hero .marketing-hero-actions {
    flex-wrap: wrap;
  }

  .reference-feature-page .feature-detail-preview {
    height: auto;
    min-height: 0;
  }

  .reference-feature-primary,
  .reference-feature-demo-editor .reference-feature-primary,
  .reference-feature-personalization .reference-feature-primary,
  .reference-feature-capabilities,
  .reference-feature-use-cases,
  .reference-feature-explore,
  .reference-feature-faq,
  .reference-feature-personalization .reference-feature-faq,
  .reference-feature-page > .showcase-trust {
    height: auto;
    min-height: 0;
    overflow: visible;
  }

  .reference-feature-primary {
    padding: 72px 20px;
  }

  .reference-feature-primary-inner {
    display: grid;
    height: auto;
    gap: 24px;
  }

  .reference-feature-row,
  .reference-feature-row.is-reversed {
    display: flex;
    height: auto;
    min-height: 0;
    flex-direction: column;
    gap: 28px;
    margin: 0;
    padding: 24px;
  }

  .reference-feature-row.is-reversed .reference-feature-row-media,
  .reference-feature-row.is-reversed .reference-feature-row-copy,
  .reference-feature-row-media,
  .reference-feature-row-copy {
    order: initial;
    width: 100%;
  }

  .reference-feature-row-media img {
    aspect-ratio: 1.1;
  }

  .reference-feature-capabilities {
    padding: 72px 20px;
  }

  .reference-feature-capabilities-inner {
    display: grid;
    grid-template-columns: 1fr;
    grid-template-rows: none;
    height: auto;
    gap: 14px;
  }

  .reference-feature-capability-card {
    min-height: 220px;
    padding: 24px;
  }

  .reference-feature-use-cases {
    padding: 76px 20px;
  }

  .reference-feature-explore {
    height: auto;
    padding: 72px 20px;
  }

  .reference-feature-faq {
    padding: 76px 20px 88px;
  }

  .reference-feature-page > .showcase-trust {
    padding: 65px 20px 70px;
  }

  .reference-feature-page + .marketing-footer-showcase {
    padding-top: 0;
  }
}

@media (prefers-reduced-motion: reduce) {
  .reference-feature-page * {
    animation: none !important;
    scroll-behavior: auto !important;
    transition: none !important;
  }
}

