* {
  box-sizing: border-box;
}
html {
  background: var(--canvas);
  scroll-behavior: smooth;
}
body {
  margin: 0;
  color: var(--ink);
  background: var(--canvas);
  font-family: var(--font-family-sans);
  -webkit-font-smoothing: antialiased;
}
a {
  color: inherit;
  text-decoration: none;
}
button,
a {
  -webkit-tap-highlight-color: transparent;
}
button:focus-visible,
a:focus-visible {
  outline: 3px solid var(--color-focus-ring);
  outline-offset: 3px;
}

.app-shell {
  min-height: 100vh;
  display: flex;
}

/* Authenticated home: compact workspace rail with a Supademo-like content shelf. */
.home-workspace {
  min-height: 100vh;
  display: flex;
  color: #273247;
  background: #fff;
  font-size: 14px;
}
.workspace-reference .home-main {
  background: #fff;
}
.workspace-ref-content {
  min-height: calc(100vh - 64px);
  padding: 0 7.5%;
  overflow: hidden;
}
.workspace-ref-heading {
  padding: 0 0 30px;
}
.workspace-ref-breadcrumb {
  height: 52px;
  display: flex;
  align-items: center;
  gap: 14px;
  margin: 0 -7.5%;
  padding: 0 28px;
  color: #737c8d;
  border-bottom: 1px solid #e6e9ef;
  font-size: 15px;
}
.workspace-ref-breadcrumb svg {
  width: 18px;
  height: 18px;
}
.workspace-ref-breadcrumb strong {
  color: #273247;
  font-weight: 600;
}
.workspace-ref-title-row {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 24px;
  padding-top: 33px;
}
.workspace-ref-title-row h1 {
  margin: 0;
  color: #111c31;
  font-size: 32px;
  letter-spacing: -0.06em;
}
.workspace-ref-title-row p {
  margin: 12px 0 0;
  color: #667085;
  font-size: 16px;
}
.workspace-ref-actions {
  display: flex;
  align-items: center;
  gap: 14px;
}
.workspace-ref-primary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 43px;
  padding: 0 18px;
  color: #fff;
  background: #4b4ee8;
  border: 0;
  border-radius: 9px;
  font: inherit;
  font-size: 16px;
  font-weight: 700;
  cursor: pointer;
