/* Workspace reference surfaces: authored to mirror the Supademo creator desk while keeping
   every illustration local and deterministic. Motion is limited to state/relationship changes. */
.workspace-reference {
  --workspace-cobalt: #4b4ee8;
  --workspace-ink: #101828;
  --workspace-muted: #667085;
  --workspace-line: #e1e5ec;
  --workspace-canvas: #f7f9fc;
}
.workspace-reference .home-main {
  min-width: 0;
  background: #fff;
}
.workspace-reference .home-sidebar {
  min-height: 100vh;
}
.workspace-reference .home-topbar {
  height: 64px;
  background: #fff;
}
.workspace-reference .home-topbar svg,
.workspace-reference .home-earn svg {
  color: #5f6878;
}
.workspace-ref-content {
  animation: workspace-ref-enter 320ms cubic-bezier(0.2, 0.75, 0.25, 1) both;
}
.workspace-ref-create-dialog {
  width: min(560px, calc(100vw - 32px));
  animation: workspace-ref-create-in 220ms cubic-bezier(0.2, 0.75, 0.25, 1) both;
}
.workspace-ref-create-options {
  display: grid;
  gap: 10px;
  padding: 2px 0 22px;
}
.workspace-ref-create-options button {
  display: grid;
  grid-template-columns: 42px minmax(0, 1fr);
  align-items: center;
  gap: 14px;
  width: 100%;
  padding: 14px;
  color: var(--workspace-ink);
  background: #fff;
  border: 1px solid #e2e7ef;
  border-radius: 12px;
  text-align: left;
  cursor: pointer;
  transition:
    border-color 160ms ease,
    background 160ms ease,
    transform 160ms ease;
}
.workspace-ref-create-options button:hover {
  border-color: #aeb9f8;
  transform: translateY(-1px);
}
.workspace-ref-create-options button.is-selected {
  background: #f2f4ff;
  border-color: var(--workspace-cobalt);
  box-shadow: 0 0 0 3px rgb(75 78 232 / 10%);
}
.workspace-ref-create-options strong,
.workspace-ref-create-options small {
  display: block;
}
.workspace-ref-create-options strong {
  font-size: 15px;
}
.workspace-ref-create-options small {
  margin-top: 3px;
  color: var(--workspace-muted);
  font-size: 13px;
  line-height: 1.4;
}
.workspace-ref-create-icon {
  position: relative;
  display: block;
  width: 42px;
  height: 42px;
  background: #eef1ff;
  border: 1px solid #d6dcff;
  border-radius: 11px;
}
.workspace-ref-create-icon::before,
.workspace-ref-create-icon::after {
  position: absolute;
  content: "";
}
.workspace-ref-create-icon-guided::before {
  inset: 10px 9px;
  border: 2px solid var(--workspace-cobalt);
  border-radius: 5px;
}
.workspace-ref-create-icon-guided::after {
  left: 17px;
  top: 14px;
  width: 8px;
  height: 8px;
  border-top: 2px solid var(--workspace-cobalt);
  border-right: 2px solid var(--workspace-cobalt);
  transform: rotate(45deg);
}
.workspace-ref-create-icon-html::before {
  inset: 9px;
  border: 2px solid var(--workspace-cobalt);
  border-radius: 4px;
}
.workspace-ref-create-icon-html::after {
  left: 14px;
  top: 14px;
  width: 13px;
  height: 8px;
  border-top: 2px solid var(--workspace-cobalt);
  border-bottom: 2px solid var(--workspace-cobalt);
}
.workspace-ref-create-icon-sandbox::before {
  left: 9px;
  top: 12px;
  width: 22px;
  height: 16px;
  border: 2px solid var(--workspace-cobalt);
  border-radius: 50%;
  transform: rotate(-18deg);
}
.workspace-ref-create-icon-sandbox::after {
  left: 17px;
  top: 9px;
  width: 7px;
  height: 22px;
  border-left: 2px solid var(--workspace-cobalt);
  transform: rotate(35deg);
}
.workspace-ref-create-icon-screenshot::before {
  inset: 10px;
  border: 2px solid var(--workspace-cobalt);
  border-radius: 4px;
}
.workspace-ref-create-icon-screenshot::after {
  left: 15px;
  top: 15px;
  width: 12px;
  height: 8px;
  border-bottom: 2px solid var(--workspace-cobalt);
  border-left: 2px solid var(--workspace-cobalt);
  transform: skewY(-24deg);
}
.workspace-ref-create-icon-video::before {
  left: 9px;
  top: 12px;
  width: 19px;
  height: 16px;
  border: 2px solid var(--workspace-cobalt);
  border-radius: 4px;
}
.workspace-ref-create-icon-video::after {
  right: 7px;
  top: 17px;
  width: 0;
  height: 0;
  border-top: 4px solid transparent;
  border-bottom: 4px solid transparent;
  border-left: 6px solid var(--workspace-cobalt);
}
.workspace-ref-create-icon-upload::before {
  left: 11px;
  top: 18px;
  width: 18px;
  height: 13px;
  border: 2px solid var(--workspace-cobalt);
  border-radius: 4px;
}
.workspace-ref-create-icon-upload::after {
  left: 18px;
  top: 9px;
  width: 7px;
  height: 14px;
  border-left: 2px solid var(--workspace-cobalt);
  border-top: 2px solid var(--workspace-cobalt);
