  margin-top: var(--space-2);
}

.loading-screen,
.state-screen {
  min-height: 100vh;
  display: grid;
  place-content: center;
  justify-items: center;
  gap: 14px;
  padding: 24px;
  text-align: center;
  background: var(--canvas);
}
.loading-screen {
  align-content: center;
}
.loading-line {
  width: 160px;
  height: 10px;
  background: var(--color-skeleton);
