/* Shared UI primitives. Keep component state styling semantic and token-driven. */
.ui-button,
.ui-link,
.ui-control,
.ui-choice-control,
.ui-switch-control {
  font: inherit;
}
.ui-sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}
.ui-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-2);
  min-height: 36px;
  padding: 0 var(--space-4);
  border: 1px solid transparent;
  border-radius: var(--radius-lg);
  font-size: var(--font-size-md);
  font-weight: var(--font-weight-semibold);
  cursor: pointer;
  transition:
    background var(--motion-duration-fast) var(--motion-ease-standard),
    border-color var(--motion-duration-fast) var(--motion-ease-standard),
    color var(--motion-duration-fast) var(--motion-ease-standard),
    box-shadow var(--motion-duration-fast) var(--motion-ease-standard);
}
.ui-button:hover:not(:disabled) {
  transform: translateY(-1px);
}
.ui-button:focus-visible,
.ui-link:focus-visible,
.ui-control:focus-visible,
.ui-choice-control:focus-visible,
.ui-switch-control:focus-visible {
  outline: 3px solid var(--color-focus-ring);
  outline-offset: 2px;
}
.ui-button:disabled,
.ui-control:disabled,
.ui-choice-control:disabled,
.ui-switch-control:disabled {
  cursor: not-allowed;
  opacity: 0.55;
}
.ui-button-primary {
  color: var(--color-on-brand);
  background: var(--color-brand);
  box-shadow: var(--shadow-button);
}
.ui-button-primary:hover:not(:disabled) {
  background: var(--color-brand-strong);
}
.ui-button-secondary {
  color: var(--color-text-primary);
  background: var(--color-surface-raised);
  border-color: var(--color-border);
}
.ui-button-secondary:hover:not(:disabled),
.ui-button-ghost:hover:not(:disabled) {
  background: var(--color-brand-subtle);
}
.ui-button-ghost {
  color: var(--color-brand-strong);
  background: transparent;
}
.ui-button-danger {
  color: var(--color-on-brand);
  background: var(--color-danger);
}
.ui-control-sm {
  min-height: 32px;
}
.ui-control-md {
  min-height: 36px;
}
.ui-control-lg {
  min-height: 44px;
}
.ui-icon-button {
  width: 36px;
  padding: 0;
}
.ui-link {
  color: var(--color-brand-strong);
  text-decoration: underline;
  text-decoration-thickness: 1px;
  text-underline-offset: 2px;
}
.ui-link-muted {
  color: var(--color-text-secondary);
}
.ui-link-subtle {
  color: var(--color-text-tertiary);
}
.ui-field,
.ui-choice-field {
  display: grid;
  gap: var(--space-2);
}
.ui-field-label,
.ui-choice-label {
  color: var(--color-text-primary);
  font-size: var(--font-size-md);
  font-weight: var(--font-weight-medium);
}
.ui-field-description,
.ui-choice-description {
  color: var(--color-text-secondary);
  font-size: var(--font-size-sm);
  line-height: var(--line-height-body);
}
.ui-field-error,
.ui-choice-error {
  color: var(--color-danger);
  font-size: var(--font-size-sm);
  line-height: var(--line-height-body);
}
.ui-control {
  width: 100%;
  min-height: 40px;
  padding: 0 var(--space-3);
  color: var(--color-text-primary);
  background: var(--color-surface-raised);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
}
.ui-control::placeholder {
  color: var(--color-text-tertiary);
}
.ui-control[aria-invalid="true"] {
  border-color: var(--color-danger);
}
.ui-textarea {
  min-height: 96px;
  padding-block: var(--space-3);
  resize: vertical;
}
.ui-select {
  appearance: auto;
}
.ui-choice-field {
  gap: var(--space-1);
}
.ui-choice-row {
  display: flex;
  align-items: flex-start;
  gap: var(--space-2);
}
.ui-choice-control,
.ui-switch-control {
  flex: 0 0 auto;
