}
.ui-choice-label {
  cursor: pointer;
}
.ui-badge {
  display: inline-flex;
  align-items: center;
  min-height: 24px;
  padding: 0 var(--space-2);
  color: var(--color-text-secondary);
  background: var(--color-status-neutral);
  border-radius: var(--radius-pill);
  font-size: var(--font-size-sm);
  font-weight: var(--font-weight-semibold);
}
.ui-badge-brand {
  color: var(--color-brand-strong);
  background: var(--color-brand-subtle);
}
.ui-badge-success {
  color: var(--color-success);
  background: var(--color-success-subtle);
}
.ui-badge-warning {
  color: var(--color-warning);
  background: var(--color-warning-subtle);
}
.ui-badge-danger {
  color: var(--color-danger);
  background: var(--color-danger-subtle);
}
.ui-avatar {
  display: inline-grid;
  place-items: center;
  width: 36px;
  height: 36px;
  overflow: hidden;
  color: var(--color-avatar-text);
  background: var(--color-avatar-surface);
  border-radius: 50%;
  font-size: var(--font-size-sm);
  font-weight: var(--font-weight-bold);
}
.ui-avatar.ui-control-sm {
  width: 28px;
  height: 28px;
}
.ui-avatar.ui-control-lg {
  width: 48px;
  height: 48px;
  font-size: var(--font-size-lg);
}
.ui-avatar img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.ui-separator {
  flex: 0 0 auto;
  background: var(--color-border);
}
.ui-separator-horizontal {
  width: 100%;
  height: 1px;
}
.ui-separator-vertical {
  width: 1px;
  min-height: 1.5em;
}
.ui-spinner {
  display: inline-block;
  width: 16px;
  height: 16px;
  border: 2px solid currentColor;
  border-right-color: transparent;
  border-radius: 50%;
  animation: ui-spin var(--motion-duration-skeleton) linear infinite;
}
.ui-button-spinner {
  width: 14px;
  height: 14px;
}
.ui-tooltip {
  position: relative;
  display: inline-flex;
}
.ui-tooltip-content {
  position: absolute;
  z-index: var(--z-overlay);
  width: max-content;
  max-width: 240px;
  padding: var(--space-2) var(--space-3);
  color: var(--color-on-brand);
  background: var(--color-text-primary);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-sm);
  font-size: var(--font-size-sm);
  line-height: var(--line-height-body);
  visibility: hidden;
  opacity: 0;
  pointer-events: none;
  transform: translateY(2px);
  transition:
    opacity var(--motion-duration-fast) var(--motion-ease-standard),
    transform var(--motion-duration-fast) var(--motion-ease-standard),
    visibility var(--motion-duration-fast) var(--motion-ease-standard);
}
.ui-tooltip:hover .ui-tooltip-content,
.ui-tooltip:focus-within .ui-tooltip-content {
  visibility: visible;
  opacity: 1;
  transform: translateY(0);
}
.ui-tooltip-top .ui-tooltip-content {
  right: 50%;
  bottom: calc(100% + var(--space-2));
  transform: translate(50%, 2px);
}
.ui-tooltip-top:hover .ui-tooltip-content,
.ui-tooltip-top:focus-within .ui-tooltip-content {
  transform: translate(50%, 0);
}
.ui-tooltip-right .ui-tooltip-content {
  top: 50%;
  left: calc(100% + var(--space-2));
  transform: translate(2px, -50%);
}
.ui-tooltip-right:hover .ui-tooltip-content,
.ui-tooltip-right:focus-within .ui-tooltip-content {
  transform: translate(0, -50%);
}
.ui-tooltip-bottom .ui-tooltip-content {
  top: calc(100% + var(--space-2));
  right: 50%;
  transform: translate(50%, 2px);
}
.ui-tooltip-bottom:hover .ui-tooltip-content,
.ui-tooltip-bottom:focus-within .ui-tooltip-content {
  transform: translate(50%, 0);
}
.ui-tooltip-left .ui-tooltip-content {
  top: 50%;
  right: calc(100% + var(--space-2));
  transform: translate(-2px, -50%);
}
.ui-tooltip-left:hover .ui-tooltip-content,
.ui-tooltip-left:focus-within .ui-tooltip-content {
  transform: translate(0, -50%);
}
@keyframes ui-spin {
  to {
    transform: rotate(360deg);
  }
}

.ui-overlay-layer {
  position: fixed;
  z-index: var(--z-overlay);
  inset: 0;
  display: grid;
  place-items: center;
  padding: var(--space-6);
