.ui-stack[data-gap="10"],
.ui-grid[data-gap="10"] {
  gap: var(--space-10);
}
.ui-stack[data-gap="11"],
.ui-grid[data-gap="11"] {
  gap: var(--space-11);
}
.ui-grid {
  display: grid;
  min-width: 0;
}
.ui-grid[data-columns="1"] {
  grid-template-columns: repeat(1, minmax(0, 1fr));
}
.ui-grid[data-columns="2"] {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}
.ui-grid[data-columns="3"] {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}
.ui-grid[data-columns="4"] {
  grid-template-columns: repeat(4, minmax(0, 1fr));
}
.ui-grid[data-columns="5"] {
  grid-template-columns: repeat(5, minmax(0, 1fr));
}
.ui-grid[data-columns="6"] {
  grid-template-columns: repeat(6, minmax(0, 1fr));
}
.ui-grid[data-min-item-width="sm"] {
  grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
}
.ui-grid[data-min-item-width="md"] {
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
}
.ui-grid[data-min-item-width="lg"] {
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
}
.ui-container {
  width: min(100%, calc(100% - var(--space-6)));
  margin-inline: auto;
  min-width: 0;
}
.ui-container-narrow {
  max-width: 720px;
}
.ui-container-content {
  max-width: 1180px;
}
.ui-container-wide {
  max-width: 1440px;
}
.ui-split-pane {
  display: grid;
  grid-template-columns: minmax(0, 280px) minmax(0, 1fr);
  min-width: 0;
  min-height: 0;
  overflow: hidden;
}
.ui-split-pane[data-side="right"] {
  grid-template-columns: minmax(0, 1fr) minmax(0, 280px);
}
.ui-split-pane[data-sidebar-size="sm"] {
  grid-template-columns: minmax(0, 220px) minmax(0, 1fr);
}
.ui-split-pane[data-sidebar-size="lg"] {
  grid-template-columns: minmax(0, 360px) minmax(0, 1fr);
}
.ui-split-pane[data-side="right"][data-sidebar-size="sm"] {
  grid-template-columns: minmax(0, 1fr) minmax(0, 220px);
}
.ui-split-pane[data-side="right"][data-sidebar-size="lg"] {
  grid-template-columns: minmax(0, 1fr) minmax(0, 360px);
}
.ui-split-pane-sidebar,
.ui-split-pane-main {
  min-width: 0;
  min-height: 0;
}
.ui-split-pane-sidebar {
  overflow: auto;
}
.ui-split-pane-main {
  overflow: auto;
}
.ui-sidebar {
  display: flex;
  flex-direction: column;
  min-width: 0;
  min-height: 100%;
  padding: var(--space-5);
  color: var(--color-text-primary);
  background: var(--color-surface);
  border-right: 1px solid var(--color-border);
}
.ui-sidebar nav {
  display: grid;
  gap: var(--space-1);
  min-width: 0;
}
.ui-sidebar-footer {
  margin-top: auto;
  padding-top: var(--space-6);
}
.ui-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-4);
  min-width: 0;
  min-height: 64px;
  padding: var(--space-3) var(--space-5);
  color: var(--color-text-primary);
  background: var(--color-surface-raised);
  border-bottom: 1px solid var(--color-border);
}
.ui-header-content,
.ui-header-actions {
  display: flex;
  align-items: center;
  gap: var(--space-3);
  min-width: 0;
}
.ui-header-content {
  flex: 1;
}
.ui-header-actions {
  flex: 0 0 auto;
  flex-wrap: wrap;
  justify-content: flex-end;
}
.ui-breadcrumb {
  min-width: 0;
  overflow-x: auto;
  color: var(--color-text-secondary);
}
.ui-breadcrumb ol {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  min-width: max-content;
  margin: 0;
  padding: 0;
  list-style: none;
  font-size: var(--font-size-sm);
}
.ui-breadcrumb li {
  display: inline-flex;
  align-items: center;
  gap: var(--space-2);
}
.ui-breadcrumb a {
  color: var(--color-brand-strong);
  text-decoration: none;
}
.ui-breadcrumb a:hover,
.ui-breadcrumb a:focus-visible {
  text-decoration: underline;
}
.ui-breadcrumb span[aria-current="page"] {
  color: var(--color-text-primary);
  font-weight: var(--font-weight-semibold);
}
.ui-breadcrumb-separator {
  color: var(--color-text-tertiary);
}
.ui-tabs {
  min-width: 0;
}
.ui-tabs-tablist {
  display: flex;
  gap: var(--space-1);
  max-width: 100%;
  overflow-x: auto;
  border-bottom: 1px solid var(--color-border);
}
.ui-tabs-vertical {
  display: grid;
  grid-template-columns: max-content minmax(0, 1fr);
  gap: var(--space-6);
}
.ui-tabs-vertical .ui-tabs-tablist {
  display: grid;
  align-content: start;
  overflow-x: visible;
  border-right: 1px solid var(--color-border);
  border-bottom: 0;
}
.ui-tabs-tab {
  position: relative;
  min-height: 44px;
  padding: 0 var(--space-3);
  color: var(--color-text-secondary);
  background: transparent;
  border: 0;
  border-bottom: 2px solid transparent;
  cursor: pointer;
  font: inherit;
  font-size: var(--font-size-md);
  font-weight: var(--font-weight-semibold);
  white-space: nowrap;
}
.ui-tabs-tab:hover,
.ui-tabs-tab:focus-visible {
  color: var(--color-brand-strong);
  background: var(--color-brand-subtle);
  outline: 0;
}
.ui-tabs-tab[aria-selected="true"] {
  color: var(--color-brand-strong);
  border-bottom-color: var(--color-brand);
}
.ui-tabs-tab:disabled {
  cursor: not-allowed;
  opacity: 0.5;
}
.ui-tabs-vertical .ui-tabs-tab {
  border-right: 2px solid transparent;
  border-bottom: 0;
  text-align: left;
}
.ui-tabs-vertical .ui-tabs-tab[aria-selected="true"] {
  border-right-color: var(--color-brand);
}
.ui-tabs-panel {
  min-width: 0;
  padding-block: var(--space-5);
}
.ui-tabs-panel:focus-visible {
  outline: 3px solid var(--color-focus-ring);
  outline-offset: 2px;
}
.ui-pagination {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-2);
  max-width: 100%;
  color: var(--color-text-secondary);
}
.ui-pagination > button,
.ui-pagination ol button {
  min-width: 40px;
  min-height: 40px;
  padding: 0 var(--space-2);
  color: inherit;
  background: var(--color-surface-raised);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  cursor: pointer;
  font: inherit;
  font-size: var(--font-size-sm);
  font-weight: var(--font-weight-semibold);
}
.ui-pagination > button {
  padding-inline: var(--space-3);
}
.ui-pagination button:hover:not(:disabled),
.ui-pagination button:focus-visible {
  color: var(--color-brand-strong);
  background: var(--color-brand-subtle);
  border-color: var(--color-brand);
  outline: 0;
}
.ui-pagination button:disabled {
  cursor: not-allowed;
  opacity: 0.5;
}
.ui-pagination ol {
  display: flex;
  align-items: center;
  gap: var(--space-1);
  margin: 0;
  padding: 0;
  list-style: none;
}
.ui-pagination ol button[aria-current="page"] {
  color: var(--color-on-brand);
  background: var(--color-brand);
  border-color: var(--color-brand);
}

@media (max-width: 800px) {
  .ui-grid[data-columns="3"],
  .ui-grid[data-columns="4"],
  .ui-grid[data-columns="5"],
  .ui-grid[data-columns="6"] {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .ui-split-pane,
  .ui-split-pane[data-side="right"],
  .ui-split-pane[data-sidebar-size="sm"],
  .ui-split-pane[data-sidebar-size="lg"] {
    grid-template-columns: minmax(0, 1fr);
  }
  .ui-split-pane-sidebar {
    max-height: 320px;
    border-right: 0;
    border-bottom: 1px solid var(--color-border);
  }
  .ui-split-pane-main {
    min-height: 0;
  }
  .ui-tabs-vertical {
    display: block;
  }
  .ui-tabs-vertical .ui-tabs-tablist {
    display: flex;
    overflow-x: auto;
    border-right: 0;
    border-bottom: 1px solid var(--color-border);
  }
  .ui-tabs-vertical .ui-tabs-tab {
    border-right: 0;
    border-bottom: 2px solid transparent;
  }
  .ui-tabs-vertical .ui-tabs-tab[aria-selected="true"] {
    border-right-color: transparent;
    border-bottom-color: var(--color-brand);
  }
}

@media (max-width: 520px) {
  .ui-container {
    width: min(100%, calc(100% - var(--space-4)));
  }
  .ui-header {
    align-items: flex-start;
    flex-direction: column;
  }
  .ui-header-content,
  .ui-header-actions {
    width: 100%;
  }
  .ui-header-actions {
    justify-content: flex-start;
  }
  .ui-grid[data-columns="2"],
  .ui-grid[data-columns="3"],
  .ui-grid[data-columns="4"],
  .ui-grid[data-columns="5"],
  .ui-grid[data-columns="6"] {
    grid-template-columns: minmax(0, 1fr);
  }
  .ui-pagination {
    flex-wrap: wrap;
  }
  .ui-pagination > button {
    flex: 1 1 auto;
  }
}

