/* Public marketing home */
.marketing-home {
  --marketing-ink: #07153d;
  --marketing-muted: #52617d;
  --marketing-blue: #314bd8;
  --marketing-blue-dark: #162b9e;
  --marketing-pale: #e9edff;
  --marketing-line: #dbe1f0;
  overflow: hidden;
  color: var(--marketing-ink);
  background: #fff;
}
.marketing-nav,
.marketing-hero,
.marketing-product,
.marketing-workflows,
.product-page-hero,
.product-page-statement,
.product-area-list,
.marketing-footer {
  width: min(1180px, calc(100% - 64px));
  margin-inline: auto;
}
.marketing-nav {
  width: min(1216px, calc(100% - 64px));
}
.marketing-nav {
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 78px;
  gap: 24px;
}
.marketing-logo {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  color: var(--marketing-ink);
  font-size: 20px;
  font-weight: 800;
  letter-spacing: -0.06em;
}
.marketing-logo img {
  display: block;
  width: 148px;
  height: 32px;
  object-fit: contain;
}
.marketing-logo span {
  display: grid;
  place-items: center;
  width: 28px;
  height: 28px;
  color: #fff;
  background: var(--marketing-blue);
  border-radius: 8px;
  font-size: 14px;
  letter-spacing: -0.08em;
}
.marketing-nav nav,
.marketing-nav-actions,
.marketing-hero-actions,
.marketing-demo-actions,
.marketing-proof div,
.marketing-footer > div {
  display: flex;
  align-items: center;
  gap: 24px;
}
.marketing-nav nav a,
.marketing-nav-actions > a:first-child,
.marketing-footer a:not(.marketing-logo) {
  color: #384866;
  font-size: 14px;
  font-weight: 650;
}
.marketing-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 48px;
  padding: 0 20px;
  color: #fff;
  background: var(--marketing-blue);
  border: 1px solid var(--marketing-blue);
  border-radius: 9px;
  box-shadow: 0 9px 20px rgb(49 75 216 / 20%);
  font: inherit;
  font-size: 14px;
  font-weight: 750;
  cursor: pointer;
  transition:
    background var(--motion-duration-fast),
    transform var(--motion-duration-fast);
}
.marketing-button:hover {
  background: var(--marketing-blue-dark);
  transform: translateY(-1px);
}
.marketing-button:disabled {
  color: #7582a3;
  background: #edf0f7;
  border-color: #edf0f7;
  box-shadow: none;
  cursor: not-allowed;
  transform: none;
}
.marketing-button-small {
  min-height: 38px;
  padding-inline: 15px;
  border-radius: 8px;
  box-shadow: none;
}
.marketing-text-action {
  color: var(--marketing-ink);
  font-size: 14px;
  font-weight: 750;
}
.marketing-hero {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(420px, 0.92fr);
  align-items: center;
  gap: 70px;
  min-height: 650px;
