  }
  .marketing-section-heading,
  .marketing-workflows {
    grid-template-columns: 1fr;
    gap: 36px;
  }
  .marketing-product {
    padding-block: 88px;
  }
  .marketing-workflows {
    padding-block: 80px;
  }
  .marketing-footer {
    grid-template-columns: 1fr;
  }
