  .marketing-nav,
  .marketing-hero,
  .marketing-product,
  .marketing-workflows,
  .marketing-footer {
    width: min(100% - 40px, 1180px);
  }
  .marketing-nav {
    min-height: 68px;
  }
  .marketing-nav-actions > a:first-child {
    display: none;
  }
  .marketing-logo {
    font-size: 18px;
  }
  .marketing-hero {
    padding-top: 44px;
  }
  .marketing-hero h1 {
    font-size: clamp(42px, 13vw, 58px);
  }
  .marketing-hero-copy > p:not(.marketing-announcement) {
    font-size: 17px;
  }
  .marketing-hero-actions {
    align-items: flex-start;
    flex-direction: column;
    gap: 16px;
  }
  .marketing-demo-body {
    min-height: 300px;
    padding: 34px 26px;
  }
  .marketing-proof {
    padding-inline: 20px;
  }
  .marketing-section-heading {
    margin-bottom: 38px;
  }
  .marketing-capability-list article {
    grid-template-columns: 42px 1fr;
  }
  .marketing-capability-list article > a {
    grid-column: 2;
  }
  .marketing-customers {
    padding: 82px 20px;
  }
  .marketing-footer {
    padding-block: 32px;
  }
  .marketing-footer > div {
    flex-wrap: wrap;
  }
