  padding-inline: 16px;
  border-bottom-color: var(--marketing-line);
  font-size: 11px;
}
.marketing-use-case-content {
  display: grid;
  align-content: center;
  padding: 30px;
}
.marketing-use-case-content h3 {
  margin: 0;
  font-size: 28px;
  line-height: 1.05;
  letter-spacing: -0.05em;
}
.marketing-use-case-content p {
  margin: 15px 0 22px;
  color: var(--marketing-muted);
  font-size: 14px;
  line-height: 1.55;
}
.marketing-use-case-content a {
  color: var(--marketing-blue);
  font-size: 13px;
  font-weight: 800;
}
.marketing-faq-section {
  display: grid;
  grid-template-columns: minmax(0, 0.85fr) minmax(0, 1.15fr);
  gap: 80px;
  padding: 110px 0 126px;
  border-top: 1px solid var(--marketing-line);
}
.marketing-faq-section h2 {
  font-size: clamp(38px, 4.7vw, 60px);
}
.marketing-faq-section > div {
  border-top: 1px solid var(--marketing-line);
}
.marketing-faq-section details {
  border-bottom: 1px solid var(--marketing-line);
}
.marketing-faq-section summary {
  padding: 23px 0;
