  }
  .marketing-faq-section {
    gap: 32px;
    padding-block: 80px 94px;
  }
}

/* The Product route presents the Record → Edit → Share mechanism as a visible workflow bench. */
.marketing-product-page {
  --product-panel: #0d1d63;
  --product-slate: #e6ebff;
  --product-coral: #ff886d;
}
.product-page-hero {
  display: grid;
  grid-template-columns: minmax(0, 0.94fr) minmax(480px, 1.06fr);
  gap: 76px;
  align-items: center;
  min-height: 680px;
  padding: 82px 0 116px;
}
.product-page-hero-copy h1,
.product-page-statement h2,
.product-area h2,
.product-page-close h2 {
  margin: 0;
  letter-spacing: -0.065em;
}
.product-page-hero-copy h1 {
  max-width: 630px;
  font-size: clamp(48px, 5.35vw, 76px);
  line-height: 0.96;
}
.product-page-hero-copy > p {
