  margin: 28px 0 36px;
  color: var(--marketing-muted);
  font-size: 19px;
  line-height: 1.6;
}
.product-workflow-bench {
  position: relative;
  display: grid;
  grid-template-columns: 112px minmax(0, 1fr);
  gap: 0;
  overflow: hidden;
  min-height: 500px;
  color: #fff;
