}
.product-bench-capture-copy {
  display: grid;
  gap: 4px;
  margin-top: 20px;
}
.product-bench-capture-copy strong,
.product-bench-guide strong,
.product-bench-deliver strong {
  font-size: 18px;
  letter-spacing: -0.035em;
}
.product-bench-capture-copy small,
.product-bench-guide small,
.product-bench-guide p,
.product-bench-deliver p {
