  gap: var(--space-4);
}
.command-list {
  display: grid;
  gap: var(--space-1);
}
.command-item {
  display: grid;
  gap: 2px;
  padding: var(--space-3);
  color: var(--color-text-primary);
  border-radius: var(--radius-md);
}
.command-item:hover,
.command-item:focus-visible {
  background: var(--color-brand-subtle);
  outline: 0;
}
.command-item span {
  color: var(--color-text-secondary);
