  background: var(--color-danger-subtle);
  border: 1px solid var(--color-danger);
  border-radius: var(--radius-lg);
}
.ui-form-error-summary:focus-within {
  outline: 3px solid var(--color-focus-ring);
  outline-offset: 2px;
}
.ui-form-error-summary h2 {
  margin: 0 0 var(--space-2);
  color: inherit;
  font-size: var(--font-size-lg);
}
.ui-form-error-summary p {
  margin: 0 0 var(--space-2);
}
.ui-form-error-summary ul {
  display: grid;
  gap: var(--space-1);
  margin: 0;
  padding-left: var(--space-5);
}
.ui-form-error-summary a {
  color: inherit;
  text-decoration: underline;
}

.ui-table-wrap {
  max-width: 100%;
  overflow-x: auto;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
}
.ui-table {
  width: 100%;
  min-width: 560px;
  border-collapse: collapse;
  color: var(--color-text-primary);
  background: var(--color-surface-raised);
  font-size: var(--font-size-md);
}
.ui-table caption {
  padding: var(--space-3) var(--space-4);
  color: var(--color-text-primary);
  font-size: var(--font-size-lg);
  font-weight: var(--font-weight-semibold);
  text-align: left;
}
.ui-table th,
.ui-table td {
  padding: var(--space-3) var(--space-4);
  border-top: 1px solid var(--color-border);
  text-align: left;
  vertical-align: middle;
}
.ui-table th {
  color: var(--color-text-secondary);
  background: var(--color-status-background);
  font-size: var(--font-size-sm);
  font-weight: var(--font-weight-semibold);
  white-space: nowrap;
}
.ui-table th button {
  padding: 0;
  color: inherit;
  background: transparent;
  border: 0;
  cursor: pointer;
  font: inherit;
  font-weight: inherit;
}
.ui-table th button:hover,
.ui-table th button:focus-visible {
  color: var(--color-brand-strong);
  text-decoration: underline;
  outline: 0;
}
.ui-table tbody tr:hover {
  background: var(--color-row-hover);
}
.ui-table tbody tr[aria-selected="true"] {
  background: var(--color-brand-subtle);
}
.ui-table-selection-cell {
  width: 44px;
  padding-inline: var(--space-3) !important;
}
.ui-table input[type="checkbox"] {
  accent-color: var(--color-brand);
}
.ui-list {
  min-width: 0;
}
.ui-list ul {
  display: grid;
  gap: var(--space-2);
  margin: 0;
  padding: 0;
  list-style: none;
}
.ui-list > ul > li {
  min-width: 0;
}
.ui-list-state {
  padding: var(--space-6);
  color: var(--color-text-secondary);
  background: var(--color-status-background);
  border-radius: var(--radius-md);
  text-align: center;
}
.ui-card {
  min-width: 0;
  color: var(--color-text-primary);
  background: var(--color-surface-raised);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-sm);
}
.ui-card-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: var(--space-4);
  padding: var(--space-4);
  border-bottom: 1px solid var(--color-border);
}
.ui-card-header h2,
.ui-card-header p {
  margin: 0;
}
.ui-card-header h2 {
  font-size: var(--font-size-lg);
}
.ui-card-header p {
  margin-top: var(--space-1);
  color: var(--color-text-secondary);
  font-size: var(--font-size-sm);
  line-height: var(--line-height-body);
}
.ui-card-actions {
  flex: 0 0 auto;
}
.ui-card-body {
  min-width: 0;
  padding: var(--space-4);
}
.ui-stat {
  display: grid;
  gap: var(--space-1);
  margin: 0;
  padding: var(--space-4);
  color: var(--color-text-primary);
  background: var(--color-surface-raised);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
}
.ui-stat dt {
  color: var(--color-text-secondary);
  font-size: var(--font-size-sm);
}
.ui-stat dd {
  margin: 0;
  font-size: var(--font-size-2xl);
  font-weight: var(--font-weight-bold);
  letter-spacing: -0.04em;
}
.ui-stat-supporting {
  font-size: var(--font-size-sm);
}
.ui-stat-up {
  color: var(--color-success);
}
.ui-stat-down {
  color: var(--color-danger);
}
.ui-stat-neutral {
  color: var(--color-text-secondary);
}
.ui-timeline {
  display: grid;
  gap: var(--space-5);
  margin: 0;
  padding: 0;
  list-style: none;
}
.ui-timeline li {
  position: relative;
  display: grid;
  grid-template-columns: 20px minmax(0, 1fr);
  gap: var(--space-3);
  min-width: 0;
}
.ui-timeline li:not(:last-child)::before {
  position: absolute;
  top: 20px;
  bottom: -24px;
  left: 9px;
  width: 1px;
  background: var(--color-border);
  content: "";
}
.ui-timeline-marker {
  position: relative;
  z-index: 1;
  width: 20px;
  height: 20px;
  margin-top: 1px;
  background: var(--color-surface-raised);
  border: 2px solid var(--color-border);
  border-radius: 50%;
}
.ui-timeline-complete .ui-timeline-marker {
  background: var(--color-success);
  border-color: var(--color-success);
}
.ui-timeline-current .ui-timeline-marker {
  background: var(--color-brand);
  border-color: var(--color-brand);
  box-shadow: var(--shadow-focus);
}
.ui-timeline-content {
  min-width: 0;
}
.ui-timeline-heading {
  display: flex;
  justify-content: space-between;
  gap: var(--space-3);
}
.ui-timeline-heading time {
  flex: 0 0 auto;
  color: var(--color-text-tertiary);
  font-size: var(--font-size-sm);
}
.ui-timeline-content p {
  margin: var(--space-1) 0 0;
  color: var(--color-text-secondary);
  font-size: var(--font-size-sm);
  line-height: var(--line-height-body);
}
.ui-progress {
  min-width: 0;
}
.ui-progress-label {
  display: flex;
  justify-content: space-between;
  gap: var(--space-3);
  margin-bottom: var(--space-2);
  color: var(--color-text-secondary);
  font-size: var(--font-size-sm);
}
.ui-progress-track {
  height: 8px;
  overflow: hidden;
  background: var(--color-progress-track);
  border-radius: var(--radius-pill);
}
.ui-progress-value {
  display: block;
  height: 100%;
  background: var(--color-brand);
  border-radius: inherit;
}
.ui-progress-indeterminate .ui-progress-value {
  width: 38% !important;
  animation: ui-progress-slide var(--motion-duration-skeleton) ease-in-out infinite alternate;
}
@keyframes ui-progress-slide {
  from {
    transform: translateX(-100%);
  }
  to {
    transform: translateX(260%);
  }
}
.ui-virtualized-collection {
  max-width: 100%;
  overflow: auto;
  overscroll-behavior: contain;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
}
.ui-virtualized-track {
  position: relative;
  min-width: 0;
}
.ui-virtualized-window {
  position: absolute;
  inset: 0 var(--space-2) auto;
  min-width: 0;
}
.ui-virtualized-window > [role="listitem"] {
  min-width: 0;
}

/* Iconography and media presentation. */
.ui-icon {
  display: block;
  flex: 0 0 auto;
}
.ui-media-image {
  display: block;
  max-width: 100%;
  height: auto;
  object-fit: contain;
}
.ui-media-fallback {
  display: grid;
  place-items: center;
  min-width: 0;
  min-height: 0;
  overflow: hidden;
  color: var(--color-text-tertiary);
  background: var(--color-status-background);
  border: 1px solid var(--color-border);
  aspect-ratio: inherit;
}
.ui-aspect-ratio {
  position: relative;
  width: 100%;
  overflow: hidden;
}
.ui-aspect-ratio > * {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
}
.ui-thumbnail {
  background: var(--color-status-background);
  border-radius: var(--radius-md);
}
.ui-thumbnail .ui-media-image {
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.ui-thumbnail .ui-media-fallback {
  width: 100%;
  height: 100%;
  border: 0;
  border-radius: inherit;
}
.ui-device-frame {
  position: relative;
  width: 100%;
  margin: 0;
  padding: var(--space-2);
  background: var(--color-text-primary);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-xl);
  box-shadow: var(--shadow-md);
}
.ui-device-frame-desktop {
  max-width: 1200px;
}
.ui-device-frame-tablet {
  max-width: 760px;
}
.ui-device-frame-phone {
  max-width: 390px;
}
.ui-device-frame-chrome {
  display: flex;
  gap: 6px;
  padding: 6px 8px;
}
.ui-device-frame-chrome span {
  width: 6px;
  height: 6px;
  background: var(--color-text-tertiary);
  border-radius: 50%;
}
.ui-device-frame-screen {
  overflow: hidden;
  background: var(--color-surface-raised);
  border-radius: var(--radius-md);
}
.ui-device-frame-screen > * {
  display: block;
  width: 100%;
  max-width: 100%;
}

/* Local component workbench. */
.workbench {
  min-height: 100vh;
  padding: var(--space-9) clamp(var(--space-4), 5vw, var(--space-10));
  color: var(--color-text-primary);
  background: var(--color-canvas);
}
.workbench-header,
.workbench-grid {
  width: min(100%, 1320px);
  margin-inline: auto;
}
.workbench-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: var(--space-7);
  margin-bottom: var(--space-7);
}
.workbench-header h1 {
  max-width: 720px;
  margin: var(--space-2) 0 0;
  font-size: clamp(30px, 4vw, 48px);
  letter-spacing: -0.05em;
  line-height: var(--line-height-tight);
}
.workbench-intro {
  max-width: 680px;
  margin: var(--space-4) 0 0;
  color: var(--color-text-secondary);
  line-height: var(--line-height-relaxed);
}
.workbench-header-actions {
  display: flex;
  align-items: center;
  gap: var(--space-3);
  flex-wrap: wrap;
  justify-content: flex-end;
}
.workbench-segmented {
  display: inline-flex;
  padding: 3px;
  background: var(--color-surface-raised);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
}
.workbench-segmented button {
  min-height: 36px;
  padding: 0 var(--space-3);
  color: var(--color-text-secondary);
  background: transparent;
  border: 0;
  border-radius: var(--radius-sm);
  cursor: pointer;
  font: inherit;
  font-size: var(--font-size-sm);
  font-weight: var(--font-weight-semibold);
}
.workbench-segmented button:hover,
.workbench-segmented button:focus-visible {
  color: var(--color-brand-strong);
  background: var(--color-brand-subtle);
  outline: 0;
}
.workbench-segmented button[aria-pressed="true"] {
  color: var(--color-on-brand);
  background: var(--color-brand);
}
.workbench > .ui-banner {
  width: min(100%, 1320px);
  margin: 0 auto var(--space-7);
}
.workbench-grid {
  display: grid;
  gap: var(--space-7);
}
.workbench-section {
  display: grid;
  gap: var(--space-4);
  min-width: 0;
}
.workbench-section-heading {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: var(--space-4);
}
.workbench-section-heading h2 {
  margin: var(--space-1) 0 0;
  font-size: var(--font-size-2xl);
  letter-spacing: -0.04em;
}
.workbench-card-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: var(--space-4);
  min-width: 0;
}
.workbench-card-grid > .ui-card,
.workbench-media-grid > .ui-card {
  min-width: 0;
}
.workbench-card-grid .ui-card-body,
.workbench-media-grid .ui-card-body {
  display: grid;
  gap: var(--space-4);
}
.workbench-media-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: var(--space-4);
  min-width: 0;
}
.workbench-media-grid .ui-thumbnail,
.workbench-media-grid .ui-aspect-ratio {
  min-width: 0;
}
.workbench-media-grid .ui-device-frame {
  width: min(100%, 220px);
  margin-inline: auto;
}
.workbench-tab-copy {
  margin: 0;
  color: var(--color-text-secondary);
}

@media (max-width: 900px) {
  .workbench-header {
    display: grid;
  }
  .workbench-header-actions {
    justify-content: flex-start;
  }
  .workbench-media-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 620px) {
  .workbench {
    padding: var(--space-6) var(--space-4);
  }
  .workbench-header h1 {
    font-size: 32px;
  }
  .workbench-card-grid,
  .workbench-media-grid {
    grid-template-columns: minmax(0, 1fr);
  }
  .workbench-section-heading {
    align-items: flex-start;
    flex-direction: column;
  }
  .workbench-header-actions {
    align-items: stretch;
    flex-direction: column;
  }
  .workbench-segmented {
    width: 100%;
  }
  .workbench-segmented button {
    flex: 1 1 50%;
  }
}

