/* Reference Record → Edit → Share laboratory. */
.ui-lab {
  min-height: 100vh;
  padding: var(--space-8) clamp(var(--space-4), 5vw, var(--space-10));
  color: var(--color-text-primary);
  background: var(--color-canvas);
}
.ui-lab-header,
.ui-lab-stage-nav,
.ui-lab-stage {
  width: min(100%, 1320px);
  margin-inline: auto;
}
.ui-lab-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: var(--space-7);
  margin-bottom: var(--space-6);
}
.ui-lab-header-copy {
  display: grid;
  gap: var(--space-5);
  min-width: 0;
}
.ui-lab-header-copy h1 {
  max-width: none;
  margin: var(--space-1) 0 var(--space-2);
  font-size: clamp(32px, 4vw, 56px);
}
.ui-lab-header-copy p:last-child {
  max-width: 560px;
  margin: 0;
  color: var(--color-text-secondary);
  font-size: var(--font-size-lg);
  line-height: var(--line-height-relaxed);
}
.ui-lab-header-actions {
  display: grid;
  justify-items: end;
  gap: var(--space-4);
}
.ui-lab-stage-nav {
  display: flex;
  gap: var(--space-2);
  margin-bottom: var(--space-7);
  padding: var(--space-2);
  overflow-x: auto;
  background: var(--color-surface-raised);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
}
.ui-lab-stage-nav button {
  display: inline-flex;
  align-items: center;
  gap: var(--space-2);
  min-width: 150px;
  min-height: 44px;
  padding: 0 var(--space-4);
  color: var(--color-text-secondary);
  background: transparent;
  border: 0;
  border-radius: var(--radius-md);
  cursor: pointer;
  font: inherit;
  font-size: var(--font-size-md);
  font-weight: var(--font-weight-semibold);
  text-align: left;
}
.ui-lab-stage-nav button span {
  color: var(--color-text-tertiary);
  font-size: var(--font-size-sm);
}
.ui-lab-stage-nav button:hover,
.ui-lab-stage-nav button:focus-visible {
  color: var(--color-brand-strong);
  background: var(--color-brand-subtle);
  outline: 0;
}
.ui-lab-stage-nav button[aria-current="step"] {
  color: var(--color-brand-strong);
  background: var(--color-brand-subtle);
  box-shadow: inset 0 -2px 0 var(--color-brand);
}
.ui-lab-stage {
  display: grid;
  gap: var(--space-6);
}
.ui-lab-stage-heading {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: var(--space-5);
}
.ui-lab-stage-heading h2 {
  margin: var(--space-1) 0 var(--space-2);
  font-size: clamp(24px, 3vw, 36px);
}
.ui-lab-stage-heading p:last-child {
  max-width: 640px;
  margin: 0;
  color: var(--color-text-secondary);
  line-height: var(--line-height-body);
}
.ui-lab-choice-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: var(--space-4);
}
.ui-lab-choice-grid .ui-card-body {
  display: grid;
  gap: var(--space-4);
}
.ui-lab-capture-preview {
  position: relative;
  min-height: 170px;
  overflow: hidden;
  background: linear-gradient(135deg, #eef2ff, #f8faff);
  border: 1px solid #e0e5f0;
  border-radius: 12px;
}
.ui-lab-capture-preview::before {
  position: absolute;
  inset: 15px;
  background: #fff;
  border-radius: 7px;
  box-shadow: 0 8px 22px rgb(16 24 40 / 10%);
  content: "";
}
.ui-lab-capture-preview > span {
  position: absolute;
  z-index: 1;
  display: block;
}
.ui-lab-capture-browser-bar {
  top: 28px;
  left: 30px;
  width: 46%;
  height: 8px;
  background: #cbd3f7;
  border-radius: 999px;
}
.ui-lab-capture-sidebar {
  top: 49px;
  left: 30px;
  bottom: 30px;
  width: 20%;
  background: #eff2f8;
  border-radius: 4px;
}
.ui-lab-capture-panel {
  top: 51px;
  right: 30px;
  width: 49%;
  height: 48px;
  background: linear-gradient(135deg, #dfe6ff, #f5f7ff);
  border-radius: 5px;
}
.ui-lab-capture-panel-small {
  top: 108px;
  width: 31%;
  height: 30px;
  background: #eef1f7;
}
.ui-lab-capture-preview-2 {
  background: linear-gradient(135deg, #f0f8ed, #fffdf5);
}
.ui-lab-capture-preview-2 .ui-lab-capture-panel {
  background: linear-gradient(135deg, #f9edc9, #dff2e2);
}
.ui-lab-capture-preview-3 {
  background: linear-gradient(135deg, #f8efff, #eef4ff);
}
.ui-lab-capture-preview-3 .ui-lab-capture-panel {
  background: linear-gradient(135deg, #f1d8ff, #dfe4ff);
}
.ui-lab-editor {
  display: grid;
  grid-template-columns: minmax(180px, 220px) minmax(0, 1fr) minmax(220px, 280px);
  min-width: 0;
  min-height: 460px;
  overflow: hidden;
  background: var(--color-surface-raised);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-xl);
  box-shadow: var(--shadow-sm);
}
.ui-lab-step-rail,
.ui-lab-inspector {
  min-width: 0;
  padding: var(--space-5);
  background: var(--color-surface);
}
.ui-lab-step-rail {
  border-right: 1px solid var(--color-border);
}
.ui-lab-inspector {
  border-left: 1px solid var(--color-border);
}
.ui-lab-step-rail strong {
  font-size: var(--font-size-md);
}
.ui-lab-step-rail ol {
  display: grid;
  gap: var(--space-2);
  margin: var(--space-4) 0 var(--space-5);
  padding: 0;
  list-style: none;
}
.ui-lab-step-rail button {
  display: grid;
  grid-template-columns: 24px minmax(0, 1fr);
  gap: var(--space-2);
  width: 100%;
  min-height: 44px;
  padding: var(--space-2);
  color: var(--color-text-secondary);
  background: transparent;
  border: 0;
  border-radius: var(--radius-md);
  cursor: pointer;
  font: inherit;
  font-size: var(--font-size-sm);
  text-align: left;
}
.ui-lab-step-rail button span {
  color: var(--color-text-tertiary);
}
.ui-lab-step-rail button:hover,
.ui-lab-step-rail button:focus-visible,
.ui-lab-step-rail button[aria-current="step"] {
  color: var(--color-brand-strong);
  background: var(--color-brand-subtle);
  outline: 0;
}
.ui-lab-canvas {
  display: grid;
  place-items: center;
  min-width: 0;
  padding: var(--space-6);
  background: var(--color-canvas);
}
.ui-lab-canvas .ui-device-frame {
  max-width: 760px;
}
.ui-lab-screen-preview {
  display: grid;
  align-content: start;
  gap: var(--space-4);
  min-height: 300px;
  padding: var(--space-6);
  color: var(--color-text-primary);
  background: var(--color-surface-raised);
}
.ui-lab-screen-bar {
  display: block;
  width: 36%;
  height: 10px;
  background: var(--color-brand-subtle);
  border-radius: var(--radius-pill);
}
.ui-lab-screen-title {
  font-size: clamp(18px, 3vw, 28px);
  font-weight: var(--font-weight-bold);
  letter-spacing: -0.04em;
}
.ui-lab-screen-card {
  display: block;
  width: 100%;
  height: 86px;
  background: var(--color-status-background);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
}
.ui-lab-screen-card.short {
  width: 68%;
  height: 52px;
}
.ui-lab-tab-panel {
  margin: 0;
  padding: var(--space-5) 0;
  color: var(--color-text-secondary);
}

@media (max-width: 900px) {
  .ui-lab-header {
    display: grid;
  }
  .ui-lab-header-actions {
    justify-items: start;
  }
  .ui-lab-choice-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .ui-lab-editor {
    grid-template-columns: 180px minmax(0, 1fr);
  }
  .ui-lab-inspector {
    grid-column: 1 / -1;
    border-top: 1px solid var(--color-border);
    border-left: 0;
  }
}

@media (max-width: 760px) {
  .ui-lab {
    padding: var(--space-6) var(--space-4);
  }
  .ui-lab-stage-nav button {
    min-width: 120px;
  }
  .ui-lab-choice-grid {
    grid-template-columns: minmax(0, 1fr);
  }
  .ui-lab-editor {
    display: flex;
    flex-direction: column;
  }
  .ui-lab-step-rail {
    border-right: 0;
    border-bottom: 1px solid var(--color-border);
  }
  .ui-lab-step-rail ol {
    grid-template-columns: repeat(3, minmax(0, 1fr));
    overflow-x: auto;
  }
  .ui-lab-step-rail li {
    min-width: 150px;
  }
  .ui-lab-inspector {
    border-top: 1px solid var(--color-border);
  }
  .ui-lab-stage-heading {
    align-items: flex-start;
    flex-direction: column;
  }
}

