  height: 1px;
  flex: 1;
  background: var(--color-border);
}
.auth-provider-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-3);
}
.auth-provider-grid .ui-button {
  min-height: 76px;
  flex-direction: column;
  gap: 6px;
}
.auth-provider-icon {
  display: inline-grid;
  place-items: center;
  width: 24px;
  height: 24px;
  font-size: 22px;
  font-weight: 800;
  line-height: 1;
}
.auth-provider-icon-google {
  color: #4285f4;
}
.auth-provider-icon-microsoft {
  color: #f25022;
}
.auth-provider-icon-sso {
  color: #4c586a;
}
.auth-terms {
  max-width: 440px;
  margin: var(--space-5) auto 0;
  color: var(--color-text-secondary);
  font-size: var(--font-size-sm);
  line-height: var(--line-height-body);
  text-align: center;
}
.auth-terms a {
  color: var(--color-text-primary);
  font-weight: var(--font-weight-bold);
}
.auth-route-link {
  color: var(--color-accent);
  font-size: var(--font-size-sm);
  font-weight: var(--font-weight-bold);
  text-decoration: none;
}
.auth-route-link:hover {
  text-decoration: underline;
}
.auth-proof {
  display: grid;
  align-content: center;
  gap: 34px;
  min-width: 0;
  padding: 72px 5vw;
  color: #fff;
  background: #1d2a3a;
  overflow: hidden;
}
.auth-proof-intro h2 {
  margin: 0;
  font-size: clamp(28px, 3vw, 42px);
  line-height: 1.05;
  letter-spacing: -0.05em;
  text-align: center;
}
.auth-proof-badges {
  display: grid;
  grid-template-columns: repeat(6, minmax(70px, 1fr));
  gap: 10px;
  margin-top: 34px;
}
.auth-proof-badges span {
  display: grid;
  min-height: 92px;
  place-items: center;
  padding: 8px;
  color: #182333;
  background: #f2f3f2;
  border-bottom: 12px solid #f0b43c;
  clip-path: polygon(0 0, 100% 0, 100% 82%, 50% 100%, 0 82%);
  font-size: 10px;
  font-weight: 800;
  text-align: center;
  text-transform: uppercase;
}
.auth-proof-badges span:nth-child(2n) {
  border-bottom-color: #7a72ce;
}
.auth-proof-badges span:nth-child(3n) {
  border-bottom-color: #f0503d;
}
.auth-proof-cards {
  display: grid;
  grid-template-columns: repeat(3, minmax(220px, 1fr));
  gap: 20px;
  width: max-content;
}
.auth-proof-cards article {
  display: grid;
  gap: 10px;
  width: 280px;
  min-height: 310px;
  padding: 24px;
  color: #182333;
  background: #fff;
  border-radius: 14px;
}
.auth-proof-cards article strong {
  font-size: 20px;
}
.auth-proof-cards article p {
  margin: 0;
  color: #3b4655;
  font-size: 15px;
  line-height: 1.45;
}
.auth-proof-cards article b {
  margin-top: auto;
  font-size: 14px;
}
.auth-proof-cards article small {
  color: #647084;
  font-size: 12px;
}
.auth-proof-cards article em {
  display: grid;
  margin-top: 12px;
  padding-top: 14px;
  border-top: 1px solid #e5e7eb;
  color: #182333;
  font-size: 28px;
  font-style: normal;
  font-weight: 800;
}
.auth-proof-cards article em small {
  font-size: 13px;
  font-weight: 500;
}
.auth-proof-trust {
  text-align: center;
}
.auth-proof-trust p {
  margin: 0 0 20px;
  color: #9ba6b6;
  font-size: 14px;
  font-weight: 700;
}
.auth-proof-trust div {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 24px;
  color: #9ba6b6;
  font-size: 15px;
  font-weight: 800;
}
.auth-card-wrap {
  display: grid;
  gap: var(--space-5);
  width: min(100%, 440px);
}
.auth-brand {
  color: var(--color-text-primary);
  font-size: var(--font-size-xl);
  font-weight: var(--font-weight-bold);
  letter-spacing: -0.05em;
  text-align: center;
}
.auth-card-wrap .ui-card-body {
  display: grid;
  gap: var(--space-4);
}
.auth-form {
  display: grid;
  gap: var(--space-4);
}
.auth-links {
  display: flex;
  justify-content: center;
  gap: var(--space-2);
  flex-wrap: wrap;
  padding-top: var(--space-2);
  border-top: 1px solid var(--color-border);
}
.auth-success {
  padding: var(--space-3);
  color: var(--color-success);
  background: var(--color-success-subtle);
  border: 1px solid var(--color-connection-success-border);
  border-radius: var(--radius-md);
  font-size: var(--font-size-md);
  line-height: var(--line-height-body);
}
@media (max-width: 800px) {
  .auth-page-signup {
    grid-template-columns: 1fr;
    padding-inline: var(--space-4);
    background: #fff;
  }
  .auth-page-signup .auth-card-wrap {
    width: min(100%, 520px);
    padding-block: 48px;
  }
  .auth-page-signup .auth-card-wrap::before {
    inset: 0;
  }
  .auth-provider-grid {
    gap: var(--space-2);
  }
  .auth-proof {
    display: none;
  }
}

/* Account profile settings use the same calm, card-based workspace language. */
.profile-settings {
  display: grid;
  gap: var(--space-6);
}
.profile-settings-heading {
  display: flex;
  justify-content: space-between;
  gap: var(--space-6);
}
.profile-settings-heading h1 {
  margin: 0 0 var(--space-2);
  font-size: clamp(32px, 4vw, 48px);
}
.profile-settings-description {
  max-width: 560px;
  margin: 0;
  color: var(--color-text-secondary);
  line-height: var(--line-height-body);
}
.profile-settings-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.2fr) minmax(280px, 0.8fr);
  gap: var(--space-6);
}
.profile-settings-grid .ui-card {
  min-width: 0;
}
.profile-settings-form {
  display: grid;
  gap: var(--space-5);
}
.profile-settings-actions {
  display: flex;
  justify-content: flex-end;
}
.profile-settings-success {
  padding: var(--space-3);
  color: var(--color-success);
  background: var(--color-success-subtle);
  border: 1px solid var(--color-connection-success-border);
  border-radius: var(--radius-md);
  font-size: var(--font-size-md);
}

/* Workspace member administration stays in Settings and keeps operational controls contextual. */
.member-settings {
  display: grid;
  gap: var(--space-6);
}
.member-settings-heading h1 {
  margin: 0 0 var(--space-2);
  font-size: clamp(32px, 4vw, 48px);
}
.member-settings-heading p:last-child {
  max-width: 640px;
  margin: 0;
  color: var(--color-text-secondary);
  line-height: var(--line-height-body);
}
.member-settings-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.2fr) minmax(280px, 0.8fr);
  gap: var(--space-6);
}
.member-table-wrap {
  max-width: 100%;
  overflow-x: auto;
}
.member-table {
  width: 100%;
  min-width: 560px;
  border-collapse: collapse;
}
.member-table th,
.member-table td {
  padding: var(--space-3);
  border-top: 1px solid var(--color-border);
  text-align: left;
  vertical-align: middle;
}
.member-table th {
  color: var(--color-text-secondary);
  font-size: var(--font-size-sm);
  font-weight: var(--font-weight-semibold);
}
.member-table td strong,
.member-table td small {
  display: block;
}
.member-table td small {
  margin-top: 2px;
  color: var(--color-text-secondary);
}
.member-table-actions {
  width: 1%;
  white-space: nowrap;
}
.member-role-label {
  display: inline-flex;
  padding: 3px var(--space-2);
  color: var(--color-text-secondary);
  background: var(--color-status-background);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-pill);
  font-size: var(--font-size-sm);
  font-weight: var(--font-weight-semibold);
  text-transform: capitalize;
}
.member-invite-form {
  display: grid;
}
.member-empty {
  margin: 0;
  color: var(--color-text-secondary);
}
.member-settings-actions,
.member-confirmation-actions {
  display: flex;
  justify-content: flex-end;
  gap: var(--space-3);
  margin-top: var(--space-4);
}

@media (max-width: 760px) {
  .profile-settings {
    padding-top: var(--space-5);
  }
  .profile-settings-grid {
    grid-template-columns: minmax(0, 1fr);
  }
  .member-settings-grid {
    grid-template-columns: minmax(0, 1fr);
  }
  .profile-settings-actions {
    justify-content: stretch;
  }
  .profile-settings-actions .ui-button {
    width: 100%;
  }
}

@media (max-width: 680px) {
  .ui-table {
    min-width: 0;
  }
  .ui-table thead {
    position: absolute;
    width: 1px;
    height: 1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
  }
  .ui-table,
  .ui-table tbody,
  .ui-table tr,
  .ui-table td {
    display: block;
    width: 100%;
  }
  .ui-table tr {
    padding: var(--space-3);
    border-top: 1px solid var(--color-border);
  }
  .ui-table tbody tr:first-child {
    border-top: 0;
  }
  .ui-table td {
    display: grid;
    grid-template-columns: minmax(88px, 34%) minmax(0, 1fr);
    gap: var(--space-3);
    padding: var(--space-2) 0;
    border: 0;
  }
  .ui-table td::before {
    color: var(--color-text-secondary);
    content: attr(data-label);
    font-size: var(--font-size-sm);
    font-weight: var(--font-weight-semibold);
  }
  .ui-table .ui-table-selection-cell {
    display: block;
    width: auto;
    padding: 0 0 var(--space-2) !important;
  }
  .ui-table .ui-table-selection-cell::before {
    content: none;
  }
}

@media (max-width: 640px) {
  .member-table {
    min-width: 0;
  }
  .member-table thead {
    position: absolute;
    width: 1px;
    height: 1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
  }
  .member-table,
  .member-table tbody,
  .member-table tr,
  .member-table td {
    display: block;
    width: 100%;
  }
  .member-table tr {
    padding: var(--space-3);
    border-top: 1px solid var(--color-border);
  }
  .member-table tbody tr:first-child {
    border-top: 0;
  }
  .member-table td {
    display: grid;
    grid-template-columns: minmax(84px, 34%) minmax(0, 1fr);
    gap: var(--space-3);
    padding: var(--space-2) 0;
    border: 0;
  }
  .member-table td::before {
    color: var(--color-text-secondary);
    content: attr(data-label);
    font-size: var(--font-size-sm);
    font-weight: var(--font-weight-semibold);
  }
  .member-table-actions {
    width: auto;
    white-space: normal;
  }
  .member-confirmation-actions {
    flex-direction: column-reverse;
  }
  .member-confirmation-actions .ui-button {
    width: 100%;
  }
}
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
    animation-duration: 0.01ms !important;
    transition-duration: 0.01ms !important;
  }
}

/* AppShell uses the same workspace chrome as the reference home surfaces. */
.app-shell-sidebar.home-sidebar {
  width: 306px;
  flex: 0 0 306px;
  min-height: 100vh;
  padding: 16px 18px 18px;
  background: #f7f9fc;
  border-right-color: #e5e8ee;
}
.app-shell-sidebar.home-sidebar .ui-sidebar-header {
  display: block;
}
.app-shell-sidebar.home-sidebar .ui-sidebar-footer {
  gap: 24px;
  padding-top: 0;
}
.app-shell-sidebar .app-workspace-switcher.home-workspace-switcher {
  position: relative;
  grid-template-columns: 30px minmax(0, 1fr) auto 14px;
  margin: 0;
  padding: 0 5px 20px;
  background: transparent;
  border: 0;
  border-radius: 0;
}
.app-shell-sidebar .app-workspace-switcher-select {
  position: absolute;
  inset: 0 0 20px;
  z-index: 1;
  width: 100%;
  max-width: none;
  padding: 0;
  cursor: pointer;
  opacity: 0;
}
.app-shell-sidebar .app-workspace-setup {
  grid-column: 3;
  display: grid;
  place-items: center;
  width: 26px;
  height: 26px;
  margin-left: auto;
  color: #4b4ee8;
  background: #eef0ff;
  border: 1px solid #c6ccff;
  border-radius: 8px;
  font-size: 17px;
  font-weight: 700;
}
.app-shell-sidebar .home-chevron {
  grid-column: 4;
}
.app-shell-sidebar .home-primary-nav {
  display: grid;
  gap: 4px;
}
.app-shell-sidebar .app-shell-nav-link.home-nav-item {
  min-height: 40px;
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 0 9px;
  color: #4c5668;
  border-radius: 8px;
  font-size: 16px;
  font-weight: 400;
}
.app-shell-sidebar .app-shell-nav-link.home-nav-item:hover,
.app-shell-sidebar .app-shell-nav-link.home-nav-item:focus-visible {
  color: #263249;
  background: #edf1f7;
}
.app-shell-sidebar .app-shell-nav-link.home-nav-item[data-active="true"] {
  color: #263249;
  background: #fff;
  box-shadow: 0 1px 3px rgb(16 24 40 / 10%);
}
.app-shell-sidebar .app-shell-nav-link.home-nav-item svg,
.app-shell-sidebar .app-shell-nav-link.home-nav-item .app-shell-nav-glyph {
  width: 20px;
  height: 20px;
  flex: 0 0 20px;
  color: #586274;
}
.app-shell-sidebar .app-shell-nav-link.home-nav-item[data-active="true"] svg,
.app-shell-sidebar .app-shell-nav-link.home-nav-item[data-active="true"] .app-shell-nav-glyph {
  color: #4b4ee8;
}
.app-shell-nav-glyph {
  position: relative;
  display: inline-block;
}
.app-shell-nav-glyph-agents::before {
  position: absolute;
  inset: 3px 6px;
  border: 2px solid currentColor;
  border-radius: 50%;
  content: "";
}
.app-shell-nav-glyph-agents::after {
  position: absolute;
  left: 4px;
  top: 3px;
  width: 12px;
  height: 2px;
  background: currentColor;
  box-shadow: 3px 5px 0 currentColor;
  content: "";
  transform: rotate(-35deg);
}
.app-shell-nav-glyph-routes::before,
.app-shell-nav-glyph-routes::after {
  position: absolute;
  width: 6px;
  height: 6px;
  border: 2px solid currentColor;
  border-radius: 50%;
  content: "";
}
.app-shell-nav-glyph-routes::before {
  left: 1px;
  top: 2px;
}
.app-shell-nav-glyph-routes::after {
  right: 1px;
  bottom: 2px;
}
.app-shell-sidebar .home-nav-label {
  margin: 16px 0 4px;
  color: #737c8d;
  font-size: 13px;
  font-weight: 600;
}
.app-shell-sidebar .home-nav-item em {
  margin-left: auto;
  padding: 3px 8px;
  color: #5263ed;
  background: #eef0ff;
  border: 1px solid #c6ccff;
  border-radius: 999px;
  font-size: 12px;
  font-style: normal;
}
.app-shell-sidebar .app-shell-settings-link {
  margin-top: 8px;
}
.app-shell-sidebar .home-account-row {
  grid-template-columns: 1fr 26px 26px auto;
}
.app-shell-sidebar .home-account-row .ui-dropdown {
  margin-left: 0;
}
.app-shell-sidebar .app-user-avatar {
  width: 30px;
  height: 30px;
}
.main-content.home-main {
  min-width: 0;
  flex: 1;
  background: #fff;
}
.app-shell-header.home-topbar {
  height: 64px;
  min-height: 64px;
  padding: 0 22px;
  background: #fff;
  border-bottom-color: #e6e9ef;
}
.app-shell-header.home-topbar .ui-header-content {
  gap: 14px;
}
.app-shell-home-link {
  display: grid;
  place-items: center;
  width: 28px;
  height: 28px;
  color: #4b5566;
}
.app-shell-home-link svg {
  width: 19px;
  height: 19px;
}
.app-shell-breadcrumb {
  gap: 9px;
  font-size: 15px;
  font-weight: 600;
}
.app-shell-breadcrumb-separator {
  color: #737c8d;
  font-size: 22px;
  font-weight: 400;
}
.app-shell-header-actions {
  gap: 26px;
}
.app-shell-header-actions .home-earn {
  gap: 8px;
  color: #4d5768;
  font-size: 15px;
  font-weight: 600;
}
.app-shell-command-trigger.home-search {
  min-width: 252px;
  min-height: 40px;
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 0 10px;
  color: #596273;
  background: #fff;
  border: 1px solid #e0e4ec;
  border-radius: 9px;
  font: inherit;
  text-align: left;
  box-shadow: 0 1px 2px rgb(16 24 40 / 4%);
}
.app-shell-command-trigger.home-search svg {
  width: 18px;
  height: 18px;
}
.app-shell-command-trigger.home-search span {
  flex: 1;
}
.app-shell-command-trigger.home-search kbd {
  padding: 2px 5px;
  color: #6e7786;
  background: #f5f6f8;
  border: 1px solid #e4e7ed;
