/* Authoring editor: a calm, high-contrast workspace for the capture-to-share flow. */
.editor-shell {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  color: #e9edfb;
  background: #0d1322;
  font-family:
    Inter,
    ui-sans-serif,
    system-ui,
    -apple-system,
    BlinkMacSystemFont,
    "Segoe UI",
    sans-serif;
}
.editor-readonly-banner {
  min-height: 32px;
  display: flex;
  align-items: center;
  padding: 0 22px;
  color: #f5d58a;
  background: #2c2417;
  border-bottom: 1px solid #59451e;
  font-size: 12px;
}
.editor-topbar {
  min-height: 64px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  padding: 0 22px;
  background: #11192a;
  border-bottom: 1px solid #26334a;
}
.editor-topbar-left,
.editor-topbar-actions {
  display: flex;
  align-items: center;
  min-width: 0;
  gap: 14px;
}
.editor-back-link {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  color: #aab7d2;
  font-size: 13px;
  font-weight: 650;
  white-space: nowrap;
}
.editor-back-link:hover,
.editor-back-link:focus-visible {
  color: #fff;
}
.editor-divider {
  width: 1px;
  height: 22px;
  background: #2d3a51;
}
.editor-title-input {
  min-width: 180px;
  max-width: min(420px, 34vw);
  padding: 7px 9px;
  color: #f4f6ff;
  background: transparent;
  border: 1px solid transparent;
  border-radius: 7px;
  font-size: 14px;
  font-weight: 700;
  letter-spacing: -0.02em;
}
.editor-title-input:focus {
  outline: 2px solid #6b7cff;
  outline-offset: 1px;
  border-color: #4353b7;
}
.editor-title-input:disabled {
  opacity: 0.9;
}
.editor-save-state {
  display: inline-flex;
  align-items: center;
  min-height: 24px;
  padding: 0 9px;
  color: #9bacbf;
  background: #1b263b;
  border: 1px solid #2a3852;
  border-radius: 999px;
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 11px;
  white-space: nowrap;
}
.editor-save-saved {
  color: #a8e5c3;
}
.editor-save-error {
  color: #ffaeae;
}
.editor-button,
.editor-small-button {
  min-height: 36px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  padding: 0 14px;
  color: #dce3f7;
  background: #1b263b;
  border: 1px solid #34435e;
  border-radius: 8px;
  font: inherit;
  font-size: 13px;
  font-weight: 700;
  cursor: pointer;
  transition:
    background 160ms ease,
    border-color 160ms ease,
    transform 160ms ease;
}
.editor-button:hover,
.editor-small-button:hover {
  background: #263654;
  border-color: #4c5e83;
}
.editor-button:active,
.editor-small-button:active {
  transform: translateY(1px);
}
.editor-button:disabled,
.editor-small-button:disabled {
  opacity: 0.45;
  cursor: not-allowed;
  transform: none;
}
.editor-button-primary {
  color: #fff;
  background: #4d56e8;
  border-color: #5d67f3;
  box-shadow: 0 5px 14px rgb(77 86 232 / 20%);
}
.editor-button-primary:hover {
  background: #5a63f2;
  border-color: #7079ff;
}
.editor-button-secondary {
