  }
  .editor-step-list {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .editor-canvas {
    padding-inline: 14px;
  }
  .editor-capture-entry {
    grid-template-columns: 1fr;
  }
  .editor-capture-actions {
    justify-content: flex-start;
  }
}
@media (prefers-reduced-motion: reduce) {
  .editor-button,
  .editor-small-button,
  .editor-step-card,
  .editor-hotspot {
    transition: none;
    animation: none;
