/* Supademo pricing reference surface. The page keeps the public chrome shared
   with the marketing pages while giving pricing its own quiet, editorial grid. */
.marketing-public-chrome {
  position: relative;
  z-index: 20;
  background: rgb(255 255 255 / 92%);
  backdrop-filter: blur(12px);
}
.marketing-announcement-strip {
  display: flex;
  overflow: hidden;
  border-bottom: 1px solid #e6e9f0;
  background: #fbfcff;
}
.marketing-announcement-strip > a {
  flex: 0 0 50%;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 10px;
  min-height: 38px;
  padding: 0 24px;
  color: #56627a;
  font-size: 11px;
  text-decoration: none;
}
.marketing-announcement-strip > a + a {
  border-left: 1px solid #e6e9f0;
}
.marketing-announcement-strip strong {
  color: #131d32;
  font-weight: 800;
}
.marketing-announcement-strip span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.marketing-announcement-arrow {
  color: #4c57e8;
  font-size: 15px;
  font-weight: 800;
}
.marketing-nav {
  position: relative;
  min-height: 76px;
  padding-block: 10px;
}
.marketing-logo {
  font-family: Georgia, "Times New Roman", serif;
  font-weight: 700;
}
.marketing-logo span {
  width: 30px;
  height: 30px;
  color: #fff;
  background: #07182e;
  border-radius: 50%;
  font-family: Georgia, "Times New Roman", serif;
  font-size: 15px;
}
.marketing-nav nav {
  gap: 26px;
}
.marketing-nav nav > a,
.marketing-menu > summary {
  color: #25324b;
  font-size: 13px;
  font-weight: 700;
  list-style: none;
  cursor: pointer;
}
.marketing-menu > summary::-webkit-details-marker {
  display: none;
}
.marketing-menu > summary::after {
  display: inline-block;
  margin-left: 5px;
  color: #7e8aa2;
  content: "⌄";
  font-size: 12px;
  transform: translateY(-1px);
}
.marketing-menu[open] > summary::after {
  transform: rotate(180deg) translateY(-1px);
}
.marketing-menu-panel {
  position: absolute;
  top: calc(100% + 10px);
  left: 50%;
  display: grid;
  min-width: 190px;
  gap: 4px;
  padding: 9px;
  background: #fff;
  border: 1px solid #e3e7ef;
  border-radius: 12px;
  box-shadow: 0 18px 44px rgb(19 31 61 / 15%);
  transform: translateX(-50%);
}
.marketing-menu-panel a {
  padding: 9px 11px;
  color: #33415d;
  border-radius: 7px;
  font-size: 12px;
  font-weight: 650;
  text-decoration: none;
}
.marketing-menu-panel a:hover,
.marketing-menu-panel a:focus-visible {
  background: #f0f2ff;
  color: #424fea;
}
.marketing-nav-actions {
  gap: 12px;
}
.marketing-nav-actions > a:first-child {
  font-size: 13px;
}
.marketing-button-outline {
  min-height: 38px;
  color: #2f3c57;
  background: #fff;
  border-color: #dce2ed;
  box-shadow: none;
}
.marketing-button-outline:hover {
  color: #2736c7;
  background: #f8f9ff;
  border-color: #bfc6ff;
}
.marketing-nav .marketing-button-small {
  gap: 8px;
}
.marketing-mobile-menu {
  position: relative;
  display: none;
}
.marketing-mobile-menu > summary {
  display: grid;
  place-items: center;
  width: 38px;
  height: 38px;
  color: #25324b;
  background: #fff;
  border: 1px solid #dce2ed;
  border-radius: 9px;
  font-size: 17px;
  line-height: 1;
  list-style: none;
  cursor: pointer;
}
.marketing-mobile-menu > summary::-webkit-details-marker {
  display: none;
}
.marketing-mobile-menu-panel {
  position: absolute;
  top: calc(100% + 10px);
  right: 0;
  z-index: 30;
  display: grid;
  min-width: 190px;
  gap: 4px;
  padding: 9px;
  background: #fff;
  border: 1px solid #e3e7ef;
  border-radius: 12px;
  box-shadow: 0 18px 44px rgb(19 31 61 / 15%);
}
.marketing-mobile-menu-panel a {
  padding: 10px 11px;
  color: #33415d;
  border-radius: 7px;
  font-size: 13px;
  font-weight: 650;
  text-decoration: none;
}
.marketing-mobile-menu-panel a:hover,
.marketing-mobile-menu-panel a:focus-visible {
  color: #424fea;
  background: #f0f2ff;
}

