/* Pricing lower-page parity: the live reference inserts a two-row proof grid,
   then a full-width FAQ band and showcase footer. Keep the desktop geometry
   explicit so the content aligns with the captured reference at 1280px. */
.pricing-comparison {
  padding-bottom: 328px;
}
.pricing-testimonials {
  width: 100%;
  box-sizing: border-box;
  padding: 104px 32px 177px;
  background: #fff;
}
.pricing-testimonials > h2 {
  width: min(672px, 100%);
  margin: 0 auto 72px;
  color: #101a31;
  font-size: 48px;
  line-height: 48px;
  letter-spacing: -0.055em;
  text-align: center;
}
.pricing-testimonials-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  grid-template-rows: 300px 277px;
  gap: 32px;
  width: min(1216px, 100%);
  margin: 0 auto;
}
.pricing-testimonial-card {
  display: flex;
  flex-direction: column;
  min-width: 0;
  box-sizing: border-box;
  padding: 24px 32px;
  color: inherit;
  background: #fff;
  border: 1px solid #dfe4ed;
  border-radius: 16px;
  text-decoration: none;
  transition:
    border-color 180ms ease,
    background 180ms ease,
    box-shadow 180ms ease,
    transform 180ms ease;
}
.pricing-testimonial-card:hover,
.pricing-testimonial-card:focus-visible {
  background: linear-gradient(135deg, #fff, #eef0ff);
  border-color: #bfc6ff;
  box-shadow: 0 12px 28px rgb(31 38 92 / 10%);
  transform: translateY(-2px);
}
.pricing-testimonial-logo {
  display: block;
  width: 100px;
  height: 50px;
  margin: 0 0 16px;
  object-fit: contain;
  object-position: left center;
}
.pricing-testimonial-card > p {
  margin: 0;
  color: #5f6878;
  font-size: 18px;
  font-weight: 500;
  line-height: 1.5;
}
.pricing-testimonial-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  margin-top: auto;
  padding-top: 24px;
}
.pricing-testimonial-person {
  display: flex;
  align-items: center;
  min-width: 0;
  gap: 12px;
}
.pricing-testimonial-person > img {
  flex: 0 0 40px;
  width: 40px;
  height: 40px;
  border: 1px solid #dfe4ed;
  border-radius: 50%;
  object-fit: cover;
}
.pricing-testimonial-person > span {
  display: grid;
  min-width: 0;
  gap: 2px;
}
.pricing-testimonial-person strong {
  overflow: hidden;
  color: #1a253d;
  font-size: 14px;
  font-weight: 800;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.pricing-testimonial-person small {
  overflow: hidden;
  color: #657188;
  font-size: 12px;
  font-weight: 500;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.pricing-testimonial-arrow {
  display: grid;
  flex: 0 0 40px;
  place-items: center;
  width: 40px;
  height: 40px;
  color: #5048df;
  border: 1px solid #dfe4ed;
  border-radius: 16px;
  font-size: 26px;
  line-height: 1;
}
.pricing-faq {
  display: grid;
  grid-template-columns: 408px minmax(0, 1fr);
  gap: 96px;
  width: 100%;
  max-width: none;
  box-sizing: border-box;
  margin: 0;
  padding: 96px 32px;
  background: linear-gradient(180deg, #fff 0%, rgb(238 242 255 / 30%) 52%, #fff 100%);
}
.pricing-faq-intro,
.pricing-faq-list {
  width: min(100%, 1216px);
}
.pricing-faq-intro {
  width: 408px;
}
.pricing-faq-intro h2 {
  margin: 0;
  color: #111a31;
  font-size: 48px;
  line-height: 58px;
  letter-spacing: -0.055em;
}
.pricing-faq-intro > p:not(.pricing-eyebrow) {
  max-width: 408px;
  margin: 16px 0 0;
  color: #66728a;
  font-size: 18px;
  line-height: 28px;
}
.pricing-faq-intro > img {
  display: block;
  width: 320px;
  height: 275px;
  margin-top: 19px;
  object-fit: contain;
  object-position: left bottom;
}
.pricing-faq-list {
  display: grid;
  gap: 12px;
  min-width: 0;
}
.pricing-faq-item {
  box-sizing: border-box;
  padding: 20px 32px;
  background: rgb(238 242 255 / 80%);
  border-radius: 16px;
}
.pricing-faq-item.is-open {
  padding: 32px;
  background: rgb(238 242 255 / 80%);
}
.pricing-faq-item button {
  min-height: 40px;
  padding: 0;
  color: #111827;
  font-size: 18px;
  font-weight: 650;
  line-height: 27px;
}
.pricing-faq-item button > span:first-child {
  max-width: 384px;
}
.pricing-faq-icon {
  flex: 0 0 40px;
  width: 40px;
  height: 40px;
  background: #e0e7ff;
  border-radius: 12px;
}
.pricing-faq-answer {
  padding: 16px 0 0;
  color: #374151;
  font-size: 16px;
  font-weight: 500;
  line-height: 26px;
}
.pricing-faq-item.is-open .pricing-faq-answer {
  min-height: 140px;
  box-sizing: border-box;
}
.pricing-faq-answer p {
  max-width: none;
  margin: 0;
}
.pricing-page .marketing-footer-showcase {
  width: 100%;
  max-width: none;
  padding: 32px 0 0;
}

@media (max-width: 900px) {
  .pricing-testimonials {
    padding: 72px 24px 96px;
  }
  .pricing-testimonials > h2 {
    font-size: 42px;
    line-height: 44px;
  }
  .pricing-testimonials-grid {
    grid-template-rows: none;
  }
  .pricing-faq {
    grid-template-columns: 1fr;
    gap: 48px;
    padding: 72px 24px 96px;
  }
  .pricing-faq-intro {
    width: 100%;
  }
  .pricing-faq-intro > img {
    margin-top: 24px;
  }
  .pricing-faq-list {
    width: 100%;
  }
}

@media (max-width: 620px) {
  .pricing-testimonials {
    padding: 56px 20px 72px;
  }
  .pricing-testimonials > h2 {
    font-size: 36px;
    line-height: 39px;
  }
  .pricing-testimonials-grid {
    grid-template-columns: 1fr;
  }
  .pricing-testimonial-card {
    min-height: 277px;
    padding: 22px 24px;
  }
  .pricing-testimonial-card > p {
    font-size: 16px;
  }
  .pricing-faq {
    padding: 56px 20px 72px;
  }
  .pricing-faq-intro h2 {
    font-size: 42px;
    line-height: 48px;
  }
  .pricing-faq-item,
  .pricing-faq-item.is-open {
    padding: 20px;
  }
  .pricing-faq-item button {
    gap: 14px;
    font-size: 16px;
    line-height: 24px;
  }
  .pricing-faq-item button > span:first-child {
    max-width: none;
  }
}
@media (max-width: 1040px) {
  .pricing-plans {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .pricing-card {
    min-height: 430px;
  }
}
@media (max-width: 1050px) {
  .marketing-announcement-strip > a {
    flex-basis: 50%;
    grid-template-columns: auto minmax(0, 1fr);
  }
  .marketing-announcement-strip > a:nth-child(3) {
    display: none;
  }
  .marketing-announcement-arrow {
    display: none;
  }
  .marketing-nav nav {
    display: none;
  }
  .marketing-nav-actions .marketing-button-outline {
    display: inline-flex;
  }
  .marketing-nav-actions .marketing-button-small {
    display: inline-flex;
  }
  .marketing-nav-actions > a:first-child {
    display: none;
  }
  .marketing-mobile-menu {
    display: block;
  }
  .marketing-nav {
    transform: translateY(16px);
  }
  .marketing-home .marketing-hero-centered {
    width: calc(100% - 48px);
    gap: 29px;
    padding-top: 32px;
  }
  .marketing-home .marketing-home-hero-frame {
    min-height: 638px;
    padding: 12px 16px 70px;
    background: #eef0f4;
  }
  .marketing-home .marketing-home-hero-frame .marketing-browser-bar,
  .marketing-home .marketing-home-hero-frame .marketing-demo-progress {
    display: none;
  }
  .marketing-home .marketing-home-hero-media,
  .marketing-home .marketing-home-hero-frame .marketing-demo-body {
    min-height: 554px;
    height: 554px;
  }
  .marketing-home .marketing-home-hero-media {
    border-radius: 17px;
  }
  .pricing-eyebrow {
    display: none;
  }
  .pricing-hero {
    padding-top: 132px;
  }
  .pricing-hero h1 {
    max-width: none;
    font-size: clamp(40px, 5vw, 48px);
    white-space: nowrap;
  }
  .pricing-plans {
    display: flex;
    gap: 14px;
    width: max-content;
    max-width: none;
    margin-left: 40px;
    overflow: visible;
  }
  .pricing-plans::before,
  .pricing-plans::after {
    flex: 0 0 0;
    content: "";
  }
  .pricing-card-shell {
    flex: 0 0 438px;
  }
  .pricing-card-shell:nth-child(-n + 2) {
    display: none;
  }
  .pricing-billing-row > strong {
    width: 100%;
    margin: 10px 0 0;
  }
  .pricing-plans {
    margin-top: 5px;
    margin-inline: 40px 0;
  }
  .pricing-page {
    overflow-x: hidden;
  }
  .pricing-trust,
  .pricing-comparison,
  .pricing-cta,
  .pricing-plans {
    width: min(100% - 40px, 1180px);
  }
  .pricing-trust {
    margin-top: 75px;
  }
  .pricing-comparison,
  .pricing-cta {
    margin-top: 78px;
  }
  .pricing-plans {
    width: max-content;
    max-width: none;
    gap: 16px;
    margin: 5px 0 0 40px;
  }
  .pricing-plans::before,
  .pricing-plans::after {
    display: none;
  }
  .pricing-card {
    padding-top: 18px;
  }
  .pricing-creator-control,
  .pricing-enterprise-control {
    margin-bottom: 10px;
  }
}

@media (max-width: 760px) {
  .marketing-nav-actions .marketing-button-small {
    display: none;
  }
  .marketing-home .marketing-hero-centered {
    width: auto;
    gap: 42px;
    padding-top: 62px;
  }
  .marketing-home .marketing-home-hero-frame {
    min-height: 440px;
    padding: 8px;
  }
  .marketing-home .marketing-home-hero-media,
  .marketing-home .marketing-home-hero-frame .marketing-demo-body {
    min-height: 300px;
    height: 300px;
  }
}

.pricing-page .marketing-announcement-strip strong,
.features-page .marketing-announcement-strip strong,
.use-cases-page .marketing-announcement-strip strong {
  display: inline-flex;
  align-items: center;
  min-height: 21px;
  padding: 0 8px;
  color: #fff;
  background: #344054;
  border-radius: 999px;
  font-size: 10px;
  letter-spacing: -0.01em;
  white-space: nowrap;
}
@media (max-width: 1050px) {
  .use-cases-hero-copy > p:not(.use-cases-eyebrow) {
    max-width: 350px;
    font-size: 20px;
    line-height: 1.4;
  }
  .use-cases-hero-actions .marketing-button {
    gap: 7px;
  }
}
@media (max-width: 640px) {
  .marketing-announcement-strip {
    display: block;
  }
  .marketing-announcement-strip > a {
    min-height: 35px;
    padding-inline: 20px;
  }
  .marketing-announcement-strip > a + a {
    display: none;
  }
  .pricing-hero {
    padding-top: 72px;
  }
  .pricing-hero h1 {
    font-size: 50px;
  }
  .pricing-billing-row {
    gap: 9px;
  }
  .pricing-billing-row > strong {
