  }
  .pricing-section-heading,
  .pricing-cta {
    align-items: flex-start;
    flex-direction: column;
  }
  .pricing-section-heading .marketing-text-action {
    margin-top: 8px;
  }
  .pricing-cta {
    padding: 38px 28px;
  }
}
@media (prefers-reduced-motion: reduce) {
  .pricing-card-shell {
    animation: none;
  }
  .pricing-toggle,
  .pricing-toggle span {
    transition: none;
  }
}

@media (max-width: 1100px) {
  .pricing-trust-heading {
    grid-template-columns: 1fr;
    gap: 42px;
  }
  .pricing-awards {
    justify-content: flex-start;
  }
  .pricing-trust-logo-panel {
    grid-template-columns: repeat(5, minmax(0, 1fr));
  }
  .pricing-faq {
    grid-template-columns: 1fr;
    gap: 44px;
    padding-top: 88px;
  }
  .pricing-faq-intro > p:not(.pricing-eyebrow) {
    max-width: 520px;
  }
}

@media (max-width: 760px) {
  .pricing-addon {
    grid-template-columns: 1fr;
    gap: 25px;
    padding: 34px 22px 25px;
  }
  .pricing-addon-benefits {
    grid-auto-flow: row;
    grid-template-columns: 1fr;
    gap: 14px;
  }
  .pricing-compare-jump {
    margin-bottom: 58px;
  }
  .pricing-trust {
