  font-size: 13px;
  text-align: left;
  cursor: pointer;
}
.features-trust-menu button:hover,
.features-trust-menu button:focus-visible,
.features-trust-menu button[aria-selected="true"] {
  color: #fff;
  background: rgb(101 117 154 / 55%);
}
.features-trust-logo-grid {
  display: grid;
  grid-template-columns: repeat(10, minmax(0, 1fr));
  grid-template-rows: repeat(2, minmax(0, 1fr));
