  filter: brightness(0) invert(1);
  opacity: 0.5;
}
@keyframes features-trust-grid-swap {
  from {
    opacity: 0.35;
    transform: translateY(7px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
