.use-cases-featured-card p {
  max-width: 535px;
  margin: 0;
  color: #67738b;
  font-size: 13px;
  line-height: 1.45;
}
.use-cases-inline-link {
  display: inline-flex;
  gap: 6px;
  align-items: center;
  margin-top: 20px;
  padding: 7px 10px;
  color: #3e48d8;
  background: #f4f5ff;
  border-radius: 6px;
  font-size: 10px;
  font-weight: 800;
  text-decoration: none;
}
.use-cases-card-art {
  position: relative;
