  border-radius: 99px;
}
.use-cases-card-art span:first-child {
  width: 32%;
  background: #5553e5;
}
.use-cases-card-art span:nth-child(2) {
  width: 60%;
}
.use-cases-card-art span:nth-child(3) {
  width: 45%;
}
.use-cases-card-art strong {
  position: absolute;
  right: 15px;
  bottom: 14px;
  z-index: 1;
  color: #343f98;
  font-size: 12px;
  letter-spacing: -0.03em;
}
.use-cases-card-art-guidance {
  background: linear-gradient(140deg, #dfe5ff, #f4e6ff);
}
.use-cases-card-art-guidance::after {
  position: absolute;
  right: 18%;
  bottom: 14%;
  width: 37%;
  height: 42%;
  background: linear-gradient(135deg, #fff, #c5c8ff);
