  border-radius: 6px;
  box-shadow: -8px 7px 0 rgb(85 77 205 / 20%);
  content: "";
}
.use-cases-card-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 13px;
  padding: 78px max(32px, calc((100% - 1180px) / 2)) 86px;
  background: #101c78;
}
.use-cases-grid-card {
  position: relative;
  display: flex;
  min-height: 155px;
  align-items: flex-start;
  justify-content: space-between;
  gap: 20px;
  padding: 23px;
  overflow: hidden;
  background: linear-gradient(135deg, #fff, #eef0ff);
  border: 1px solid rgb(227 231 255 / 88%);
  border-radius: 9px;
  box-shadow: 0 8px 18px rgb(8 16 82 / 15%);
}
.use-cases-grid-card h3 {
  margin: 0;
  color: #202c4a;
  font-size: 13px;
  letter-spacing: -0.025em;
}
.use-cases-grid-card p {
  max-width: 280px;
  margin: 11px 0 0;
  color: #66728b;
  font-size: 10px;
  line-height: 1.45;
}
.use-cases-grid-card .use-cases-card-art {
  flex: 0 0 116px;
  min-height: 97px;
  margin: -5px -5px -5px 0;
  padding: 8px;
}
.use-cases-features {
  padding: 102px max(32px, calc((100% - 1180px) / 2)) 95px;
  background: #fff;
}
.use-cases-features .use-cases-section-heading {
  margin-inline: 0;
  text-align: left;
}
.use-cases-feature-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 13px;
  margin-top: 42px;
}
.use-cases-feature-card {
  min-height: 178px;
  padding: 22px;
  border: 1px solid #e2e6ef;
  border-radius: 10px;
  box-shadow: 0 8px 20px rgb(24 39 82 / 5%);
}
.use-cases-feature-icon {
  display: grid;
  place-items: center;
  width: 31px;
  height: 31px;
  color: #5355e5;
  background: #f0f1ff;
  border-radius: 8px;
  font-size: 15px;
}
.use-cases-feature-card h3 {
  margin: 19px 0 8px;
  color: #1c2946;
  font-size: 14px;
  letter-spacing: -0.025em;
}
.use-cases-feature-card p {
  margin: 0;
  color: #738097;
  font-size: 11px;
  line-height: 1.45;
}
.use-cases-carousel-controls {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 18px;
  margin-top: 28px;
  color: #7a859b;
  font-size: 11px;
}
.use-cases-carousel-controls button {
  min-height: 35px;
  padding: 0 13px;
  color: #4b54df;
  background: #fff;
  border: 1px solid #dde2ed;
  border-radius: 7px;
  font: inherit;
  font-size: 11px;
  font-weight: 800;
  cursor: pointer;
}
.use-cases-carousel-controls button:disabled {
  color: #aeb6c7;
  background: #f7f8fb;
  cursor: not-allowed;
}
.use-cases-trust {
  padding: 79px max(32px, calc((100% - 1180px) / 2)) 87px;
  color: #fff;
  background: #142238;
}
.use-cases-trust-heading {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 25px;
  align-items: end;
}
.use-cases-trust-heading .use-cases-eyebrow {
  grid-column: 1 / -1;
  margin-bottom: -12px;
  color: #aeb9d3;
}
.use-cases-trust h2 {
  max-width: 620px;
  margin: 0;
  font-size: clamp(29px, 4vw, 49px);
  line-height: 1.02;
  letter-spacing: -0.07em;
}
.use-cases-trust-badges {
  display: flex;
  gap: 8px;
}
.use-cases-trust-badges span {
  display: grid;
  place-items: center;
  width: 64px;
  height: 73px;
  padding: 8px;
  color: #16213c;
  background: linear-gradient(145deg, #fff, #f0d95a);
  clip-path: polygon(0 0, 100% 0, 100% 82%, 50% 100%, 0 82%);
  font-size: 9px;
  font-weight: 900;
  text-align: center;
}
.use-cases-trust-badges span:nth-child(2) {
  background: linear-gradient(145deg, #fff, #ee7d58);
}
.use-cases-trust-badges span:nth-child(3) {
  background: linear-gradient(145deg, #fff, #a796ec);
}
.use-cases-testimonial-picker {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-top: 43px;
  color: #aeb9d3;
  font-size: 12px;
}
.use-cases-testimonial-picker button {
  min-height: 33px;
  padding: 0 13px;
  color: #fff;
  background: #4c54e6;
  border: 1px solid #6c72f0;
  border-radius: 7px;
  font: inherit;
  font-size: 11px;
  font-weight: 800;
  cursor: pointer;
}
.use-cases-testimonial-picker button[aria-pressed="false"] {
  color: #c5cde0;
  background: transparent;
  border-color: #53627d;
}
.use-cases-testimonials {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 13px;
  margin-top: 18px;
}
.use-cases-testimonial-card {
  min-height: 180px;
  padding: 22px;
  color: #15223d;
  background: #fff;
  border-radius: 9px;
}
.use-cases-testimonial-card strong {
  color: #1c2b4d;
  font-size: 16px;
  letter-spacing: -0.04em;
}
.use-cases-testimonial-card p {
  min-height: 57px;
  margin: 18px 0 19px;
  color: #56637a;
  font-size: 12px;
  line-height: 1.45;
}
.use-cases-testimonial-card span {
  display: block;
  color: #1a2945;
  font-size: 11px;
  font-weight: 800;
}
.use-cases-testimonial-card small {
  display: block;
  margin-top: 3px;
  color: #8290a7;
  font-size: 10px;
}
.use-cases-cta {
  padding: 106px 24px 113px;
  color: #fff;
  background: radial-gradient(circle at 50% 45%, rgb(119 113 251 / 40%), transparent 35%), #162452;
  text-align: center;
}
.use-cases-cta .use-cases-eyebrow {
  color: #b7b9ff;
}
.use-cases-cta h2 {
  max-width: 690px;
  margin: 0 auto;
  font-size: clamp(38px, 5vw, 63px);
  line-height: 0.98;
  letter-spacing: -0.075em;
}
.use-cases-cta .marketing-button {
  margin-top: 29px;
}

/* Use-cases reference geometry: the live directory gives the team selector,
   popular cards, feature carousel, and trust band their full editorial height;
   the showcase footer owns the closing CTA. */
.use-cases-hero {
  min-height: 676px;
  box-sizing: border-box;
}
.use-cases-featured {
  min-height: 859px;
  box-sizing: border-box;
}
.use-cases-card-grid {
  min-height: 832px;
  box-sizing: border-box;
}
.use-cases-features {
  min-height: 949px;
  box-sizing: border-box;
}
.use-cases-trust {
  min-height: 600px;
  box-sizing: border-box;
}
@media (max-width: 900px) {
  .use-cases-page .marketing-nav,
  .use-cases-page .marketing-footer {
    width: min(100% - 40px, 1180px);
  }
  .use-cases-hero {
    grid-template-columns: 1fr;
    padding-inline: 20px;
  }
  .use-cases-hero-copy {
    max-width: 680px;
  }
  .use-cases-hero-art {
    max-width: 690px;
    width: 100%;
  }
  .use-cases-featured,
  .use-cases-card-grid,
  .use-cases-features,
  .use-cases-trust {
    padding-inline: 20px;
  }
  .use-cases-featured-card {
    grid-template-columns: 1fr;
  }
  .use-cases-trust-heading {
    grid-template-columns: 1fr;
  }
  .use-cases-testimonials {
    grid-template-columns: 1fr;
  }
}
@media (max-width: 1050px) {
  .use-cases-hero {
    align-items: start;
    min-height: 537px;
    padding-top: 0;
    padding-bottom: 55px;
    padding-inline: 24px;
    grid-template-columns: minmax(0, 0.94fr) minmax(440px, 1.06fr);
  }
  .use-cases-hero-copy {
    max-width: 430px;
    padding-top: 125px;
  }
  .use-cases-hero-copy > .use-cases-eyebrow {
    display: none;
  }
  .use-cases-hero h1 {
    max-width: 450px;
    font-size: clamp(34px, 3.8vw, 40px);
    letter-spacing: -0.07em;
  }
  .use-cases-hero-art {
    min-height: 420px;
    margin-top: 57px;
  }
  .use-cases-hero-actions .marketing-button {
    min-height: 41px;
    padding-inline: 14px;
    font-size: 13px;
  }
}
@media (max-width: 900px) {
  .use-cases-hero {
    grid-template-columns: 1fr;
  }
}
@media (max-width: 620px) {
  .use-cases-hero {
    min-height: auto;
    padding-top: 72px;
  }
  .use-cases-hero-copy {
    padding-top: 0;
  }
  .use-cases-hero h1 {
    font-size: 51px;
  }
  .use-cases-hero-actions {
    align-items: flex-start;
    flex-direction: column;
  }
  .use-cases-hero-art {
    min-height: 270px;
    margin-top: 0;
  }
  .use-cases-hero-screen {
    grid-template-columns: 63px 1fr;
    min-height: 220px;
    padding: 9px;
  }
  .use-cases-hero-screen > div {
    padding: 16px;
  }
  .use-cases-tabs {
    justify-content: flex-start;
  }
  .use-cases-featured {
    padding-top: 69px;
  }
  .use-cases-featured-card {
    padding: 23px;
  }
  .use-cases-card-grid {
    grid-template-columns: 1fr;
    padding-block: 59px;
  }
  .use-cases-feature-grid {
    grid-template-columns: 1fr;
  }
  .use-cases-trust {
    padding-block: 67px;
  }
  .use-cases-trust-badges {
    margin-top: 6px;
  }
}
@media (min-width: 761px) and (max-width: 1050px) {
  .use-cases-hero-copy > p:not(.use-cases-eyebrow) {
    max-width: 350px;
    font-size: 20px;
    line-height: 1.4;
  }
  .use-cases-hero-actions .marketing-button {
    gap: 7px;
  }
}
@media (prefers-reduced-motion: reduce) {
  .use-cases-hero-art,
  .use-cases-tabs button {
    transform: none;
    transition: none;
  }
}

/* Free-tools directory reference surface. */
.tools-page {
  --marketing-blue: #4d54e8;
  --marketing-blue-dark: #2736c7;
  min-height: 100vh;
  overflow: hidden;
  color: #111a30;
  background: #fff;
}
.tools-page .marketing-nav,
.tools-page .marketing-footer {
  width: min(1216px, calc(100% - 64px));
}
.tools-hero {
  display: grid;
  grid-template-columns: minmax(0, 484.57px) minmax(0, 667.43px);
  gap: 64px;
  align-items: center;
  width: min(1216px, calc(100% - 64px));
  min-height: 0;
  margin: 0 auto;
  padding: 86px 0 96px;
  background: #fff;
}
.tools-hero-copy {
  width: 100%;
  max-width: none;
}
.tools-eyebrow {
  margin: 0 0 15px;
  color: #4d56e6;
  font-size: 12px;
  font-weight: 850;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}
.tools-hero-copy > .tools-eyebrow {
  display: none;
}
.tools-hero h1 {
  max-width: none;
  margin: 0;
  color: #121c34;
  font-size: 44px;
  line-height: 48px;
  letter-spacing: -0.05em;
}
.tools-hero-copy > p:not(.tools-eyebrow) {
  max-width: none;
  min-height: 84px;
  margin: 24px 0 32px;
  color: #5f6c83;
  font-size: 20px;
  line-height: 28px;
}
.tools-hero-copy .marketing-button {
  display: inline-flex;
  margin-top: 0;
  min-height: 40px;
  padding-inline: 20px;
  font-size: 16px;
}
.tools-hero-art {
  position: relative;
  width: 100%;
  height: 420px;
  min-height: 420px;
  padding: 0;
  overflow: hidden;
  background: transparent;
  border: 0;
  border-radius: 0;
  box-shadow: none;
