   desktop split, a compact 527px form column, and a clipped horizontal proof
   rail. These overrides intentionally sit after the first-pass styles above
   so the reference geometry remains stable as the page evolves. */
.product-demo-page {
  min-height: 100vh;
  height: 100vh;
  overflow: hidden;
}
.product-demo-form-panel {
  min-height: 100vh;
  padding: 40px 56px;
}
.product-demo-form-inner {
  width: 100%;
  max-width: 527px;
}
.product-demo-title-decoration {
  display: none;
}
.product-demo-form-inner h1 {
  display: flex;
  align-items: center;
  gap: 12px;
  width: 100%;
  margin: 0 0 12px;
  color: #101827;
  font-family: var(--font-display, Inter), system-ui, sans-serif;
  font-size: 36px;
  font-weight: 700;
  line-height: 40px;
  letter-spacing: -0.055em;
  white-space: nowrap;
}
.product-demo-avatar-stack {
  position: relative;
  display: inline-flex;
  flex: 0 0 112px;
  width: 112px;
  height: 40px;
}
.product-demo-avatar {
  position: absolute;
  top: 0;
  display: block;
  width: 40px;
  height: 40px;
  overflow: hidden;
  border: 1px solid #fff;
  border-radius: 999px;
  box-shadow: 0 6px 16px rgb(24 35 64 / 16%);
  transition: transform 180ms ease;
}
.product-demo-avatar:hover {
  transform: rotate(5deg) scale(1.08);
}
.product-demo-avatar:nth-child(even):hover {
  transform: rotate(-5deg) scale(1.08);
}
.product-demo-avatar-1 {
  left: 0;
  z-index: 4;
}
.product-demo-avatar-2 {
  left: 28px;
  z-index: 3;
}
.product-demo-avatar-3 {
  left: 56px;
  z-index: 2;
}
.product-demo-avatar-4 {
  left: 84px;
  z-index: 1;
}
.product-demo-avatar img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.product-demo-form-inner > p {
  max-width: none;
  margin: 0 0 24px;
  color: #667085;
  font-size: 16px;
  line-height: 26px;
}
.product-demo-form-inner form {
  display: block;
}
.product-demo-fields-row {
  margin-bottom: 20px;
}
.product-demo-form-inner label {
  display: block;
  color: #344054;
  font-size: 14px;
  font-weight: 500;
  line-height: 20px;
}
.product-demo-form-inner input,
.product-demo-form-inner select {
  min-height: 40px;
  padding: 0 12px;
  color: #101828;
  border-color: #d0d5dd;
  border-radius: 8px;
  font-size: 14px;
  line-height: 20px;
}
.product-demo-form-inner input,
.product-demo-form-inner select {
  display: block;
  margin-top: 4px;
}
.product-demo-form-inner form > label {
  margin-bottom: 32px;
}
.product-demo-actions {
  gap: 12px;
}
.product-demo-actions .marketing-button,
.product-demo-skip {
  min-height: 40px;
  border-radius: 12px;
  font-size: 14px;
  line-height: 20px;
}
.product-demo-actions .marketing-button {
  padding-inline: 12px;
  box-shadow:
    0 1px 2px rgb(10 13 18 / 5%),
    inset 0 -2px 0 rgb(10 13 18 / 5%),
    inset 0 0 0 1px rgb(10 13 18 / 18%);
}
.product-demo-skip {
  padding-inline: 12px;
  color: #414651;
  font-weight: 450;
  box-shadow:
    0 1px 2px rgb(10 13 18 / 5%),
    inset 0 -2px 0 rgb(10 13 18 / 5%),
    inset 0 0 0 1px rgb(10 13 18 / 18%);
}
.product-demo-skip:first-letter {
  color: #444ce7;
}
.product-demo-proof {
  display: flex;
  align-items: center;
  flex-direction: column;
  justify-content: flex-start;
  min-height: 100vh;
  padding: 103px 0 0;
  background: #1d2735;
}
.product-demo-proof h2 {
  width: 100%;
  margin: 0 0 32px;
  font-family: var(--font-display, Inter), system-ui, sans-serif;
  font-size: 24px;
  font-weight: 500;
  line-height: 32px;
  letter-spacing: -0.045em;
  text-align: center;
}
.product-demo-proof-viewport {
  align-self: stretch;
  flex-shrink: 0;
  width: 100%;
  min-width: 100%;
  height: 311px;
  overflow: hidden;
  padding: 8px 0;
}
.product-demo-proof-track {
  display: flex;
  gap: 20px;
  width: max-content;
  padding: 0 10px;
  transform: translateX(-835px);
  animation: product-demo-card-marquee 42s linear infinite;
  will-change: transform;
}
.product-demo-proof-card {
  position: relative;
  display: flex;
  flex: 0 0 300px;
  width: 300px;
  min-height: 295px;
  flex-direction: column;
  padding: 20px;
  border: 1px solid #f0f1f3;
  border-radius: 12px;
  box-shadow: 0 15px 30px rgb(0 0 0 / 10%);
}
.product-demo-company {
  display: flex;
  align-items: center;
  height: 20px;
  margin-bottom: 12px;
}
.product-demo-company img {
  display: block;
  width: auto;
  max-width: 80px;
  height: 20px;
  object-fit: contain;
  object-position: left center;
}
.product-demo-proof-card > p {
  min-height: 0;
  margin: 0 0 12px;
  color: #344054;
  font-size: 13px;
  line-height: 19px;
}
.product-demo-person {
  gap: 2px;
  padding-bottom: 16px;
  border-bottom-color: #f0f1f3;
}
.product-demo-person strong {
  color: #101828;
  font-size: 13px;
  line-height: 17px;
}
.product-demo-person span {
  color: #667085;
  font-size: 11px;
  line-height: 14px;
}
.product-demo-metric {
  gap: 2px;
  margin-top: 12px;
}
.product-demo-metric strong {
  color: #101828;
  font-size: 24px;
  line-height: 28px;
}
.product-demo-metric span {
  color: #667085;
  font-size: 12px;
  line-height: 16px;
}
.product-demo-card-arrow {
  right: 20px;
  bottom: 20px;
  width: 28px;
  height: 28px;
  color: #98a2b3;
  font-size: 14px;
}
.product-demo-trusted {
  margin: 23px 0 16px;
  color: rgb(255 255 255 / 50%);
  font-size: 12px;
  font-weight: 600;
  line-height: 16px;
}
.product-demo-trust-logos {
  display: grid;
  grid-template-columns: repeat(4, 80px);
  gap: 4px 32px;
  width: 512px;
  max-width: 100%;
  margin-inline: auto;
}
.product-demo-trust-logos span {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 80px;
  height: 46px;
}
.product-demo-trust-logos img {
  display: block;
  width: 80px;
  max-height: 46px;
  object-fit: contain;
  filter: brightness(0) invert(1);
  opacity: 0.62;
}
@keyframes product-demo-card-marquee {
  from {
    transform: translateX(-835px);
  }
  to {
    transform: translateX(calc(-50% - 835px));
  }
}
@media (max-width: 920px) {
  .product-demo-page {
    height: auto;
    min-height: 100vh;
    overflow: visible;
  }
  .product-demo-form-panel {
    min-height: auto;
    padding: 72px 24px;
  }
  .product-demo-proof {
    min-height: 720px;
    padding: 72px 0 48px;
  }
}
@media (max-width: 560px) {
  .product-demo-form-inner h1 {
    align-items: flex-start;
    flex-direction: column;
    gap: 12px;
    white-space: normal;
  }
  .product-demo-fields-row {
    margin-bottom: 20px;
  }
  .product-demo-form-inner form > label {
    margin-bottom: 28px;
  }
  .product-demo-trust-logos {
    grid-template-columns: repeat(4, 72px);
    gap: 4px 12px;
    justify-content: center;
  }
  .product-demo-trust-logos span,
  .product-demo-trust-logos img {
    width: 72px;
  }
}
@media (prefers-reduced-motion: reduce) {
  .product-demo-proof-track,
  .product-demo-avatar {
    animation: none;
    transition: none;
  }
  .product-demo-proof-track {
    transform: translateX(-835px);
  }
}

/* Enterprise landing page: a quiet, procurement-ready surface with the same
