  color: #182238;
  font-size: clamp(34px, 4vw, 54px);
  letter-spacing: -0.065em;
}
.blog-exact-update-archive-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 16px;
