  background: #fff;
  color: #10182b;
}
.feature-detail-hero,
.customer-detail-hero {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 0.9fr) minmax(0, 1.1fr);
  gap: clamp(36px, 7vw, 108px);
  align-items: center;
  max-width: 1240px;
  margin: 0 auto;
  padding: 106px 32px 112px;
  overflow: hidden;
}
