  50% {
    transform: translateY(-7px);
  }
}
.customer-detail-hero {
  grid-template-columns: 1fr;
  gap: 34px;
  max-width: 1120px;
  padding-top: 72px;
  text-align: center;
}
.customer-detail-hero-copy {
  max-width: 880px;
  margin: 0 auto;
}
.customer-detail-hero-copy .customer-detail-eyebrow {
  display: none;
}
.customer-detail-hero-copy .customer-detail-breadcrumb {
  margin-bottom: 20px;
  color: #6a6ff1;
  font-size: 12px;
  font-weight: 700;
}
.customer-detail-hero h1 {
  max-width: 920px;
  margin-inline: auto;
  font-size: clamp(42px, 4.4vw, 56px);
}
.customer-detail-hero-copy > p:not(.customer-detail-eyebrow):not(.customer-detail-breadcrumb) {
  max-width: 720px;
  margin-inline: auto;
  font-size: 16px;
}
.customer-detail-hero .customer-detail-author {
  display: none;
}
.customer-detail-hero .marketing-hero-actions {
  justify-content: center;
}
.customer-detail-preview {
  width: min(760px, 100%);
  min-height: 430px;
  margin: 0 auto;
  transform: translateY(0);
}
.customer-detail-preview-media {
  min-height: 430px;
  padding: 0;
  background: transparent;
}
.customer-detail-preview-image {
  min-height: 430px;
  border-radius: 0;
  object-fit: contain;
  box-shadow: none;
}
@media (max-width: 900px) {
  .feature-detail-hero,
  .customer-detail-hero {
    grid-template-columns: 1fr;
