  .feature-detail-preview,
  .customer-detail-preview {
    min-height: 380px;
    transform: none;
  }
  .feature-detail-preview-media,
  .customer-detail-preview-media,
  .feature-detail-preview-image,
  .customer-detail-preview-image {
    min-height: 330px;
  }
  .feature-detail-preview-body,
  .customer-detail-preview-body {
    min-height: 330px;
  }
  .feature-detail-capabilities,
  .customer-detail-use-grid,
  .feature-detail-step-grid {
    grid-template-columns: 1fr;
  }
  .feature-detail-cta,
  .customer-detail-cta {
    align-items: flex-start;
    flex-direction: column;
  }
}
@media (max-width: 560px) {
  .feature-detail-hero,
  .customer-detail-hero,
  .feature-detail-outcome,
  .customer-detail-quote {
    padding-left: 20px;
    padding-right: 20px;
  }
  .feature-detail-hero h1,
  .customer-detail-hero h1 {
    font-size: 48px;
