  .feature-detail-preview-body,
  .customer-detail-preview-body {
    grid-template-columns: 48px minmax(0, 1fr);
    padding: 16px;
  }
  .feature-detail-preview-body section,
  .customer-detail-preview-body section {
    padding: 24px 18px;
  }
  .feature-detail-preview-media,
  .customer-detail-preview-media,
  .feature-detail-preview-image,
  .customer-detail-preview-image {
    min-height: 250px;
  }
  .feature-detail-preview-card {
    right: 14px;
    bottom: 14px;
  }
  .feature-detail-steps,
  .feature-detail-cta,
  .customer-detail-cta,
  .customer-detail-result {
