/* Reference-grade research report surface. */
.marketing-report-page {
  --marketing-blue: #4d54e8;
  --marketing-blue-dark: #2736c7;
  --marketing-ink: #111729;
  --marketing-muted: #687287;
  --marketing-line: #dfe4ef;
  background: #fff;
  color: #111729;
}

.marketing-report-page .marketing-button-light {
  border-color: #cfd5e4;
}

.marketing-report-hero {
  position: relative;
  display: grid;
  min-height: 470px;
  place-items: center;
  overflow: hidden;
  isolation: isolate;
  padding: 92px 32px 78px;
  background:
    radial-gradient(circle at 50% 35%, rgb(255 255 255 / 88%) 0 14%, transparent 48%),
    linear-gradient(180deg, #eaf0ff 0%, #f6f8ff 64%, #fff 100%);
}

.marketing-report-hero-copy {
  position: relative;
  z-index: 2;
  width: min(900px, 100%);
  text-align: center;
}

.marketing-report-hero-copy .marketing-announcement {
  display: inline-flex;
  margin: 0 0 24px;
  padding: 10px 16px;
  border: 1px solid #cdd5ea;
  border-radius: 12px;
  background: rgb(255 255 255 / 65%);
  color: #4d53ad;
  font-weight: 650;
}

.marketing-report-hero-copy h1 {
  margin: 0;
  color: #101526;
  font-size: clamp(48px, 6.2vw, 86px);
  letter-spacing: -0.075em;
  line-height: 0.98;
}

.marketing-report-hero-copy > p:not(.marketing-announcement) {
  max-width: 760px;
  margin: 28px auto 0;
  color: #4b5569;
  font-size: clamp(18px, 2vw, 24px);
  line-height: 1.45;
}

.marketing-report-hero-copy > p strong {
  color: #4244b8;
}

.marketing-report-hero-copy .marketing-hero-actions {
  justify-content: center;
  margin-top: 30px;
}

.marketing-report-hero-art {
  position: absolute;
  z-index: 1;
  display: grid;
  width: min(310px, 25vw);
  gap: 12px;
  opacity: 0.53;
  filter: saturate(0.82);
  pointer-events: none;
}

.marketing-report-hero-art img {
  display: block;
  width: 100%;
  border: 1px solid rgb(95 105 173 / 16%);
  border-radius: 18px;
  box-shadow: 0 24px 54px rgb(69 79 153 / 18%);
}

.marketing-report-hero-art-left {
  top: 74px;
  left: max(-42px, calc((100vw - 1400px) / 2));
  transform: rotate(-8deg);
}

.marketing-report-hero-art-left img + img {
  width: 82%;
  margin: -74px 0 0 72px;
  transform: rotate(8deg);
}

.marketing-report-hero-art-right {
  right: max(-42px, calc((100vw - 1400px) / 2));
  bottom: 44px;
  transform: rotate(8deg);
}

.marketing-report-hero-art-right img + img {
  width: 82%;
  margin: -74px 0 0 36px;
  transform: rotate(-8deg);
}

.marketing-report-layout {
  display: grid;
  grid-template-columns: 250px minmax(0, 900px);
  align-items: start;
  gap: 56px;
  width: min(1240px, calc(100% - 48px));
  margin: 0 auto;
  padding: 64px 0 100px;
}

.marketing-report-nav {
  position: sticky;
  top: 82px;
  min-width: 0;
}

.marketing-report-nav-label {
  display: block;
  margin: 0 0 14px 12px;
  color: #737b8c;
  font-size: 12px;
  font-weight: 750;
  letter-spacing: 0.11em;
  text-transform: uppercase;
}

.marketing-report-nav-list {
  display: grid;
  gap: 2px;
  border-left: 2px solid #e0e5f3;
  padding-left: 10px;
}

.marketing-report-nav button {
  width: 100%;
  border: 0;
  border-radius: 8px;
  background: transparent;
  color: #656e80;
  cursor: pointer;
  padding: 9px 10px;
  text-align: left;
  font: inherit;
  font-size: 13px;
  line-height: 1.35;
  transition:
    color 160ms ease,
    background 160ms ease;
}

.marketing-report-nav button:hover,
.marketing-report-nav button:focus-visible,
.marketing-report-nav button.is-active {
  background: #f0f2ff;
  color: #4b4fe1;
}

.marketing-report-content {
  display: grid;
  gap: 28px;
  min-width: 0;
}

.marketing-report-card {
  scroll-margin-top: 88px;
  overflow: hidden;
  border: 1px solid #dfe4ef;
  border-radius: 22px;
  background: #fff;
  box-shadow: 0 18px 48px rgb(36 48 96 / 6%);
}

.marketing-report-card-heading,
.marketing-report-section-heading,
.marketing-report-copy-card,
.marketing-report-data-card,
.marketing-report-takeaways {
  padding: 34px;
}

.marketing-report-card-heading {
  border-bottom: 1px solid #dfe4ef;
  background: linear-gradient(180deg, #f6f7ff, #fff);
}

.marketing-report-card-heading h2,
.marketing-report-section-heading h2,
.marketing-report-copy-card h2,
.marketing-report-data-card h2,
.marketing-report-takeaways h2 {
  margin: 7px 0 0;
  color: #111729;
  font-size: clamp(28px, 3.2vw, 42px);
  letter-spacing: -0.055em;
  line-height: 1.04;
}
.marketing-report-inline-heading {
  margin: 30px 0 0;
  color: #202940;
  font-size: 22px;
  line-height: 1.15;
  letter-spacing: -0.035em;
}

.marketing-report-card-heading > p:last-child,
.marketing-report-section-heading > p:last-child,
.marketing-report-copy-card > p:not(.marketing-announcement),
.marketing-report-data-card > p:not(.marketing-announcement),
.marketing-report-takeaways > p:not(.marketing-announcement) {
  max-width: 720px;
  margin: 14px 0 0;
  color: #687287;
  font-size: 16px;
  line-height: 1.55;
}

.marketing-report-insights {
  position: relative;
  padding: 34px;
}

.marketing-report-section-heading {
  padding: 0;
}

.marketing-report-section-heading h3 {
  margin: 7px 0 0;
  color: #111729;
  font-size: 27px;
  letter-spacing: -0.04em;
}

.marketing-report-tabs {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
  margin-top: 24px;
}

.marketing-report-tabs button,
.marketing-report-view-toggle button {
  min-height: 38px;
  border: 1px solid #d6dcea;
  border-radius: 9px;
  background: #fff;
  color: #6b7486;
  cursor: pointer;
  padding: 7px 13px;
  font: inherit;
  font-size: 13px;
  font-weight: 650;
  transition:
    border-color 160ms ease,
    color 160ms ease,
    background 160ms ease;
}

.marketing-report-tabs button:hover,
.marketing-report-tabs button:focus-visible,
.marketing-report-tabs button[aria-selected="true"],
.marketing-report-view-toggle button:hover,
.marketing-report-view-toggle button:focus-visible,
.marketing-report-view-toggle button.is-active {
  border-color: #595af1;
  background: #f1f1ff;
  color: #4a4de2;
}

.marketing-report-view-toggle {
  display: inline-flex;
  gap: 4px;
  margin-top: 22px;
  padding: 4px;
  border: 1px solid #e0e4ed;
  border-radius: 11px;
  background: #f6f7fb;
}

.marketing-report-view-toggle button {
  min-height: 31px;
  border-color: transparent;
  padding: 4px 12px;
}

.marketing-report-chart {
  display: grid;
  gap: 17px;
  margin-top: 28px;
}

.marketing-report-chart-row {
  display: grid;
  grid-template-columns: 120px minmax(0, 1fr) 48px;
  align-items: center;
  gap: 14px;
  color: #697388;
  font-size: 13px;
}

.marketing-report-chart-row strong {
  color: #242c47;
  font-size: 13px;
  text-align: right;
}

.marketing-report-chart-track {
  height: 14px;
  overflow: hidden;
  border-radius: 999px;
  background: #eef0f7;
}

.marketing-report-chart-track span {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, #6c6ef8, #4e51e0);
}

.marketing-report-table-wrap {
  overflow-x: auto;
  margin-top: 26px;
  border: 1px solid #e0e4ed;
  border-radius: 13px;
}

.marketing-report-table {
  width: 100%;
  border-collapse: collapse;
  min-width: 560px;
  color: #5d677b;
  font-size: 14px;
}

.marketing-report-table th,
.marketing-report-table td {
  border-bottom: 1px solid #e6e9f0;
  padding: 13px 15px;
  text-align: left;
}

.marketing-report-table thead th {
  background: #f7f8fc;
  color: #788297;
  font-size: 11px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.marketing-report-table tbody tr:last-child th,
.marketing-report-table tbody tr:last-child td {
  border-bottom: 0;
}

.marketing-report-table tbody th {
  color: #202940;
}

.marketing-report-stat-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  border-top: 1px solid #dfe4ef;
}

.marketing-report-stat-grid article {
  display: grid;
  gap: 7px;
  min-height: 126px;
  align-content: center;
  padding: 22px 24px;
  border-right: 1px solid #dfe4ef;
}

.marketing-report-stat-grid article:last-child {
  border-right: 0;
}

.marketing-report-stat-grid strong {
  color: #4f52e7;
  font-size: 30px;
  letter-spacing: -0.05em;
}

.marketing-report-stat-grid span {
  color: #697388;
  font-size: 13px;
  line-height: 1.35;
}

.marketing-report-findings {
  padding: 0 34px 34px;
}

.marketing-report-findings .marketing-report-section-heading {
  padding: 34px 0 24px;
}

.marketing-report-finding-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  border-top: 1px solid #e2e6ef;
}

.marketing-report-finding-grid article {
  padding: 22px 22px 18px 0;
  border-bottom: 1px solid #e2e6ef;
}

.marketing-report-finding-grid article:nth-child(odd) {
  padding-right: 30px;
  border-right: 1px solid #e2e6ef;
}

.marketing-report-finding-grid article:nth-child(even) {
  padding-left: 30px;
}

.marketing-report-finding-grid article:nth-last-child(-n + 2) {
  border-bottom: 0;
}

.marketing-report-finding-grid span {
  color: #6063eb;
  font-size: 12px;
  font-weight: 750;
  letter-spacing: 0.1em;
}

.marketing-report-finding-grid h3 {
  margin: 10px 0 0;
  color: #202940;
  font-size: 18px;
  letter-spacing: -0.025em;
  line-height: 1.2;
}

.marketing-report-finding-grid p {
  margin: 9px 0 0;
  color: #697388;
  font-size: 14px;
  line-height: 1.5;
}

.marketing-report-copy-card {
  min-height: 260px;
}

.marketing-report-copy-card .marketing-text-action {
  display: inline-flex;
  margin-top: 22px;
}

.marketing-report-video-card {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 18px;
  margin-top: 26px;
  padding: 20px;
  border: 1px solid #dce2ee;
  border-radius: 14px;
  background: #f7f8ff;
}

.marketing-report-video-card > span {
  display: grid;
  width: 42px;
  height: 42px;
  place-items: center;
  border-radius: 50%;
  background: #4e51e0;
  color: #fff;
  font-size: 13px;
}

.marketing-report-video-card strong {
  color: #202940;
}

.marketing-report-video-card p {
  margin: 5px 0 0;
  color: #697388;
  font-size: 13px;
}

.marketing-report-video-card a {
  color: #4c4fe1;
  font-size: 13px;
  font-weight: 700;
  white-space: nowrap;
}

.marketing-report-department-grid,
.marketing-report-impact-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
  margin-top: 28px;
}

.marketing-report-department-grid div,
.marketing-report-impact-grid article {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  padding: 16px 18px;
  border: 1px solid #e0e4ed;
  border-radius: 12px;
  background: #fbfcff;
}

.marketing-report-department-grid span,
.marketing-report-impact-grid span {
  color: #667186;
  font-size: 14px;
}

.marketing-report-department-grid strong,
.marketing-report-impact-grid strong {
  color: #4f52e7;
  font-size: 21px;
}

.marketing-report-use-case-pills,
.marketing-report-formula {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin-top: 25px;
}

.marketing-report-use-case-pills span,
.marketing-report-formula span {
  display: inline-flex;
  border: 1px solid #d5daf0;
  border-radius: 999px;
  background: #f5f5ff;
  color: #4f52c6;
  padding: 9px 13px;
  font-size: 13px;
  font-weight: 650;
}

.marketing-report-impact-grid {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.marketing-report-impact-grid article {
  display: grid;
  align-content: center;
  justify-content: initial;
  min-height: 105px;
}

.marketing-report-impact-grid strong {
  margin-top: 6px;
  font-size: 31px;
  letter-spacing: -0.05em;
}

.marketing-report-impact-grid small {
  color: #8992a3;
  font-size: 12px;
}

.marketing-report-takeaways {
  display: grid;
  justify-items: start;
  background: linear-gradient(135deg, #171d40, #343a91);
}

.marketing-report-takeaways h2,
.marketing-report-takeaways > p:not(.marketing-announcement) {
  color: #fff;
}

.marketing-report-takeaways .marketing-announcement {
  color: #bcc3ff;
}

.marketing-report-takeaways .marketing-button {
  margin-top: 24px;
}

@media (max-width: 980px) {
  .marketing-report-layout {
    grid-template-columns: 1fr;
    gap: 24px;
  }

  .marketing-report-nav {
    position: static;
  }

  .marketing-report-nav-list {
    display: flex;
    overflow-x: auto;
    border-left: 0;
    border-bottom: 1px solid #e0e5f3;
    padding: 0;
  }

  .marketing-report-nav button {
    width: auto;
    min-width: max-content;
    border-radius: 8px 8px 0 0;
  }

  .marketing-report-nav button.is-active {
    border-bottom: 2px solid #4e51e0;
  }
}

@media (max-width: 720px) {
  .marketing-report-hero {
    min-height: 560px;
    padding: 74px 20px 64px;
  }

  .marketing-report-hero-copy h1 {
    font-size: clamp(42px, 12vw, 64px);
  }

  .marketing-report-hero-art {
    width: 190px;
    opacity: 0.27;
  }

  .marketing-report-hero-art-left {
    top: 38px;
    left: -66px;
  }

  .marketing-report-hero-art-right {
    right: -70px;
    bottom: 20px;
  }

  .marketing-report-layout {
    width: min(100% - 28px, 900px);
    padding-top: 36px;
  }

  .marketing-report-card-heading,
  .marketing-report-insights,
  .marketing-report-copy-card,
  .marketing-report-data-card,
  .marketing-report-takeaways {
    padding: 24px;
  }

  .marketing-report-findings {
    padding: 0 24px 24px;
  }

  .marketing-report-findings .marketing-report-section-heading {
    padding: 24px 0 18px;
  }

  .marketing-report-stat-grid,
  .marketing-report-finding-grid,
  .marketing-report-department-grid,
  .marketing-report-impact-grid {
    grid-template-columns: 1fr;
