/* Guided HTML demo reference surface. This route mirrors Supademo's public
   feature page while keeping the preview artwork local to the page so the
   surrounding copy and interactions remain accessible and testable. */
.guided-html-page {
  --marketing-blue: #444ce7;
  --marketing-blue-dark: #3538cd;
  --guided-ink: #1d2735;
  --guided-purple: #444ce7;
  --guided-muted: #59677e;
  overflow: hidden;
  color: var(--guided-ink);
  background: #fff;
}
.guided-html-hero {
  position: relative;
  min-height: 516px;
  overflow: hidden;
  border-bottom: 1px solid #e4e6ee;
  background: #fff;
}
.guided-html-hero-blob {
  position: absolute;
  width: 390px;
  height: 390px;
  border-radius: 50%;
  filter: blur(58px);
  opacity: 0.24;
  pointer-events: none;
}
.guided-html-hero-blob-left {
  top: -130px;
  left: -110px;
  background: linear-gradient(135deg, #a68aff, #5d5ded);
}
.guided-html-hero-blob-right {
  right: -120px;
  bottom: -160px;
  background: linear-gradient(135deg, #f58bde, #ab8bff);
}
.guided-html-hero-inner {
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-columns: minmax(0, 3fr) minmax(0, 4fr);
  gap: 48px;
  align-items: center;
  width: min(1216px, calc(100% - 64px));
  min-height: 516px;
  margin: 0 auto;
  padding: 74px 0 58px;
}
.guided-html-hero-copy {
  max-width: 510px;
}
.guided-html-hero-copy h1 {
  max-width: 540px;
  margin: 0;
  color: #28305b;
  font-size: clamp(42px, 3.8vw, 50px);
  font-weight: 800;
  letter-spacing: -0.07em;
  line-height: 0.99;
  background: linear-gradient(90deg, #1d2735, #3a2c6f);
  background-clip: text;
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
}
.guided-html-hero-copy > p {
  max-width: 480px;
  margin: 26px 0 30px;
  color: #556177;
  font-size: 19px;
  line-height: 1.48;
}
.guided-html-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
}
.guided-html-actions .marketing-button {
  min-height: 40px;
  padding-inline: 14px;
  border-radius: 10px;
  box-shadow:
    0 1px 2px rgb(10 13 18 / 8%),
    inset 0 -2px 0 rgb(10 13 18 / 7%);
}
.guided-html-actions .marketing-button-outline {
  color: #414651;
  background: #fff;
  border-color: #d5d7da;
  box-shadow: 0 1px 2px rgb(10 13 18 / 8%);
}
.guided-html-hero-canvas {
  position: relative;
  width: 100%;
  max-width: 560px;
  justify-self: end;
  aspect-ratio: 1.74;
  border-radius: 22px;
  animation: guided-html-float 7s ease-in-out infinite;
}
.guided-html-canvas-browser {
  position: absolute;
  inset: 0;
  overflow: hidden;
  border: 1px solid rgb(255 255 255 / 75%);
  border-radius: 22px;
  background: #e6e6ea;
  box-shadow: 0 18px 50px rgb(32 26 86 / 20%);
  transform: translateZ(0);
}
.guided-html-canvas-toolbar {
  display: flex;
  align-items: center;
  gap: 6px;
  height: 38px;
  padding: 0 15px;
  background: #343844;
}
.guided-html-canvas-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: #ef676e;
}
.guided-html-canvas-dot:nth-child(2) {
  background: #edc34d;
}
.guided-html-canvas-dot:nth-child(3) {
  background: #66c776;
}
.guided-html-canvas-url {
  width: 50%;
  height: 13px;
  margin-left: 10px;
  border-radius: 999px;
  background: #4b5060;
}
.guided-html-canvas-pill {
  width: 52px;
  height: 15px;
  margin-left: auto;
  border-radius: 999px;
  background: #141923;
}
.guided-html-canvas-body {
  position: relative;
  display: grid;
  grid-template-columns: 21% 1fr;
  height: calc(100% - 38px);
  background: #d8d9dd;
}
.guided-html-canvas-sidebar {
  display: grid;
  align-content: start;
  gap: 8px;
  padding: 24px 14px;
  color: #6d7380;
  background: #d0d1d4;
  font-size: 8px;
}
.guided-html-canvas-sidebar strong {
  margin-bottom: 14px;
  color: #414653;
  font-size: 11px;
}
.guided-html-canvas-sidebar span {
  padding: 5px 7px;
  border-radius: 4px;
}
.guided-html-canvas-sidebar span.is-active {
  color: #3d4352;
  background: #babdc5;
}
.guided-html-canvas-content {
  padding: 24px 24px 18px;
  background: #dfe0e2;
}
.guided-html-canvas-heading {
  display: flex;
  justify-content: space-between;
  align-items: center;
  color: #616875;
  font-size: 13px;
