.guided-html-canvas-stat-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
  margin-top: 18px;
}
.guided-html-canvas-stat-grid span {
  display: block;
  height: 43px;
  padding: 11px;
  color: #6b7180;
  border-radius: 5px;
  background: #f1f1f3;
  font-size: 10px;
  font-weight: 700;
