/* Sandbox demos reference surface. The sections intentionally keep the same
   quiet editorial rhythm, indigo actions, soft lavender washes, and dark
   trust rail as the live Supademo feature page. */
.sandbox-page {
  --sandbox-ink: #111a2f;
  --sandbox-muted: #536078;
  --sandbox-line: #dfe4ec;
  --sandbox-indigo: #4547e8;
  --sandbox-indigo-dark: #3031b8;
  --sandbox-soft: #f5f7ff;
  --marketing-blue: var(--sandbox-indigo);
  --marketing-blue-dark: var(--sandbox-indigo-dark);
  overflow: hidden;
  color: var(--sandbox-ink);
  background: #fff;
}
.sandbox-page h1,
.sandbox-page h2,
.sandbox-page h3 {
  font-family: "degularFont", Inter, ui-sans-serif, system-ui, sans-serif;
}
.sandbox-page .marketing-public-chrome {
  background: rgb(255 255 255 / 94%);
}
.sandbox-hero {
  position: relative;
  isolation: isolate;
  overflow: hidden;
  background:
    radial-gradient(circle at 7% 32%, rgb(166 145 255 / 27%), transparent 28%),
    radial-gradient(circle at 88% 74%, rgb(238 183 247 / 39%), transparent 34%), #fff;
}
.sandbox-hero::after {
  position: absolute;
  inset: auto 0 0;
  z-index: -1;
  height: 1px;
  background: var(--sandbox-line);
  content: "";
}
.sandbox-hero-inner {
  display: grid;
  grid-template-columns: minmax(0, 0.86fr) minmax(0, 1.14fr);
  align-items: center;
  gap: clamp(34px, 5vw, 84px);
  width: min(1216px, calc(100% - 64px));
  min-height: 550px;
  margin-inline: auto;
  padding: 64px 0 76px;
}
.sandbox-hero-copy {
  max-width: 560px;
}
.sandbox-hero-copy h1 {
  max-width: 485px;
  margin: 0;
  color: var(--sandbox-ink);
  font-size: 48px;
  font-weight: 700;
  letter-spacing: -0.8px;
  line-height: 48px;
}
.sandbox-hero-copy > p {
  max-width: 560px;
  margin: 30px 0 32px;
  color: var(--sandbox-muted);
  font-size: clamp(18px, 1.65vw, 23px);
  line-height: 1.42;
}
.sandbox-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
}
.sandbox-actions .marketing-button {
  min-height: 44px;
  padding-inline: 18px;
  background: var(--sandbox-indigo);
  border-color: var(--sandbox-indigo);
}
.sandbox-actions .marketing-button:hover {
  background: var(--sandbox-indigo-dark);
  border-color: var(--sandbox-indigo-dark);
}
.sandbox-actions .marketing-button-outline {
  color: #344059;
  background: #fff;
  border-color: #cfd6e2;
}
.sandbox-hero-art {
  position: relative;
  display: grid;
  align-items: center;
  min-width: 0;
}
.sandbox-hero-art::before {
  position: absolute;
  inset: 12% -13% -10% 8%;
  z-index: -1;
  background: radial-gradient(circle, rgb(217 192 255 / 60%), transparent 68%);
  content: "";
  filter: blur(12px);
}
.sandbox-browser-frame,
.sandbox-demo-stage-browser {
  overflow: hidden;
  border: 1px solid rgb(214 220 236 / 92%);
  border-radius: 20px;
  background: #fff;
  box-shadow: 0 24px 62px rgb(42 49 107 / 16%);
}
.sandbox-browser-frame {
  transform: rotate(0.25deg);
  transition:
    transform 240ms ease,
    box-shadow 240ms ease;
}
.sandbox-browser-frame:hover {
  transform: translateY(-4px) rotate(0.25deg);
  box-shadow: 0 30px 72px rgb(42 49 107 / 20%);
}
.sandbox-browser-bar,
.sandbox-demo-stage-bar {
  display: flex;
  align-items: center;
  gap: 7px;
  min-height: 42px;
  padding: 0 15px;
  color: #69758a;
  background: #f7f8fb;
  border-bottom: 1px solid #e8ebf1;
  font-size: 11px;
}
.sandbox-browser-bar > span,
.sandbox-demo-stage-bar > span {
  width: 9px;
  height: 9px;
  background: #e7a2a2;
  border-radius: 50%;
}
.sandbox-browser-bar > span:nth-child(2),
.sandbox-demo-stage-bar > span:nth-child(2) {
  background: #e4bc76;
}
.sandbox-browser-bar > span:nth-child(3),
.sandbox-demo-stage-bar > span:nth-child(3) {
  background: #8ccba2;
}
.sandbox-browser-bar div,
.sandbox-demo-stage-bar div {
  width: min(58%, 280px);
  margin-inline: auto;
  padding: 5px 12px;
  overflow: hidden;
  color: #8a94a5;
  background: #edf0f5;
  border-radius: 999px;
  text-align: center;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.sandbox-browser-frame > img {
  display: block;
  width: 100%;
  aspect-ratio: 1.54 / 1;
  object-fit: cover;
  object-position: center;
}
.sandbox-trust-rail {
  padding: 64px max(32px, calc((100vw - 1216px) / 2)) 72px;
  color: #fff;
  background: #202b3b;
}
.sandbox-trust-heading {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: 40px;
  max-width: 1216px;
  margin: 0 auto 34px;
}
.sandbox-trust-heading h2 {
  max-width: 640px;
  margin: 0;
  font-size: 48px;
  letter-spacing: normal;
  line-height: 48px;
}
.sandbox-trust-awards {
  display: flex;
  align-items: center;
  gap: 18px;
}
.sandbox-trust-awards img {
  display: block;
  width: 168px;
  max-width: 100%;
  height: 88px;
  object-fit: contain;
}
.sandbox-trust-chooser {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  max-width: 1216px;
  margin: 0 auto 12px;
  color: #a7b0c2;
  font-size: 13px;
}
.sandbox-trust-chooser details {
  position: relative;
}
.sandbox-trust-chooser summary {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  padding: 8px 12px;
  color: #e9edf7;
  background: #303b4d;
  border: 1px solid #475368;
  border-radius: 8px;
  cursor: pointer;
  list-style: none;
}
.sandbox-trust-chooser summary::-webkit-details-marker {
  display: none;
}
.sandbox-trust-chooser summary::after {
  content: "⌄";
  font-size: 14px;
}
.sandbox-trust-chooser-menu {
  position: absolute;
  top: calc(100% + 7px);
  left: 50%;
  z-index: 3;
  display: grid;
  min-width: 170px;
  gap: 3px;
  padding: 7px;
  background: #fff;
  border-radius: 10px;
  box-shadow: 0 16px 38px rgb(0 0 0 / 24%);
  transform: translateX(-50%);
}
.sandbox-trust-chooser-menu a {
  padding: 8px 9px;
  color: #2c3750;
  border-radius: 6px;
  font-size: 12px;
