/* RouteHub feature page: the live page uses a centered dotted hero, a calculation
   surface, and large editorial feature rows. Keep the motion restrained and let
   the native details controls remain usable with keyboard and reduced motion. */
.route-hub-page {
  --route-ink: #111a2f;
  --route-muted: #536078;
  --route-soft: #f6f7ff;
  --route-line: #dfe4ec;
  --route-indigo: #4a4cec;
  --route-indigo-dark: #3437c4;
  --marketing-blue: var(--route-indigo);
  --marketing-blue-dark: var(--route-indigo-dark);
  color: var(--route-ink);
  background: #fff;
}

.route-hub-page h1,
.route-hub-page h2,
.route-hub-page h3,
.route-hub-page h4 {
  color: var(--route-ink);
  font-family: "degularFont", Inter, ui-sans-serif, system-ui, sans-serif;
  letter-spacing: -0.055em;
}

.route-hub-page .marketing-public-chrome {
  position: relative;
  z-index: 10;
  background: #fff;
}

.route-hub-page .marketing-nav {
  color: var(--route-ink);
}

.route-hub-page .marketing-nav-actions .marketing-button-small,
.route-hub-page .marketing-nav-actions .marketing-button-small:hover,
.route-hub-page .marketing-nav-actions .marketing-button-small:focus-visible {
  color: #fff;
  background: var(--route-indigo);
  border-color: var(--route-indigo);
}

.route-hub-hero {
  position: relative;
  overflow: hidden;
  background-color: #fff;
  background-image: radial-gradient(#dfe2ed 1px, transparent 1px);
  background-size: 14px 14px;
}

.route-hub-hero::after {
  position: absolute;
  inset: 42% -15% 0;
  z-index: 0;
  background: linear-gradient(180deg, rgb(255 255 255 / 5%), #fff 78%);
  content: "";
  pointer-events: none;
}

.route-hub-hero-inner {
  position: relative;
  z-index: 1;
  max-width: 1180px;
  margin: 0 auto;
  padding: 96px 32px 14px;
  text-align: center;
}

.route-hub-hero-copy {
  max-width: 800px;
  margin: 0 auto;
}

.route-hub-hero-badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 7px 13px;
  color: #3741bb;
  background: rgb(232 234 255 / 76%);
  border: 1px solid #c9ccff;
  border-radius: 999px;
  font-size: 13px;
  font-weight: 750;
  letter-spacing: 0.01em;
}

.route-hub-hero-badge span {
  display: grid;
  width: 18px;
  height: 18px;
  place-items: center;
  color: #fff;
  background: var(--route-indigo);
  border-radius: 50%;
  font-size: 13px;
}

.route-hub-hero h1 {
  max-width: 820px;
  margin: 28px auto 0;
  font-size: clamp(48px, 4.6vw, 60px);
  line-height: 0.96;
}

.route-hub-hero-copy > p {
  max-width: 700px;
  margin: 28px auto 0;
  color: var(--route-muted);
  font-size: 19px;
  line-height: 1.45;
}

.route-hub-hero-actions {
  display: flex;
  justify-content: center;
  gap: 12px;
  margin-top: 30px;
}

.route-hub-hero-actions .marketing-button {
  min-height: 46px;
}

.route-hub-hero-art {
  max-width: 1000px;
  margin: 58px auto 0;
  padding: 10px 10px 0;
  background: #fff;
  border: 1px solid #dfe3ef;
  border-bottom: 0;
  border-radius: 22px 22px 0 0;
  box-shadow: 0 28px 60px rgb(44 54 115 / 16%);
}

.route-hub-browser-frame,
.route-hub-demo-browser {
  overflow: hidden;
  background: #eef1f8;
  border: 1px solid #d4d9e6;
  border-radius: 14px 14px 0 0;
}

.route-hub-browser-bar {
  display: flex;
  align-items: center;
  gap: 7px;
  min-height: 34px;
  padding: 0 12px;
  color: #818ba0;
  background: #f7f8fb;
  font-size: 11px;
}

.route-hub-browser-bar span {
  width: 8px;
  height: 8px;
  background: #f2a2a2;
  border-radius: 50%;
}

.route-hub-browser-bar span:nth-child(2) {
  background: #f5d487;
}

.route-hub-browser-bar span:nth-child(3) {
  background: #9ad8b0;
}

.route-hub-browser-bar div {
  margin: 0 auto;
}

.route-hub-browser-frame img {
  display: block;
  width: 100%;
  aspect-ratio: 1.5 / 1;
  object-fit: cover;
  object-position: top center;
}

.route-hub-roi {
  padding: 162px 32px 13px;
  background: linear-gradient(180deg, #fff 0%, #fafaff 100%);
}

.route-hub-roi-heading {
  max-width: 780px;
  margin: 0 auto 42px;
  text-align: center;
}

.route-hub-eyebrow {
  margin: 0 0 14px;
  color: var(--route-indigo);
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.route-hub-roi-heading h2 {
  margin: 0;
  font-size: clamp(42px, 5vw, 64px);
  line-height: 0.98;
}

.route-hub-roi-heading h2 span {
  color: var(--route-indigo);
}

.route-hub-roi-heading > p:last-child {
  margin: 22px auto 0;
  color: var(--route-muted);
  font-size: 18px;
}

.route-hub-calculator {
  max-width: 1088px;
  margin: 0 auto;
}

.route-hub-calculator-tabs {
  width: max-content;
  display: flex;
  justify-content: center;
  gap: 7px;
  margin: 0 auto 9px;
  padding: 4px;
  background: rgb(255 255 255 / 72%);
  border: 1px solid #dfe2eb;
  border-radius: 999px;
}

.route-hub-calculator-tabs button,
.route-hub-confidence button {
  min-height: 38px;
  padding: 0 17px;
  color: #6e7890;
  background: transparent;
  border: 1px solid transparent;
  border-radius: 999px;
  font: inherit;
  font-size: 13px;
  font-weight: 700;
  cursor: pointer;
  transition:
    color 180ms ease,
    background-color 180ms ease,
    border-color 180ms ease,
    transform 180ms ease;
}

.route-hub-calculator-tabs button:hover,
.route-hub-calculator-tabs button:focus-visible,
.route-hub-confidence button:hover,
.route-hub-confidence button:focus-visible {
  color: var(--route-indigo);
  border-color: #c8ccff;
}

.route-hub-calculator-tabs button.is-active,
.route-hub-confidence button.is-active {
  color: var(--route-indigo);
  background: #fff;
  border-color: #d6d9ef;
  box-shadow: 0 4px 12px rgb(35 42 108 / 10%);
}

.route-hub-calculator-context {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  min-height: 23px;
  margin: 0 0 23px;
  color: #818ba0;
  font-size: 13px;
  text-align: center;
}

.route-hub-calculator-context strong {
  color: var(--route-ink);
}

.route-hub-calculator-grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
  gap: 48px;
}

.route-hub-metrics-card,
.route-hub-result-card {
  min-height: 535px;
  padding: 32px;
  background: #fff;
  border: 1px solid var(--route-line);
  border-radius: 22px;
  box-shadow: 0 12px 28px rgb(46 57 115 / 8%);
}

.route-hub-result-card {
  background: linear-gradient(145deg, #f2f2ff 0%, #e8eaff 100%);
  border-color: #d4d6fb;
}

.route-hub-card-heading {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 14px;
}

.route-hub-card-kicker {
  margin: 0 0 5px;
  color: #8992a5;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.route-hub-card-heading h3 {
  margin: 0;
  font-size: 31px;
  line-height: 1;
}

.route-hub-metrics-card .route-hub-card-heading {
  display: block;
}

.route-hub-confidence-block {
  display: grid;
  gap: 9px;
  margin-top: 19px;
}

.route-hub-confidence-block > span {
  color: #5e6980;
  font-size: 13px;
  font-weight: 700;
}

.route-hub-confidence {
  display: flex;
  gap: 3px;
  padding: 3px;
  background: #f4f5fa;
  border: 1px solid #e2e5ed;
  border-radius: 999px;
}

.route-hub-confidence button {
  min-height: 30px;
  padding: 0 9px;
  font-size: 10px;
  text-transform: capitalize;
}

.route-hub-metrics-fields {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 18px 14px;
  margin-top: 30px;
}

.route-hub-metrics-fields label {
  display: grid;
  gap: 8px;
  color: #5e6980;
  font-size: 13px;
  font-weight: 700;
}

.route-hub-metric-wide {
  grid-column: 1 / -1;
}

.route-hub-metrics-fields input {
  width: 100%;
  min-height: 44px;
  padding: 0 13px;
  color: var(--route-ink);
  background: #fff;
  border: 1px solid #d6dce8;
  border-radius: 10px;
  font: inherit;
  font-size: 16px;
  font-weight: 600;
  outline: none;
  transition:
    border-color 180ms ease,
    box-shadow 180ms ease;
}

.route-hub-metrics-fields input:focus {
  border-color: #8c91ff;
  box-shadow: 0 0 0 3px rgb(74 76 236 / 14%);
}

.route-hub-input-with-suffix {
  display: flex;
  align-items: center;
  overflow: hidden;
  min-height: 44px;
  color: #7b8497;
  background: #fff;
  border: 1px solid #d6dce8;
  border-radius: 10px;
}

.route-hub-input-with-suffix:focus-within {
  border-color: #8c91ff;
  box-shadow: 0 0 0 3px rgb(74 76 236 / 14%);
}

.route-hub-input-with-suffix input {
  min-height: 42px;
  padding-inline: 12px 8px;
  border: 0;
  border-radius: 0;
  box-shadow: none;
}

.route-hub-input-with-suffix > span {
  padding-inline: 12px;
  font-size: 14px;
  font-weight: 700;
}

.route-hub-advanced-assumptions {
  margin-top: 28px;
  padding-top: 20px;
  border-top: 1px solid #e8ebf1;
}

.route-hub-advanced-assumptions summary {
  color: var(--route-indigo);
  font-size: 13px;
  font-weight: 800;
  cursor: pointer;
}

.route-hub-advanced-assumptions p {
  max-width: 430px;
  margin: 12px 0 0;
  color: #7b8497;
  font-size: 13px;
  line-height: 1.5;
}

.route-hub-result-badge {
  padding: 6px 10px;
  color: #4b52c5;
  background: #fff;
  border: 1px solid #d5d7fc;
  border-radius: 999px;
  font-size: 11px;
  font-weight: 800;
  text-transform: capitalize;
}

.route-hub-result-card .route-hub-card-heading {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}

.route-hub-arr-block {
  display: grid;
  gap: 8px;
  margin-top: 0;
}

.route-hub-arr-block span,
.route-hub-result-stats span {
  color: #68748b;
  font-size: 13px;
  font-weight: 700;
}

.route-hub-arr-block strong {
  color: var(--route-indigo-dark);
  font-family: "degularFont", Inter, ui-sans-serif, system-ui, sans-serif;
  font-size: clamp(55px, 7vw, 78px);
  letter-spacing: -0.06em;
  line-height: 0.8;
}

.route-hub-result-stats {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 18px;
  margin-top: 34px;
  padding: 18px 0;
  border-block: 1px solid rgb(104 113 205 / 20%);
}

.route-hub-result-stats div {
  display: grid;
  gap: 5px;
}

.route-hub-result-stats strong {
  color: var(--route-ink);
  font-family: "degularFont", Inter, ui-sans-serif, system-ui, sans-serif;
  font-size: 30px;
  line-height: 1;
}

.route-hub-drivers {
  margin-top: 23px;
}

.route-hub-drivers h4 {
  margin: 0;
  font-size: 16px;
  letter-spacing: -0.025em;
}

.route-hub-drivers ul {
  display: grid;
  gap: 8px;
  margin: 13px 0 0;
  padding: 0 0 0 17px;
  color: #68748b;
  font-size: 13px;
  line-height: 1.4;
}

.route-hub-copy-link {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  min-height: 34px;
  margin-top: 26px;
  padding: 0 12px;
  color: var(--route-indigo-dark);
  background: #fff;
  border: 1px solid #d7d9f4;
  border-radius: 8px;
  font: inherit;
  font-size: 12px;
  font-weight: 800;
  cursor: pointer;
  transition:
    transform 180ms ease,
    box-shadow 180ms ease;
}

.route-hub-copy-link:hover,
.route-hub-copy-link:focus-visible {
  box-shadow: 0 5px 15px rgb(50 55 145 / 14%);
  transform: translateY(-1px);
}

.route-hub-disclaimer {
  margin: 15px 0 0;
  color: #8b94a6;
  font-size: 11px;
}

.route-hub-feature-sections {
  padding: 88px 32px 118px;
  background: #fff;
}

.route-hub-feature-row {
  display: grid;
  grid-template-columns: minmax(0, 0.95fr) minmax(0, 1.05fr);
  align-items: center;
  gap: 64px;
  max-width: 1216px;
  margin: 0 auto;
  padding: 94px 0;
}

.route-hub-feature-row + .route-hub-feature-row {
  border-top: 1px solid #eef0f4;
}

.route-hub-feature-row.is-reversed {
  grid-template-columns: minmax(0, 1.05fr) minmax(0, 0.95fr);
}

.route-hub-feature-row.is-reversed .route-hub-feature-copy {
  order: 2;
}

.route-hub-feature-row.is-reversed .route-hub-feature-media {
  order: 1;
}

.route-hub-feature-copy h2 {
  max-width: 480px;
  margin: 0;
  font-size: clamp(30px, 2.6vw, 35px);
  line-height: 0.96;
}

.route-hub-feature-copy > p:not(.route-hub-eyebrow):not(.route-hub-feature-subcopy) {
  max-width: 500px;
  margin: 25px 0 0;
  color: var(--route-muted);
  font-size: 17px;
  line-height: 1.55;
}

.route-hub-feature-subcopy {
  max-width: 500px;
  margin: 18px 0 0;
  color: #28334b;
  font-size: 15px;
  font-weight: 700;
  line-height: 1.5;
}

.route-hub-feature-cta {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  margin-top: 28px;
  color: var(--route-indigo);
  font-size: 14px;
  font-weight: 800;
  text-decoration: none;
}

.route-hub-feature-cta:hover,
.route-hub-feature-cta:focus-visible {
  text-decoration: underline;
  text-underline-offset: 4px;
}

.route-hub-feature-media {
  overflow: hidden;
  min-height: 360px;
  background: #f0f1ff;
  border: 1px solid #dce0ef;
  border-radius: 22px;
  box-shadow: 0 18px 40px rgb(40 49 105 / 12%);
}

.route-hub-feature-media img {
  display: block;
  width: 100%;
  height: 100%;
  min-height: 360px;
  object-fit: cover;
}

.route-hub-demo-stage {
  padding: 122px 32px 132px;
  background: #f7f8ff;
}

.route-hub-demo-heading {
  max-width: 720px;
  margin: 0 auto 42px;
  text-align: center;
}

.route-hub-demo-heading h2 {
  margin: 0;
  font-size: clamp(43px, 5vw, 63px);
  line-height: 0.97;
}

.route-hub-demo-heading > p:last-child {
  margin: 20px auto 0;
  color: var(--route-muted);
  font-size: 17px;
  line-height: 1.5;
}

.route-hub-demo-browser {
  position: relative;
  max-width: 1040px;
  margin: 0 auto;
  padding: 10px 10px 0;
  background: #fff;
  border-color: #dce1ef;
  border-radius: 20px 20px 0 0;
  box-shadow: 0 25px 60px rgb(35 45 106 / 16%);
}

.route-hub-demo-browser > img {
  display: block;
  width: 100%;
  aspect-ratio: 2 / 1;
  object-fit: cover;
  object-position: top center;
}

.route-hub-demo-overlay {
  position: absolute;
  top: 51%;
  left: 50%;
  display: inline-flex;
  align-items: center;
  gap: 9px;
  min-height: 46px;
  padding: 0 19px;
  color: #fff;
  background: var(--route-indigo);
  border-radius: 10px;
  box-shadow: 0 10px 24px rgb(67 69 210 / 32%);
  font-size: 14px;
  font-weight: 800;
  text-decoration: none;
  transform: translate(-50%, -50%);
  transition:
    transform 180ms ease,
    box-shadow 180ms ease;
}

.route-hub-demo-overlay:hover,
.route-hub-demo-overlay:focus-visible {
  box-shadow: 0 14px 30px rgb(67 69 210 / 42%);
  transform: translate(-50%, calc(-50% - 2px));
}

.route-hub-explore {
  max-width: 1120px;
  margin: 0 auto;
  padding: 108px 32px 120px;
}

.route-hub-explore h2 {
  margin: 0;
  font-size: clamp(39px, 4vw, 57px);
  line-height: 0.96;
}

.route-hub-explore-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 26px;
  margin-top: 45px;
}

.route-hub-explore-grid h3 {
  margin: 0 0 16px;
  color: #69748b;
  font-family: Inter, ui-sans-serif, system-ui, sans-serif;
  font-size: 12px;
  letter-spacing: 0.07em;
  text-transform: uppercase;
}

.route-hub-explore-links {
  display: grid;
  gap: 10px;
}

.route-hub-explore-links a {
  color: #28334b;
  font-size: 14px;
  line-height: 1.35;
  text-decoration: none;
  transition:
    color 180ms ease,
    transform 180ms ease;
}

.route-hub-explore-links a:hover,
.route-hub-explore-links a:focus-visible {
  color: var(--route-indigo);
  transform: translateX(2px);
}

.route-hub-faq {
  display: grid;
  grid-template-columns: minmax(230px, 0.72fr) minmax(0, 1.28fr);
  gap: clamp(48px, 8vw, 118px);
  max-width: 1120px;
  margin: 0 auto;
  padding: 118px 32px 128px;
  border-top: 1px solid #eef0f4;
}

.route-hub-faq-intro h2 {
  margin: 0;
  font-size: clamp(48px, 6vw, 76px);
  line-height: 0.88;
}

.route-hub-faq-intro > p:not(.route-hub-eyebrow) {
  max-width: 320px;
  margin: 22px 0 0;
  color: var(--route-muted);
  font-size: 15px;
  line-height: 1.55;
}

.route-hub-faq-intro img {
  display: block;
  width: 200px;
  margin-top: 45px;
}

.route-hub-faq-list {
  border-top: 1px solid #dfe4ec;
}

.route-hub-faq-list details {
  border-bottom: 1px solid #dfe4ec;
}

.route-hub-faq-list summary {
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 78px;
  padding: 0 5px;
  color: var(--route-ink);
  font-size: 16px;
  font-weight: 750;
  list-style: none;
  cursor: pointer;
}

.route-hub-faq-list summary::-webkit-details-marker {
  display: none;
}

.route-hub-faq-list summary::after {
  flex: 0 0 auto;
  margin-left: 16px;
  color: var(--route-indigo);
  content: "+";
  font-size: 25px;
  font-weight: 400;
  transition: transform 180ms ease;
}

.route-hub-faq-list details[open] summary::after {
  transform: rotate(45deg);
}

.route-hub-faq-list details p {
  max-width: 620px;
  margin: -4px 45px 23px 5px;
  color: var(--route-muted);
  font-size: 14px;
  line-height: 1.55;
}

@media (max-width: 900px) {
  .route-hub-hero-inner {
    padding-top: 75px;
  }

  .route-hub-calculator-grid,
  .route-hub-feature-row,
  .route-hub-feature-row.is-reversed {
    grid-template-columns: 1fr;
  }

  .route-hub-feature-row.is-reversed .route-hub-feature-copy,
  .route-hub-feature-row.is-reversed .route-hub-feature-media {
    order: initial;
  }

  .route-hub-feature-copy {
    max-width: 680px;
  }

  .route-hub-feature-media,
  .route-hub-feature-media img {
    min-height: 0;
    aspect-ratio: 1.46 / 1;
  }

  .route-hub-explore-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 720px) {
  .route-hub-page .marketing-announcement-strip > a + a {
    display: none;
  }

  .route-hub-page .marketing-announcement-strip > a {
    flex-basis: 100%;
    min-height: 38px;
    padding-inline: 16px;
  }

  .route-hub-page .marketing-nav {
    width: calc(100% - 40px);
  }

  .route-hub-page .marketing-nav nav,
  .route-hub-page .marketing-nav-actions > a:first-child,
  .route-hub-page .marketing-nav-actions .marketing-button-outline {
    display: none;
  }

  .route-hub-page .marketing-nav-actions .marketing-mobile-menu {
    display: block;
  }

  .route-hub-hero-inner {
    padding: 62px 20px 0;
  }

  .route-hub-hero h1 {
    margin-top: 22px;
    font-size: 50px;
    line-height: 0.93;
  }

  .route-hub-hero-copy > p {
    margin-top: 20px;
    font-size: 16px;
  }

  .route-hub-hero-actions {
    flex-wrap: wrap;
    margin-top: 24px;
  }

  .route-hub-hero-actions .marketing-button {
    min-height: 42px;
    padding-inline: 13px;
    font-size: 13px;
  }

  .route-hub-hero-art {
    margin-top: 52px;
    padding: 7px 7px 0;
    border-radius: 15px 15px 0 0;
  }

  .route-hub-browser-frame img {
    aspect-ratio: 1.58 / 1;
  }

  .route-hub-roi {
    padding: 74px 20px 82px;
  }

  .route-hub-roi-heading h2 {
    font-size: 46px;
  }

  .route-hub-roi-heading > p:last-child {
    font-size: 16px;
  }

  .route-hub-calculator-tabs {
    justify-content: flex-start;
    overflow-x: auto;
    margin-inline: -8px;
    padding: 2px 8px 7px;
  }

  .route-hub-calculator-tabs button {
    flex: 0 0 auto;
    padding-inline: 13px;
  }

  .route-hub-calculator-grid {
    gap: 14px;
  }

  .route-hub-metrics-card,
  .route-hub-result-card {
    min-height: 0;
    padding: 23px 19px;
    border-radius: 17px;
  }

  .route-hub-card-heading h3 {
    font-size: 27px;
  }

  .route-hub-confidence {
    gap: 0;
  }

  .route-hub-confidence button {
    padding-inline: 6px;
    font-size: 9px;
  }

  .route-hub-metrics-fields {
    gap: 14px 10px;
    margin-top: 22px;
  }

  .route-hub-metrics-fields label {
    font-size: 12px;
  }

  .route-hub-arr-block {
    margin-top: 34px;
  }

  .route-hub-arr-block strong {
    font-size: 60px;
  }

  .route-hub-feature-sections {
    padding: 45px 20px 72px;
  }

  .route-hub-feature-row {
    gap: 34px;
    padding: 62px 0;
  }

  .route-hub-feature-copy h2 {
    font-size: 44px;
  }

  .route-hub-feature-copy > p:not(.route-hub-eyebrow):not(.route-hub-feature-subcopy) {
    margin-top: 19px;
    font-size: 16px;
  }

  .route-hub-feature-media {
    border-radius: 16px;
  }

  .route-hub-demo-stage {
    padding: 77px 20px 82px;
  }

  .route-hub-demo-heading h2 {
    font-size: 46px;
  }

  .route-hub-demo-heading > p:last-child {
    font-size: 16px;
  }

  .route-hub-demo-browser {
    padding: 6px 6px 0;
    border-radius: 14px 14px 0 0;
  }

  .route-hub-demo-overlay {
    min-height: 40px;
    padding-inline: 13px;
    font-size: 12px;
  }

  .route-hub-explore {
    padding: 72px 20px 82px;
  }

  .route-hub-explore h2 {
    font-size: 43px;
  }

  .route-hub-explore-grid {
    grid-template-columns: 1fr;
    gap: 31px;
    margin-top: 34px;
  }

  .route-hub-faq {
    grid-template-columns: 1fr;
    gap: 42px;
    padding: 78px 20px 86px;
  }

  .route-hub-faq-intro h2 {
    font-size: 58px;
  }

  .route-hub-faq-intro img {
    width: 170px;
    margin-top: 32px;
  }

  .route-hub-faq-list summary {
    min-height: 70px;
    font-size: 15px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .route-hub-page * {
    scroll-behavior: auto !important;
    animation: none !important;
    transition: none !important;
  }
}

/* Analytics feature page. The reference page uses a light analytics hero,
   navy feature band, and pill-led use-case/explore surfaces. */
.analytics-page {
  --analytics-ink: #111a3a;
  --analytics-muted: #58647d;
  --analytics-indigo: #4b42df;
  --analytics-navy: #07156f;
  --analytics-line: #dfe3ec;
  --marketing-blue: var(--analytics-indigo);
  --marketing-blue-dark: #3730b8;
  color: var(--analytics-ink);
  background: #fff;
}

.analytics-page h1,
.analytics-page h2,
.analytics-page h3,
.analytics-page h4 {
  color: var(--analytics-ink);
  font-family: "degularFont", Inter, ui-sans-serif, system-ui, sans-serif;
  letter-spacing: -0.055em;
}

.analytics-page .marketing-public-chrome {
  position: relative;
  z-index: 10;
  background: #fff;
}

.analytics-page .marketing-nav-actions .marketing-button-small,
.analytics-page .marketing-nav-actions .marketing-button-small:hover,
.analytics-page .marketing-nav-actions .marketing-button-small:focus-visible {
  color: #fff;
  background: var(--analytics-indigo);
  border-color: var(--analytics-indigo);
}

.analytics-hero {
  position: relative;
  overflow: hidden;
  min-height: 676px;
  background:
    radial-gradient(circle at 6% 20%, rgb(208 194 255 / 76%), transparent 27%),
    radial-gradient(circle at 92% 88%, rgb(235 196 255 / 76%), transparent 27%), #fff;
}

.analytics-hero::before,
.analytics-hero::after {
  position: absolute;
  width: 420px;
  height: 420px;
  border-radius: 50%;
  filter: blur(56px);
  opacity: 0.34;
  pointer-events: none;
  content: "";
}

.analytics-hero::before {
  top: -180px;
  left: -190px;
  background: #d5c6ff;
}

.analytics-hero::after {
  right: -180px;
  bottom: -190px;
  background: #f1c9ff;
}

.analytics-hero-inner {
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-columns: minmax(0, 0.95fr) minmax(0, 1.05fr);
  align-items: center;
  gap: 58px;
  max-width: 1216px;
  min-height: 676px;
  margin: 0 auto;
  padding: 72px 32px 60px;
}

.analytics-hero-copy {
  max-width: 535px;
  transform: translateY(-45px);
}

.analytics-hero-copy h1 {
  max-width: 500px;
  margin: 0;
  font-size: clamp(48px, 4.25vw, 57px);
  line-height: 0.94;
}

.analytics-hero-copy > p {
  max-width: 515px;
  margin: 28px 0 0;
  color: var(--analytics-muted);
  font-size: 20px;
  line-height: 1.43;
}

.analytics-hero-actions {
  display: flex;
  gap: 12px;
  margin-top: 30px;
}

.analytics-hero-actions .marketing-button {
  min-height: 44px;
}

.analytics-hero-art {
  position: relative;
  justify-self: end;
  width: min(100%, 510px);
  padding-top: 46px;
  transform: translateX(32px);
}

.analytics-hero-art-label {
  position: absolute;
  top: 0;
  left: 23%;
  display: inline-flex;
  align-items: center;
  gap: 9px;
  min-height: 39px;
  padding: 0 17px;
  color: #fff;
  background: linear-gradient(135deg, #5635cf, #683ce8);
  border-radius: 9px;
  box-shadow: 0 12px 22px rgb(75 54 213 / 27%);
  font-size: 12px;
  font-weight: 800;
}

.analytics-hero-art-label span {
  font-size: 18px;
}

.analytics-hero-art img {
  display: block;
  width: 100%;
  border-radius: 15px;
  filter: drop-shadow(0 20px 24px rgb(40 40 126 / 18%));
  transform: translateY(-69px);
}

.analytics-feature-band {
  padding: 38px 0 72px;
  background: var(--analytics-navy);
}

.analytics-feature-list {
  display: grid;
  gap: 24px;
}

.analytics-feature-card {
  display: grid;
  grid-template-columns: minmax(0, 1.22fr) minmax(0, 0.78fr);
  align-items: center;
  gap: 60px;
  width: calc(100% - 128px);
  max-width: 1152px;
  min-height: 545px;
  margin: 0 auto;
  padding: 40px;
  background: #fff;
  border-radius: 24px;
}

.analytics-feature-card.is-reversed {
  grid-template-columns: minmax(0, 0.78fr) minmax(0, 1.22fr);
}

.analytics-feature-card.is-reversed .analytics-feature-copy {
  order: 2;
}

.analytics-feature-card.is-reversed .analytics-feature-media {
  order: 1;
}

.analytics-feature-copy {
  max-width: 670px;
}

.analytics-feature-copy h2 {
  margin: 0;
  font-size: clamp(32px, 3.15vw, 43px);
  line-height: 0.98;
}

.analytics-feature-copy > p {
  max-width: 650px;
  margin: 22px 0 0;
  color: var(--analytics-muted);
  font-size: 17px;
  line-height: 1.47;
}

.analytics-tag-list {
  display: flex;
  flex-wrap: wrap;
  gap: 9px;
  margin-top: 24px;
}

.analytics-tag-list span {
  padding: 7px 13px;
  color: #4c576d;
  background: #fff;
  border: 1px solid #d3d8e3;
  border-radius: 999px;
  font-size: 12px;
  line-height: 1;
}

.analytics-row-cta {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-height: 42px;
  margin-top: 27px;
  padding: 0 16px;
  color: #4b5364;
  background: #fff;
  border: 1px solid #d1d7e0;
  border-radius: 9px;
  box-shadow: 0 2px 4px rgb(15 23 42 / 7%);
  font-size: 14px;
  font-weight: 700;
  text-decoration: none;
  transition:
    color 180ms ease,
    border-color 180ms ease,
    transform 180ms ease;
}

.analytics-row-cta:hover,
.analytics-row-cta:focus-visible {
  color: var(--analytics-indigo);
  border-color: #9897e9;
  transform: translateY(-1px);
}

.analytics-feature-media {
  display: grid;
  min-height: 335px;
  place-items: center;
}

.analytics-feature-media img {
  display: block;
  width: 100%;
  max-height: 366px;
  object-fit: contain;
  filter: drop-shadow(0 14px 22px rgb(40 42 93 / 12%));
}

.analytics-use-cases {
  padding: 104px 32px 116px;
  background: #eef0ff;
}

.analytics-use-cases-inner {
  max-width: 1152px;
  margin: 0 auto;
}

.analytics-use-cases h2 {
  max-width: 750px;
  margin: 0;
  font-size: clamp(39px, 4.2vw, 58px);
  line-height: 0.96;
}

.analytics-use-case-tabs {
  margin-top: 44px;
}

.analytics-use-case-tab-list {
  display: flex;
  gap: 8px;
  overflow-x: auto;
  padding-bottom: 8px;
  border-bottom: 1px solid #cbd1e4;
}

.analytics-use-case-tab-list button {
  flex: 0 0 auto;
  min-height: 38px;
  padding: 0 14px;
  color: #667189;
  background: transparent;
  border: 0;
  border-radius: 8px 8px 0 0;
  font: inherit;
  font-size: 13px;
  font-weight: 750;
  cursor: pointer;
  transition:
    color 180ms ease,
    background-color 180ms ease;
}

.analytics-use-case-tab-list button.is-active,
.analytics-use-case-tab-list button:hover,
.analytics-use-case-tab-list button:focus-visible {
  color: var(--analytics-indigo);
  background: #fff;
}

.analytics-use-case-panel {
  display: grid;
  grid-template-columns: minmax(0, 0.95fr) minmax(0, 1.05fr);
  align-items: center;
  gap: 44px;
  min-height: 360px;
  margin-top: 28px;
  padding: 30px 36px;
  background: #fff;
  border: 1px solid #dde1ef;
  border-radius: 22px;
}

.analytics-use-case-copy h3 {
  margin: 0;
  font-size: 41px;
  line-height: 0.97;
}

.analytics-use-case-copy p {
  margin: 20px 0 0;
  color: var(--analytics-muted);
  font-size: 17px;
  line-height: 1.5;
}

.analytics-use-case-copy a {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  margin-top: 25px;
  color: var(--analytics-indigo);
  font-size: 14px;
  font-weight: 800;
  text-decoration: none;
}

.analytics-use-case-copy a:hover,
.analytics-use-case-copy a:focus-visible {
  text-decoration: underline;
  text-underline-offset: 4px;
}

.analytics-use-case-media {
  display: grid;
  min-height: 280px;
  place-items: center;
}

.analytics-use-case-media img {
  display: block;
  width: 100%;
  max-height: 310px;
  object-fit: contain;
}

.analytics-explore {
  padding: 96px 32px 110px;
  background: #f7f8fb;
}

.analytics-explore > h2,
.analytics-explore-grid {
  max-width: 1088px;
  margin-right: auto;
  margin-left: auto;
}

.analytics-explore > h2 {
  margin-top: 0;
  margin-bottom: 40px;
  font-size: clamp(38px, 4vw, 55px);
  line-height: 0.98;
}

.analytics-explore-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 25px;
  padding: 36px;
  background: #fff;
  border: 1px solid #e0e4ed;
  border-radius: 23px;
}

.analytics-explore-grid h3 {
  margin: 0 0 14px;
  color: var(--analytics-ink);
  font-family: Inter, ui-sans-serif, system-ui, sans-serif;
  font-size: 15px;
  letter-spacing: -0.025em;
}

.analytics-explore-links {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.analytics-explore-links a {
  padding: 7px 11px;
  color: #59647a;
  background: #f7f8fb;
  border: 1px solid #e1e4ec;
  border-radius: 999px;
  font-size: 12px;
  line-height: 1;
  text-decoration: none;
  transition:
    color 180ms ease,
    border-color 180ms ease,
    transform 180ms ease;
}

.analytics-explore-links a:hover,
.analytics-explore-links a:focus-visible {
  color: var(--analytics-indigo);
  border-color: #a3a2eb;
  transform: translateY(-1px);
}

.analytics-faq {
  padding: 112px 32px 132px;
  background: linear-gradient(180deg, #f0f1ff 0%, #fff 42%);
}

.analytics-faq-inner {
  display: grid;
  grid-template-columns: minmax(235px, 0.65fr) minmax(0, 1.35fr);
  gap: 90px;
  max-width: 1152px;
  margin: 0 auto;
}

.analytics-faq-intro h2 {
  margin: 0;
  font-size: clamp(52px, 6vw, 78px);
  line-height: 0.88;
}

.analytics-faq-intro p {
  max-width: 320px;
  margin: 22px 0 0;
  color: var(--analytics-muted);
  font-size: 15px;
  line-height: 1.55;
}

.analytics-faq-intro img {
  display: block;
  width: 190px;
  margin-top: 46px;
}

.analytics-faq-list {
  border-top: 1px solid #d7dce8;
}

.analytics-faq-list details {
  border-bottom: 1px solid #d7dce8;
}

.analytics-faq-list summary {
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 76px;
  padding: 0 4px;
  color: var(--analytics-ink);
  font-size: 16px;
  font-weight: 750;
  list-style: none;
  cursor: pointer;
}

.analytics-faq-list summary::-webkit-details-marker {
  display: none;
}

.analytics-faq-list summary::after {
  margin-left: 16px;
  color: var(--analytics-indigo);
  content: "+";
  font-size: 26px;
  font-weight: 400;
  transition: transform 180ms ease;
}

.analytics-faq-list details[open] summary::after {
  transform: rotate(45deg);
}

.analytics-faq-list details p {
  max-width: 680px;
  margin: -2px 40px 23px 4px;
  color: var(--analytics-muted);
  font-size: 14px;
  line-height: 1.55;
}

@media (max-width: 980px) {
  .analytics-hero-inner {
    grid-template-columns: 1fr;
    gap: 45px;
    padding-top: 66px;
  }

  .analytics-hero-copy {
    max-width: 720px;
    transform: none;
  }

  .analytics-hero-art {
    justify-self: start;
    max-width: 620px;
    transform: none;
  }

  .analytics-feature-card,
  .analytics-feature-card.is-reversed {
    grid-template-columns: minmax(0, 1fr);
    gap: 30px;
  }

  .analytics-feature-card.is-reversed .analytics-feature-copy,
  .analytics-feature-card.is-reversed .analytics-feature-media {
    order: initial;
  }

  .analytics-feature-copy {
    max-width: 740px;
  }

  .analytics-feature-media {
    min-height: 280px;
  }

  .analytics-explore-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 720px) {
  .analytics-page .marketing-announcement-strip > a + a {
    display: none;
  }

  .analytics-page .marketing-announcement-strip > a {
    flex-basis: 100%;
    min-height: 38px;
    padding-inline: 16px;
  }

  .analytics-page .marketing-nav {
    width: calc(100% - 40px);
  }

  .analytics-page .marketing-nav nav,
  .analytics-page .marketing-nav-actions > a:first-child,
  .analytics-page .marketing-nav-actions .marketing-button-outline {
    display: none;
  }

  .analytics-page .marketing-nav-actions .marketing-mobile-menu {
    display: block;
  }

  .analytics-hero {
    min-height: 0;
  }

  .analytics-hero-inner {
    min-height: 0;
    padding: 65px 20px 57px;
  }

  .analytics-hero-copy h1 {
    font-size: 51px;
  }

  .analytics-hero-copy > p {
    margin-top: 20px;
    font-size: 17px;
  }

  .analytics-hero-actions {
    flex-wrap: wrap;
    gap: 8px;
    margin-top: 23px;
  }

  .analytics-hero-actions .marketing-button {
    min-height: 42px;
    padding-inline: 13px;
    font-size: 13px;
  }

  .analytics-hero-art {
    padding-top: 37px;
    transform: none;
  }

  .analytics-hero-art img {
    transform: none;
  }

  .analytics-hero-art-label {
    left: 18%;
    min-height: 34px;
    padding-inline: 12px;
    font-size: 11px;
  }

  .analytics-feature-band {
    padding: 20px 0 54px;
  }

  .analytics-feature-card,
  .analytics-feature-card.is-reversed {
    width: calc(100% - 40px);
    min-height: 0;
    gap: 25px;
    padding: 24px;
    border-radius: 18px;
  }

  .analytics-feature-copy h2 {
    font-size: 35px;
  }

  .analytics-feature-copy > p {
    margin-top: 17px;
    font-size: 15px;
  }

  .analytics-feature-media {
    min-height: 190px;
  }

  .analytics-feature-media img {
    max-height: 230px;
  }

  .analytics-use-cases {
    padding: 72px 20px 78px;
  }

  .analytics-use-cases h2 {
    font-size: 44px;
  }

  .analytics-use-case-tabs {
    margin-top: 32px;
  }

  .analytics-use-case-panel {
    grid-template-columns: 1fr;
    gap: 22px;
    min-height: 0;
    margin-top: 21px;
    padding: 23px;
    border-radius: 17px;
  }

  .analytics-use-case-copy h3 {
    font-size: 37px;
  }

  .analytics-use-case-copy p {
    margin-top: 16px;
    font-size: 15px;
  }

  .analytics-use-case-media {
    min-height: 180px;
  }

  .analytics-explore {
    padding: 70px 20px 78px;
  }

  .analytics-explore > h2 {
    margin-bottom: 30px;
    font-size: 43px;
  }

  .analytics-explore-grid {
    grid-template-columns: 1fr;
    gap: 30px;
    padding: 24px;
    border-radius: 18px;
  }

  .analytics-faq {
    padding: 79px 20px 88px;
  }

  .analytics-faq-inner {
    grid-template-columns: 1fr;
    gap: 42px;
  }

  .analytics-faq-intro h2 {
    font-size: 59px;
  }

  .analytics-faq-intro img {
    width: 165px;
    margin-top: 32px;
  }

  .analytics-faq-list summary {
    min-height: 70px;
    font-size: 15px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .analytics-page * {
    scroll-behavior: auto !important;
    animation: none !important;
    transition: none !important;
  }
}

/* In-app Demo Hub parity page */
.demo-hub-page {
  --demo-hub-ink: #121a2d;
  --demo-hub-muted: #556176;
  --demo-hub-indigo: #4b46e8;
  --demo-hub-dark: #1d2735;
  overflow: hidden;
  background: #fff;
  color: var(--demo-hub-ink);
}

.demo-hub-page .marketing-button {
  border-color: var(--demo-hub-indigo);
  background: var(--demo-hub-indigo);
  color: #fff;
}

.demo-hub-page .marketing-button:hover,
.demo-hub-page .marketing-button:focus-visible {
  border-color: #3732c7;
  background: #3732c7;
}

.demo-hub-page .marketing-button-outline,
.demo-hub-page .marketing-button-outline:hover,
.demo-hub-page .marketing-button-outline:focus-visible {
  border-color: #d8dce8;
  background: #fff;
  color: #33405a;
}

.demo-hub-page .marketing-nav-actions .marketing-button-small,
.demo-hub-page .marketing-nav-actions .marketing-button-small:hover,
.demo-hub-page .marketing-nav-actions .marketing-button-small:focus-visible {
  border-color: var(--demo-hub-indigo);
  background: var(--demo-hub-indigo);
  color: #fff;
}

.demo-hub-page h1,
.demo-hub-page h2,
.demo-hub-page h3,
.demo-hub-page h4,
.demo-hub-page p {
  margin: 0;
}

.demo-hub-hero {
  position: relative;
  overflow: hidden;
  padding: 134px 24px 153px;
  background: #fff;
}

.demo-hub-hero-dots {
  position: absolute;
  inset: 0 0 41%;
  pointer-events: none;
  background-image: radial-gradient(circle, rgba(67, 56, 85, 0.12) 0.8px, transparent 0.9px);
  background-size: 12px 12px;
  opacity: 0.8;
  mask-image: linear-gradient(to bottom, #000 0%, #000 78%, transparent 100%);
}

.demo-hub-hero-inner {
  position: relative;
  z-index: 1;
  max-width: 1152px;
  margin: 0 auto;
  text-align: center;
}

.demo-hub-hero-copy {
  max-width: 1030px;
  margin: 0 auto;
}

.demo-hub-hero-badge {
  display: inline-flex;
  align-items: center;
  min-height: 38px;
  padding: 7px 16px;
  border: 1px solid #ccd3e8;
  border-radius: 12px;
  background: linear-gradient(135deg, #fff, #eef2ff);
  color: #35458e;
  font-size: 14px;
  font-weight: 650;
  text-decoration: none;
  box-shadow: 0 5px 18px rgba(67, 75, 145, 0.08);
}

.demo-hub-hero h1 {
  max-width: 900px;
  margin: 27px auto 0;
  color: var(--demo-hub-ink);
  font-family: var(--font-display, Inter, sans-serif);
  font-size: clamp(48px, 4.6vw, 60px);
  font-weight: 750;
  letter-spacing: -0.07em;
  line-height: 1.04;
}

.demo-hub-hero-copy > p {
  max-width: 830px;
  margin: 17px auto 0;
  color: #4d576a;
  font-size: 21px;
  line-height: 1.42;
}

.demo-hub-hero-actions {
  display: flex;
  justify-content: center;
  gap: 12px;
  margin-top: 29px;
}

.demo-hub-hero-actions .marketing-button {
  gap: 8px;
}

.demo-hub-hero-media {
  width: min(805px, 100%);
  margin: 73px auto 0;
  overflow: hidden;
  border: 1px solid #e0e4ef;
  border-radius: 26px;
  background: #c7c9ca;
  box-shadow: 0 22px 45px rgba(23, 34, 56, 0.17);
  animation: demo-hub-rise 650ms cubic-bezier(0.22, 1, 0.36, 1) both;
}

.demo-hub-hero-media img {
  display: block;
  width: 100%;
  aspect-ratio: 805 / 475;
  object-fit: cover;
}

.demo-hub-examples {
  position: relative;
  z-index: 1;
  max-width: 1104px;
  margin: 76px auto 0;
  padding: 16px;
  border: 1px solid #e2e6f0;
  border-radius: 22px;
  background: #fff;
  box-shadow: 0 15px 32px rgba(50, 57, 88, 0.12);
}

.demo-hub-examples-inner {
  padding: 0 10px 8px;
}

.demo-hub-examples-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 42px;
}

.demo-hub-examples-heading img {
  width: 130px;
  height: auto;
}

.demo-hub-examples-heading button {
  width: 34px;
  height: 34px;
  border: 0;
  border-radius: 50%;
  background: #f1f3f8;
  color: #748096;
  font-size: 24px;
  line-height: 1;
  cursor: pointer;
}

.demo-hub-example-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 14px;
  margin-top: 8px;
}

.demo-hub-example-card {
  position: relative;
  display: flex;
  min-height: 210px;
  flex-direction: column;
  align-items: flex-start;
  justify-content: space-between;
  padding: 24px 26px 22px;
  border: 1px solid #e1e5ee;
  border-radius: 13px;
  background: #fff;
  color: #596579;
  text-decoration: none;
  transition:
    transform 180ms ease,
    border-color 180ms ease,
    box-shadow 180ms ease;
}

.demo-hub-example-card:hover,
.demo-hub-example-card:focus-visible {
  border-color: #aab4de;
  box-shadow: 0 10px 24px rgba(63, 71, 126, 0.12);
