/* Showcase Collection parity page. The reference uses a quiet dotted hero,
   a navy trust rail, and large white cards for each multi-demo workflow. */
.showcase-page {
  --showcase-ink: #111a30;
  --showcase-muted: #566279;
  --showcase-indigo: #4b46e8;
  --showcase-navy: #011369;
  overflow: hidden;
  color: var(--showcase-ink);
  background: #fff;
}

.showcase-page h1,
.showcase-page h2,
.showcase-page h3,
.showcase-page h4,
.showcase-page p {
  margin: 0;
}

.showcase-page h1,
.showcase-page h2,
.showcase-page h3,
.showcase-page h4 {
  font-family: "degularFont", Inter, ui-sans-serif, system-ui, sans-serif;
  letter-spacing: -0.055em;
}

.showcase-page .marketing-public-chrome {
  position: relative;
  z-index: 10;
  background: #fff;
}

.showcase-page .marketing-button {
  border-color: var(--showcase-indigo);
  background: var(--showcase-indigo);
  color: #fff;
}

.showcase-page .marketing-button:hover,
.showcase-page .marketing-button:focus-visible {
  border-color: #3732c7;
  background: #3732c7;
}

.showcase-page .marketing-button-outline,
.showcase-page .marketing-button-outline:hover,
.showcase-page .marketing-button-outline:focus-visible {
  border-color: #d8dce8;
  background: #fff;
  color: #33405a;
}

.showcase-page .marketing-nav-actions .marketing-button-small,
.showcase-page .marketing-nav-actions .marketing-button-small:hover,
.showcase-page .marketing-nav-actions .marketing-button-small:focus-visible {
  border-color: var(--showcase-indigo);
  background: var(--showcase-indigo);
  color: #fff;
}

.showcase-hero {
  position: relative;
  overflow: hidden;
  height: auto;
  padding: 134px 24px 150px;
  background: #fff;
}

.showcase-hero-dots {
  position: absolute;
  inset: 0 0 35%;
  pointer-events: none;
  background-image: radial-gradient(circle, rgb(67 56 85 / 13%) 0.8px, transparent 0.9px);
  background-size: 12px 12px;
  opacity: 0.8;
  mask-image: linear-gradient(to bottom, #000 0%, #000 78%, transparent 100%);
}

.showcase-hero-inner {
  position: relative;
  z-index: 1;
  max-width: 1152px;
  margin: 0 auto;
  text-align: center;
}

.showcase-hero-copy {
  max-width: 1000px;
  margin: 0 auto;
}

.showcase-hero-badge {
  display: inline-flex;
  align-items: center;
  min-height: 38px;
  padding: 7px 16px;
  border: 1px solid #ccd3e8;
  border-radius: 12px;
  background: linear-gradient(135deg, #fff, #eef2ff);
  color: #35458e;
  font-size: 14px;
  font-weight: 650;
  text-decoration: none;
  box-shadow: 0 5px 18px rgb(67 75 145 / 8%);
}

.showcase-hero h1 {
  max-width: 920px;
  margin: 30px auto 0;
  font-size: clamp(50px, 5.1vw, 67px);
  line-height: 0.93;
}

.showcase-hero-copy > p {
  max-width: 850px;
