/* Sharing feature parity page. The reference uses a soft editorial hero,
   indigo feature band, alternating white cards, and compact FAQ disclosures. */
.sharing-page {
  --sharing-ink: #111827;
  --sharing-muted: #4b5563;
  --sharing-indigo: #444ce7;
  --sharing-indigo-dark: #3538cd;
  --sharing-navy: #07156f;
  overflow: hidden;
  color: var(--sharing-ink);
  background: #fff;
}

.sharing-page h1,
.sharing-page h2,
.sharing-page h3,
.sharing-page p {
  margin: 0;
}

.sharing-page h1,
.sharing-page h2,
.sharing-page h3 {
  font-family: "degularFont", Inter, ui-sans-serif, system-ui, sans-serif;
  letter-spacing: normal;
}

.sharing-page .marketing-public-chrome {
  position: relative;
  z-index: 10;
  background: #fff;
}

/* The reference keeps the announcement in document flow and floats the
   navigation over the hero. Keeping the chrome on the same layer preserves
   the 41px hero start and lets the artwork sit underneath the nav. */
.sharing-page .marketing-public-chrome {
  height: 41px;
}

.sharing-page .marketing-nav {
  position: absolute;
  z-index: 20;
  top: 48px;
  right: 0;
  left: 0;
  width: min(1280px, 100%);
  min-height: 96px;
  padding: 16px 32px;
  margin-right: auto;
  margin-left: auto;
  background: transparent;
}

.sharing-page .marketing-nav nav {
  gap: 4px;
}

.sharing-page .marketing-nav nav > a,
.sharing-page .marketing-menu > summary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 10px 15px;
}

.sharing-page .marketing-nav nav > :nth-child(1) {
  width: 101.195px;
}

.sharing-page .marketing-nav nav > :nth-child(2) {
  width: 107.25px;
}

.sharing-page .marketing-nav nav > :nth-child(3) {
  width: 115.406px;
}

.sharing-page .marketing-nav nav > :nth-child(4) {
  width: 71.484px;
}

.sharing-page .marketing-nav nav > :nth-child(5) {
  width: 61.43px;
}

.sharing-page .marketing-nav-actions .marketing-button {
  min-height: 40px;
  padding: 8px 12px;
  gap: 4px;
  border-radius: 12px;
  font-size: 14px;
  font-weight: 450;
  line-height: 20px;
}

.sharing-page .marketing-nav-actions {
  gap: 8px;
  margin-left: 12px;
}

.sharing-page .marketing-nav-actions .marketing-button-outline {
  width: 135.484px;
}

.sharing-page .marketing-nav-actions .marketing-button-small {
  width: 136.914px;
}

.sharing-page .marketing-button {
  border-color: var(--sharing-indigo);
  background: var(--sharing-indigo);
  color: #fff;
}

.sharing-page .marketing-button:hover,
.sharing-page .marketing-button:focus-visible {
  border-color: var(--sharing-indigo-dark);
  background: var(--sharing-indigo-dark);
}

.sharing-page .marketing-button-outline,
.sharing-page .marketing-button-outline:hover,
.sharing-page .marketing-button-outline:focus-visible {
  border: 0 solid #e5e7eb;
  background: #fff;
  color: #414651;
  box-shadow:
    0 1px 2px rgb(10 13 18 / 5%),
    inset 0 -2px 0 rgb(10 13 18 / 5%),
    inset 0 0 0 1px rgb(10 13 18 / 18%);
}

.sharing-page .marketing-nav-actions .marketing-button-small,
.sharing-page .marketing-nav-actions .marketing-button-small:hover,
.sharing-page .marketing-nav-actions .marketing-button-small:focus-visible {
  border-color: var(--sharing-indigo);
  background: var(--sharing-indigo);
  color: #fff;
}

.sharing-hero {
  position: relative;
  min-height: 676px;
  overflow: hidden;
  padding: 160px 32px 96px;
  background:
    radial-gradient(circle at 6% 20%, rgb(208 194 255 / 76%), transparent 27%),
    radial-gradient(circle at 92% 88%, rgb(235 196 255 / 76%), transparent 27%), #fff;
}

.sharing-hero-glow {
  position: absolute;
  width: 384px;
  height: 384px;
  border-radius: 50%;
  filter: blur(48px);
  opacity: 0.3;
  pointer-events: none;
}

.sharing-hero-glow-left {
  top: -96px;
  left: -96px;
  background: linear-gradient(135deg, #a78bfa, #818cf8);
}

.sharing-hero-glow-right {
  right: -96px;
  bottom: -96px;
  background: linear-gradient(135deg, #f0abfc, #c084fc);
}

.sharing-hero-inner {
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  gap: 64px;
  align-items: center;
  width: min(1216px, 100%);
  height: 420px;
  margin: 0 auto;
}

.sharing-hero-copy {
  grid-column: span 3;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  justify-content: center;
}

.sharing-hero-copy h1 {
  max-width: 500px;
  color: #000;
  font-size: 48px;
  font-weight: 700;
  line-height: 48px;
}

.sharing-hero-copy > p {
  max-width: 480px;
  margin-top: 28px;
  color: var(--sharing-muted);
  font-size: 20px;
  line-height: 28px;
}

.sharing-hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  margin-top: 30px;
}

.sharing-hero-actions .marketing-button {
  min-height: 40px;
  padding: 8px 12px;
  gap: 4px;
  font-size: 14px;
  font-weight: 450;
  line-height: 20px;
  border-radius: 12px;
  box-shadow:
    0 1px 2px rgb(10 13 18 / 5%),
    inset 0 -2px 0 rgb(10 13 18 / 5%),
    inset 0 0 0 1px rgb(10 13 18 / 18%);
}

.sharing-hero-actions .marketing-button span[aria-hidden] {
  display: inline-grid;
  width: 20px;
  height: 20px;
  place-items: center;
  font-size: 20px;
  line-height: 20px;
}

.sharing-hero-actions .sharing-hero-label {
  padding-inline: 3px;
}

.sharing-hero-actions .marketing-button:first-child .sharing-hero-label {
  padding-inline: 4px;
}

.sharing-hero-art {
  grid-column: span 4;
  position: relative;
  display: flex;
  justify-content: flex-end;
  height: 420px;
  animation: sharing-hero-float 8s ease-in-out infinite;
}

.sharing-hero-art img {
  display: block;
  width: 100%;
  height: 420px;
  object-fit: contain;
  object-position: right center;
}

.sharing-feature-band {
  padding: 96px 32px;
  background: var(--sharing-navy);
}

.sharing-feature-list {
  width: min(1216px, 100%);
  margin: 0 auto;
}

.sharing-feature-row {
  min-height: 545.2px;
  padding: 32px 0;
}

.sharing-feature-card {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 48px;
  align-items: center;
  width: min(1152px, 100%);
  min-height: 481.2px;
  margin: 0 auto;
  padding: 40px;
  background: #fff;
  border: 1px solid #e5e7eb;
  border-radius: 24px;
  box-shadow: 0 8px 22px rgb(1 19 105 / 10%);
  transition:
    transform 240ms var(--ease-standard),
    box-shadow 240ms var(--ease-standard);
}

.sharing-feature-card:hover {
  transform: translateY(-3px);
  box-shadow: 0 16px 32px rgb(1 19 105 / 16%);
}

.sharing-feature-media {
  grid-column: 1 / span 2;
  position: relative;
  aspect-ratio: 1;
  overflow: hidden;
  border-radius: 24px;
  background: #eeeaff;
}

.sharing-feature-media img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: left top;
  transition: transform 360ms var(--ease-standard);
}

.sharing-feature-card:hover .sharing-feature-media img {
  transform: scale(1.025);
}

.sharing-feature-copy {
  grid-column: 3 / span 3;
}

.sharing-feature-row.is-reversed .sharing-feature-media {
  grid-column: 4 / span 2;
  grid-row: 1;
}

.sharing-feature-row.is-reversed .sharing-feature-copy {
  grid-column: 1 / span 3;
  grid-row: 1;
}

.sharing-feature-copy h2 {
  color: #111827;
  font-size: 30px;
  font-weight: 700;
  line-height: 36px;
}

.sharing-feature-copy > p {
  margin-top: 16px;
  color: var(--sharing-muted);
  font-size: 16px;
  line-height: 24px;
}

.sharing-tag-list {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 32px;
}

.sharing-tag-list span {
  display: inline-flex;
  align-items: center;
  min-height: 30px;
  padding: 6px 12px;
  color: #374151;
  background: #fff;
  border: 1px solid #d1d5db;
  border-radius: 999px;
  font-size: 12px;
  font-weight: 500;
  line-height: 18px;
}

.sharing-row-cta {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  min-height: 40px;
  margin-top: 32px;
  padding: 0 12px;
  color: #414651;
  background: #fff;
  border: 1px solid #d5d7da;
  border-radius: 12px;
  box-shadow: 0 1px 2px rgb(16 24 40 / 6%);
  font-size: 14px;
  font-weight: 450;
  text-decoration: none;
  transition:
    color 180ms ease,
    border-color 180ms ease,
    transform 180ms ease;
}

.sharing-row-cta:hover,
.sharing-row-cta:focus-visible {
  color: var(--sharing-indigo);
  border-color: #9897e9;
  transform: translateY(-1px);
}

.sharing-explore {
  min-height: 584px;
  padding: 64px 32px;
  background: #f9fafb;
}

.sharing-explore-panel {
  width: min(1152px, 100%);
  min-height: 456px;
  margin: 0 auto;
  padding: 48px;
  background: #fff;
  border: 1px solid #e5e7eb;
  border-radius: 24px;
}

.sharing-explore-panel > h2,
.sharing-explore-grid {
  width: min(1024px, 100%);
  margin-right: auto;
  margin-left: auto;
  padding-right: 32px;
  padding-left: 32px;
}

.sharing-explore-panel > h2 {
  margin-top: 0;
  margin-bottom: 32px;
  color: #1f2937;
  font-family: Inter, ui-sans-serif, system-ui, sans-serif;
  font-size: 24px;
  font-weight: 700;
  line-height: 32px;
  letter-spacing: -0.02em;
}

.sharing-explore-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 32px;
}

.sharing-explore-category {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  color: #111827;
  font-size: 16px;
  font-weight: 700;
  line-height: 24px;
  text-decoration: none;
}

.sharing-explore-category > span:last-child {
  color: #9ca3af;
  transition:
    color 180ms ease,
    transform 180ms ease;
}

.sharing-explore-category:hover,
.sharing-explore-category:focus-visible {
  color: var(--sharing-indigo);
}

.sharing-explore-category:hover > span:last-child,
.sharing-explore-category:focus-visible > span:last-child {
  color: var(--sharing-indigo);
  transform: translateX(3px);
}

.sharing-explore-links {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 12px;
}

.sharing-explore-links a {
  padding: 6px 11.75px;
  color: #374151;
  background: linear-gradient(135deg, #fff, #eef2ff);
  border: 1px solid #d1d5db;
  border-radius: 999px;
  font-family: Inter, system-ui, arial, ui-sans-serif, system-ui, sans-serif;
  font-size: 12px;
  font-weight: 500;
  line-height: 16px;
  text-decoration: none;
  transition:
    color 180ms ease,
    border-color 180ms ease;
}

.sharing-explore-links a:hover,
.sharing-explore-links a:focus-visible {
  color: var(--sharing-indigo);
  border-color: #a5b4fc;
}

.sharing-faq {
  min-height: 880px;
  padding: 96px 32px;
  background: linear-gradient(180deg, #fff 0%, rgb(238 242 255 / 30%) 42%, #fff 100%);
}

.sharing-faq-inner {
  display: grid;
  grid-template-columns: minmax(0, 408px) minmax(0, 712px);
  gap: 96px;
  width: min(1216px, 100%);
  min-height: 688px;
  margin: 0 auto;
}

.sharing-faq-intro {
  align-self: start;
  padding-top: 0;
}

.sharing-faq-intro h2 {
  color: #111827;
  font-size: 48px;
  font-weight: 700;
  line-height: 48px;
}

.sharing-faq-intro > p {
  max-width: 408px;
  margin-top: 22px;
  color: var(--sharing-muted);
  font-size: 18px;
  line-height: 28px;
}

.sharing-faq-intro img {
  display: block;
  width: 320px;
  max-width: 100%;
  margin-top: 52px;
}

.sharing-faq-list {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.sharing-faq-item {
  overflow: hidden;
  padding: 20px 32px;
  color: #111827;
  background: rgb(238 242 255 / 80%);
  border-radius: 16px;
  transition: background-color 180ms ease;
}

.sharing-faq-item[open] {
  padding-top: 32px;
  padding-bottom: 32px;
}

.sharing-faq-item summary {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  min-height: 54px;
  color: #111827;
  font-size: 18px;
  font-weight: 600;
  line-height: 27px;
  cursor: pointer;
  list-style: none;
}

.sharing-faq-question {
  display: block;
  width: 100%;
  max-width: 24rem;
}

.sharing-faq-item summary::-webkit-details-marker {
  display: none;
}

.sharing-faq-item summary::after {
  display: grid;
  width: 40px;
  height: 40px;
  flex: 0 0 40px;
  place-items: center;
  color: #3730a3;
  background: #e0e7ff;
  border-radius: 12px;
  content: "+";
  font-size: 26px;
  font-weight: 400;
  line-height: 1;
}

.sharing-faq-item[open] summary::after {
  content: "–";
}

.sharing-faq-item > p {
  margin-top: 16px;
  color: #374151;
  font-family: Inter, system-ui, arial, ui-sans-serif, system-ui, sans-serif;
  font-size: 16px;
  font-weight: 500;
  line-height: 26px;
}

@keyframes sharing-hero-float {
  0%,
  100% {
    transform: translateY(0);
  }
  50% {
    transform: translateY(-4px);
  }
}

@media (max-width: 980px) {
  .sharing-hero-inner {
    gap: 36px;
  }

  .sharing-hero-copy h1 {
    font-size: 44px;
    line-height: 44px;
  }

  .sharing-feature-card {
    gap: 32px;
  }

  .sharing-explore-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .sharing-faq-inner {
    grid-template-columns: minmax(0, 300px) minmax(0, 1fr);
    gap: 56px;
  }
}

@media (max-width: 720px) {
  .sharing-page .marketing-announcement-strip > a + a {
    display: none;
  }

  .sharing-page .marketing-announcement-strip > a {
    flex-basis: 100%;
    min-height: 38px;
    padding-inline: 16px;
  }

  .sharing-page .marketing-nav {
    width: calc(100% - 40px);
  }

  .sharing-page .marketing-nav nav,
  .sharing-page .marketing-nav-actions > a:first-child,
  .sharing-page .marketing-nav-actions .marketing-button-outline {
    display: none;
  }

  .sharing-page .marketing-nav-actions .marketing-mobile-menu {
    display: block;
  }

  .sharing-hero {
    min-height: auto;
    padding: 64px 20px 72px;
  }

  .sharing-hero-inner {
    display: grid;
    grid-template-columns: 1fr;
    gap: 36px;
    width: 100%;
    height: auto;
  }

  .sharing-hero-copy,
  .sharing-hero-art {
    grid-column: auto;
  }

  .sharing-hero-copy h1 {
    font-size: 46px;
    line-height: 0.96;
  }

  .sharing-hero-copy > p {
    margin-top: 22px;
    font-size: 17px;
    line-height: 25px;
  }

  .sharing-hero-actions {
    gap: 8px;
    margin-top: 23px;
  }

  .sharing-hero-actions .marketing-button {
    min-height: 42px;
    padding-inline: 13px;
    font-size: 13px;
  }

  .sharing-hero-art {
    height: auto;
    animation: none;
  }

  .sharing-hero-art img {
    height: auto;
    max-height: 310px;
    object-fit: contain;
  }

  .sharing-feature-band {
    padding: 64px 20px;
  }

  .sharing-feature-row {
    min-height: 0;
    padding: 16px 0;
  }

  .sharing-feature-card,
  .sharing-feature-row.is-reversed .sharing-feature-card {
    grid-template-columns: 1fr;
    gap: 28px;
    min-height: 0;
    padding: 23px;
    border-radius: 17px;
  }

  .sharing-feature-media,
  .sharing-feature-row.is-reversed .sharing-feature-media,
  .sharing-feature-copy,
  .sharing-feature-row.is-reversed .sharing-feature-copy {
    grid-column: auto;
    grid-row: auto;
  }

  .sharing-feature-media {
    width: 100%;
  }

  .sharing-feature-copy h2 {
    font-size: 36px;
    line-height: 1;
  }

  .sharing-feature-copy > p {
    margin-top: 17px;
    font-size: 15px;
    line-height: 23px;
  }

  .sharing-tag-list {
    margin-top: 22px;
  }

  .sharing-row-cta {
    margin-top: 24px;
  }

  .sharing-explore {
    min-height: 0;
    padding: 64px 20px;
  }

  .sharing-explore-panel {
    min-height: 0;
    padding: 24px;
    border-radius: 18px;
  }

  .sharing-explore-panel > h2,
  .sharing-explore-grid {
    width: 100%;
    padding: 0;
  }

  .sharing-explore-panel > h2 {
    margin-bottom: 30px;
    font-size: 22px;
  }

  .sharing-explore-grid {
    grid-template-columns: 1fr;
    gap: 30px;
  }

  .sharing-faq {
    min-height: 0;
    padding: 78px 20px 88px;
  }

  .sharing-faq-inner {
    grid-template-columns: 1fr;
    gap: 42px;
    min-height: 0;
  }

  .sharing-faq-intro h2 {
    font-size: 59px;
    line-height: 0.9;
  }

  .sharing-faq-intro > p {
    font-size: 16px;
  }

  .sharing-faq-intro img {
    width: 240px;
    margin-top: 32px;
  }

  .sharing-faq-item {
    padding: 16px 20px;
  }

  .sharing-faq-item[open] {
    padding: 24px 20px;
  }

  .sharing-faq-item summary {
    min-height: 50px;
    font-size: 15px;
    line-height: 22px;
  }

  .sharing-faq-question {
    max-width: none;
  }

  .sharing-faq-item > p {
    font-size: 14px;
    line-height: 22px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .sharing-page * {
    scroll-behavior: auto !important;
    animation: none !important;
    transition: none !important;
  }
}

