  color: #344054;
  font-size: 24px;
  font-style: italic;
  line-height: 32px;
}

.vrify-story-inline-quote cite {
  width: 824px;
  max-width: 100%;
  min-height: 52px;
  margin-top: 16px;
  justify-content: center;
  font-style: normal;
}

.vrify-case-study-faq {
  height: 1040px;
  box-sizing: border-box;
  padding: 96px 32px;
  background: linear-gradient(180deg, #fff, rgb(238 240 255 / 30%), #fff);
}

.vrify-case-study-faq-inner {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 1.25fr);
  gap: 96px;
  width: min(1152px, 100%);
  height: 848px;
  margin: 0 auto;
}

.vrify-case-study-faq-intro {
  display: flex;
  flex-direction: column;
  min-width: 0;
}

.vrify-case-study-faq-intro h2 {
  margin: 0;
  color: #101828;
  font-family: "degularFont", system-ui, sans-serif;
  font-size: 48px;
  line-height: 48px;
}

.vrify-case-study-faq-intro p {
  margin: 16px 0 0;
  color: #667085;
  font-size: 16px;
  line-height: 24px;
}

.vrify-case-study-faq-intro img {
  width: 320px;
  height: 280px;
  margin-top: auto;
  object-fit: contain;
  object-position: left bottom;
}

.vrify-case-study-faq-list {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.vrify-case-study-faq-list details {
  overflow: hidden;
  padding: 20px 32px;
  background: rgb(238 240 255 / 80%);
  border-radius: 16px;
}

.vrify-case-study-faq-list details[open] {
  padding-top: 32px;
  padding-bottom: 32px;
}

.vrify-case-study-faq-list summary {
  display: flex;
  align-items: center;
  justify-content: space-between;
  color: #101828;
  font-size: 16px;
  font-weight: 700;
  line-height: 24px;
  cursor: pointer;
  list-style: none;
}

.vrify-case-study-faq-list summary::-webkit-details-marker {
  display: none;
}

.vrify-case-study-faq-list summary::after {
  flex: 0 0 auto;
  margin-left: 16px;
  color: #4d43cd;
  content: "+";
  font-size: 22px;
  font-weight: 400;
}

.vrify-case-study-faq-list details[open] summary::after {
  content: "–";
}

.vrify-case-study-faq-list details p {
  margin: 16px 0 0;
  color: #667085;
  font-size: 15px;
  line-height: 24px;
}

@media (max-width: 900px) {
  .vrify-case-study-top {
    margin-top: 0;
  }

  .vrify-case-study-hero,
  .vrify-case-study-stats,
  .vrify-case-study-profile,
  .vrify-case-study-content,
  .vrify-case-study-faq {
    height: auto;
  }

  .vrify-case-study-hero {
    padding: 72px 20px 64px;
  }

  .vrify-case-study-hero h1 {
    font-size: clamp(42px, 9vw, 60px);
    line-height: 1;
  }

  .vrify-case-study-hero-media {
    width: 100%;
    height: auto;
    aspect-ratio: 768 / 550;
  }

  .vrify-case-study-stats {
    grid-template-columns: 1fr;
    gap: 12px;
    width: min(100% - 40px, 520px);
    padding-bottom: 64px;
  }

  .vrify-case-study-profile {
    padding: 64px 20px;
  }

  .vrify-case-study-profile-card {
    display: flex;
    height: auto;
    flex-direction: column;
    gap: 36px;
    padding: 32px;
  }

  .vrify-case-study-profile-card dl {
    padding-inline: 0;
  }

  .vrify-case-study-profile-card dd {
    max-width: none;
  }

  .vrify-case-study-content {
    width: min(100% - 40px, 896px);
    padding: 64px 0;
  }

  .vrify-story-block,
  .vrify-story-about,
  .vrify-story-challenge,
  .vrify-story-solution,
  .vrify-story-use,
  .vrify-story-features,
  .vrify-story-results,
  .vrify-story-next {
    height: auto;
    min-height: 0;
  }

  .vrify-story-block + .vrify-story-block {
    margin-top: 64px;
  }

  .vrify-story-image {
    width: 100%;
    height: auto;
    aspect-ratio: 864 / 486;
  }

  .vrify-story-inline-quote {
    height: auto;
    min-height: 278px;
  }

  .vrify-case-study-faq {
    padding: 64px 20px;
  }

  .vrify-case-study-faq-inner {
    display: flex;
    width: min(100%, 896px);
    height: auto;
    flex-direction: column;
    gap: 48px;
  }

  .vrify-case-study-faq-intro img {
    width: 240px;
    height: auto;
    margin-top: 32px;
  }
}
